window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0184", [{"word":"distributor","ipa_uk":"/dɪˈstrɪbjuːtə/","ipa_us":"/dɪˈstrɪbjuːtər/","definition_zh":"经销商；分销商；配电企业；（发动机的）分电器；分发者","definition_en":"a firm or person that supplies goods to shops, or a device that sends current or content out to several points","core_image":"一只总水管分出许多支管，水从一处进来，被均匀送到各个出口","scene":"仓库门口停着几辆货车，一箱箱货被分到不同店铺的车上，每张运货单都写着各自的去处。The distributor sends the cases to shops across the region.","sceneCN":"仓库月台上，货物按店铺分堆装车，一家公司把整批货拆开来分别送往各处；句中的 distributor 指「从生产商进货、再分送给各家店铺的经销商」（第 1 个义项：处在生产商与零售店之间、负责把货物分发出去的一方）。图中可辨识物件：货车、纸箱、运货单、仓库月台。","pos":[{"tag":"n.","zh":"经销商；分销商；分发者"},{"tag":"n.","zh":"配电（或配气）企业"},{"tag":"n.","zh":"（发动机）分电器"}],"collocations":[{"phrase":"authorised distributor","zh":"授权经销商"},{"phrase":"exclusive distributor","zh":"独家经销商"},{"phrase":"local distributor","zh":"本地经销商"},{"phrase":"power distributor","zh":"配电企业"},{"phrase":"film distributor","zh":"电影发行方"},{"phrase":"distributor network","zh":"经销网络"}],"forms":[{"label":"复数","form":"distributors"},{"label":"动词（分发）","form":"distribute"},{"label":"名词（分发、分配）","form":"distribution"},{"label":"形容词（分配的）","form":"distributive"},{"label":"名词（再分配）","form":"redistribution"},{"label":"形容词（可分配的）","form":"distributable"}],"derivatives":[{"word":"distribute","pos":"v.","zh":"分发；分配；配送"},{"word":"distribution","pos":"n.","zh":"分发；分配；分布"},{"word":"distributive","pos":"adj.","zh":"分配的；分发的"},{"word":"redistribute","pos":"v.","zh":"重新分配"},{"word":"redistribution","pos":"n.","zh":"再分配"},{"word":"distributable","pos":"adj.","zh":"可分配的"}],"senses":[{"no":"01","title":"Firm that supplies shops","titleCN":"从生产商进货、再分送给店铺的经销商","definition":"a company that buys goods from producers and sells them on to shops rather than to the public","definitionCN":"从生产商手中进货，再转售给店铺而不是卖给公众的公司","example":"The distributor supplies forty bookshops in the province.","exampleCN":"这家经销商为省内四十家书店供货。","why":"the Latin verb behind it means to deal something out in portions, so the agent noun names the party that hands goods out piece by piece.","whyCN":"其背后的拉丁语动词意为「按份分出」，因此施动名词指把货物一份份发出去的一方。"},{"no":"02","title":"Appointed seller of a brand","titleCN":"获授权在某一地区销售某品牌的商家","definition":"a firm holding the right to sell a particular brand within a territory","definitionCN":"在某一地区内拥有销售某个品牌权利的商家","example":"She became the authorised distributor for the brand in three countries.","exampleCN":"她成为该品牌在三个国家的授权经销商。","why":"an exclusive contract turns an ordinary reseller into the officially appointed channel, and the word follows the contract.","whyCN":"独家合同把普通的转售者变成官方指定的渠道，这个词也随之跟着合同走。"},{"no":"03","title":"Company that releases films","titleCN":"把影片发行到影院的电影发行方","definition":"a company that arranges for a film or recording to reach cinemas and shops","definitionCN":"安排影片或录音制品进入影院与商店的公司","example":"The film's distributor held back the release until spring.","exampleCN":"该片的发行方把上映日期推迟到春天。","why":"films were once physically distributed in reels, so the entertainment trade kept the literal sense of handing copies outward.","whyCN":"影片曾经以成卷胶片实物分发，娱乐业因此保留了「把拷贝发出去」的字面意思。"},{"no":"04","title":"Engine part that routes the spark","titleCN":"把电流轮流送往各火花塞的分电器","definition":"a device in a petrol engine that sends the electric current to each spark plug in turn","definitionCN":"在汽油发动机中把电流依次送往各个火花塞的装置","example":"A worn distributor cap made the engine misfire.","exampleCN":"磨损的分电器盖使发动机点火失常。","why":"the part performs exactly what the name says: it deals one current out to several plugs in a fixed order.","whyCN":"这个部件的功能正如其名：把同一股电流按固定顺序分给几个火花塞。"},{"no":"05","title":"Operator of the local power network","titleCN":"把电或燃气送到用户的配电企业","definition":"a utility that carries electricity or gas from the main grid to individual homes and businesses","definitionCN":"把电力或燃气从主干网输送到各户与各企业的公用事业公司","example":"The local distributor restored power within two hours.","exampleCN":"本地配电企业在两小时内恢复了供电。","why":"the grid has a bulk transmission stage and a local delivery stage; the second stage hands energy to individual users, which is distribution.","whyCN":"电网分为大宗输送与本地配送两个环节，后一个环节把能源交给单个用户，这就是分配。"},{"no":"06","title":"Person who hands things out","titleCN":"把物资或文件分发给他人的办事人员","definition":"a person who gives out supplies, aid or papers to a group of people","definitionCN":"把物资、援助或文件分发给一群人的工作人员","example":"A distributor of aid stood at the gate with a list of names.","exampleCN":"一名负责分发援助物资的人拿着名单站在门口。","why":"the agent noun is older than the commercial sense and applies to any person who deals out shares.","whyCN":"这个施动名词比商业义更早，适用于任何把份例分出去的人。"},{"no":"07","title":"Channel that spreads information","titleCN":"把消息扩散到众人的渠道或机构","definition":"an agency or medium through which news or ideas reach a large audience","definitionCN":"使新闻或观念传达到大量受众的机构或媒介","example":"Social platforms became the main distributor of the rumour.","exampleCN":"社交平台成了这则谣言的主要传播渠道。","why":"the commercial sense widened: what is dealt out need not be goods but attention and information.","whyCN":"商业义发生扩展：被分出去的不必是货物，也可以是注意力与信息。"},{"no":"08","title":"Service that delivers digital goods","titleCN":"把软件或数字内容分发给用户的平台","definition":"a service that makes software, games or digital content available to users","definitionCN":"把软件、游戏或数字内容提供给用户的服务平台","example":"The app distributor takes a share of every sale.","exampleCN":"应用分发平台从每笔销售中抽取一份。","why":"digital goods are copied rather than shipped, yet the middle role survives because access still has to be granted.","whyCN":"数字商品靠复制而不靠运输，但中间角色依然存在，因为获取权限仍需有人授予。"}],"etymology":{"intro":{"en":"Distributor comes from the Latin verb distribuere 'to deal out in portions', built on dis- 'apart' and tribuere 'to allot'. Dates are approximate.","cn":"distributor 来自拉丁语动词 distribuere「按份分出」，由表示「分开」的前缀与表示「分配」的词根构成。年代均为约数。"},"items":[{"era":"LATIN TRIBUERE","en":"Tribuere meant 'to allot, assign, grant'. It is tied to tribus 'a division of the people', the source of the English word tribe; the deeper origin of tribus is not established.","cn":"tribuere 意为「分配、分给、授予」。它与 tribus「人群的划分」相关，后者是英语中「部落」一词的来源；tribus 更早的来源未有定论。"},{"era":"LATIN DISTRIBUERE","en":"Dis- 'apart' plus tribuere produced distribuere 'to divide up, deal out', the direct ancestor of the English verb distribute.","cn":"表示「分开」的前缀加 tribuere 构成 distribuere「分开、按份分出」，它是英语动词 distribute 的直接祖先。"},{"era":"ENGLISH AGENT NOUN","en":"The suffix -or names the one who performs the action, so distributor first meant any person who handed things out.","cn":"后缀表示动作的执行者，因此 distributor 最初指任何把东西分发出去的人。"},{"era":"COMMERCIAL SENSE","en":"In the nineteenth century the word settled on the firm standing between maker and shop, as trade grew too large for direct dealing.","cn":"到十九世纪，随着交易规模大到无法直接买卖，这个词固定指站在制造商与店铺之间的公司。"},{"era":"MACHINE SENSE","en":"The petrol engine gave the word a mechanical branch: an ignition distributor deals one current out to several plugs.","cn":"汽油发动机给这个词添了一条机械分支：分电器把同一股电流分给几个火花塞。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the link between tribuere and tribus is accepted, but the pre-Latin origin of tribus is unsettled, so any older form proposed for it is a reconstruction.","cn":"来源不确定（更深词根）：tribuere 与 tribus 的关联已被接受，但 tribus 在拉丁语之前的来源没有定论，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin root that allot or assign; group two holds near neighbours in the supply chain.","cn":"第一组是同出「分配」这一拉丁词根、都含「分给」意思的词；第二组是供应链上语义相近的角色名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"contribute","ipa":"/kənˈtrɪbjuːt/","tag":"give toward a pool","definition":"Built with the prefix for 'together' and the allotting root: to give a share into a common fund or effort.","definitionCN":"由表示「共同」的前缀与该分配词根构成：把一份力量或钱物放进共同的池子。"},{"word":"attribute","ipa":"/əˈtrɪbjuːt/","tag":"assign a cause","definition":"The prefix for 'to, toward' plus the allotting root: to assign a quality or cause to someone.","definitionCN":"由表示「朝向」的前缀与该分配词根构成：把某种性质或原因归到某人身上。"},{"word":"tribute","ipa":"/ˈtrɪbjuːt/","tag":"something paid or offered","definition":"From the same root, originally a sum allotted or paid to a ruler, later words or acts offered in respect.","definitionCN":"同出该词根，原指分派或缴纳给统治者的款项，后指为表示敬意而献上的言辞或举动。"},{"word":"retribution","ipa":"/ˌretrɪˈbjuːʃn/","tag":"payback","definition":"The prefix for 'back' plus the allotting root: a share dealt back as punishment.","definitionCN":"由表示「回」的前缀与该分配词根构成：作为惩罚被回报的一份。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supplier","ipa":"/səˈplaɪə/","tag":"sells to anyone","definition":"A firm that provides goods, often directly to the user; a distributor specifically resells to shops.","definitionCN":"提供货物、常常直接卖给使用者的公司；distributor 特指转售给店铺的一方。"},{"word":"dealer","ipa":"/ˈdiːlə/","tag":"trades a category","definition":"A person or firm trading in a particular class of goods, such as cars; it does not fix a place in the chain.","definitionCN":"经营某一类商品（如汽车）的个人或公司，并不限定处在链条的哪一环。"},{"word":"vendor","ipa":"/ˈvendə/","tag":"the selling party","definition":"The party that sells in a transaction, whether a market stall or a software company.","definitionCN":"交易中出售的一方，可以是市场摊贩，也可以是软件公司。"},{"word":"middleman","ipa":"/ˈmɪdlmæn/","tag":"stands between","definition":"Any trader between producer and buyer, of which a distributor is one kind.","definitionCN":"任何处于生产者与买家之间的商人，经销商是其中一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real allotting root, the real word family and the real supply-chain phrases.","cn":"正常联想使用真实的「分配」词根、真实词族与真实的供应链搭配。"},"normal":[{"en":"The root means 'to allot': a distributor allots portions of a shipment to different shops.","cn":"词根意为「分配」：经销商把一批货分成份额，分给不同的店铺。"},{"en":"The family moves through distribute, distribution, distributive and redistribution.","cn":"同族词围绕「分配」展开，包括分发、分配、分配的形容词与再分配。"},{"en":"Fixed phrases mark the trade: authorised distributor, exclusive distributor, distributor network.","cn":"固定搭配标出行业义：授权经销商、独家经销商、经销网络。"},{"en":"The same root allots in contribute, attribute, tribute and retribution.","cn":"同一词根在「贡献」「归因」「纳贡」「报应」中也表示分给。"},{"en":"A distributor is not a shop: it sells to shops, and the shop sells to the public.","cn":"经销商不是店铺：它把货卖给店铺，店铺才卖给公众。"}],"abstract":[{"en":"Picture a single pipe splitting into many smaller pipes, each feeding a different street.","cn":"想象一根总管分成许多细管，每根细管通向不同街道。"},{"en":"Picture a hand dealing cards face down to every player at a table.","cn":"想象一只手把牌一张张扣着发给桌边的每位玩家。"},{"en":"Picture a pump that pushes the same current to several lamps in turn.","cn":"想象一台泵把同一股电流轮流推给几盏灯。"}]},"examples":[{"en":"A distributor buys in bulk and never sells a single item to a walk-in customer.","cn":"经销商整批进货，从不把单件商品卖给散客。"},{"en":"The book's distributor ships to shops, while the publisher deals with the author.","cn":"书的发行方把书发给店铺，出版社则与作者打交道。"},{"en":"In an old engine, the distributor decides which plug fires next.","cn":"在老式发动机里，分电器决定下一个点火的是哪个火花塞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「dis（分开）+ tribute（分配）」——把货分开分给各家店 → 经销商、分销商","word":"distributor"},"root":"拉丁语 distribuere（按份分出）＝表示「分开」的前缀＋tribuere（分配、分给）。词根又与 tribus（人群的划分）相关，tribus 更早来源无定论。英语 distributor 由该动词加表施动者的后缀构成。","sensesIntro":{"en":"Eight senses follow one gesture: one quantity is split into portions and sent to several receivers, whether the portions are crates, films, sparks or news.","cn":"八个义项沿同一个动作展开：把一份总量拆成若干份，送往不同的接收者；被拆开的可以是货箱、影片、电火花或消息。"},"semanticMap":{"core":{"en":"CORE IMAGE: one inlet splitting into many outlets, each receiving a share.","cn":"核心意象：一个入口分出许多出口，每个出口各得一份。"},"chain":["DEAL OUT","SPLIT INTO SHARES","GOODS CHANNEL","APPOINTED SELLER","SENDS CURRENT","SPREADS CONTENT"],"branches":[{"senses":"01 · 02","en":"GOODS CHANNEL: goods or brand rights pass from maker to shop through one appointed hand.","cn":"货物渠道：货物或品牌权利经一只被指定的手从制造商流向店铺。"},{"senses":"03 · 08","en":"CONTENT CHANNEL: reels and app downloads are released rather than shipped, yet access is still granted by a middle party.","cn":"内容渠道：胶片与下载不靠运输而靠发行，但获取权限仍由中间方授予。"},{"senses":"04 · 05","en":"CURRENT: sparks and mains power prove that the share being dealt out may be pure energy.","cn":"电流：火花与市电说明，被分出去的份额可以是纯粹的能量。"},{"senses":"06","en":"PERSON: before firms existed, the word simply named a person handing out shares.","cn":"人：在公司出现之前，这个词只指把份额分出去的人。"},{"senses":"07","en":"INFORMATION: attention is the last thing dealt out, and the role survives without any physical goods.","cn":"信息：注意力是最后一种被分出去的东西，角色在没有实物时依然成立。"}]},"affixes":{"intro":{"en":"The word is a Latin prefix, a Latin root and an agent suffix; all three recur in ordinary English.","cn":"这个词由一个拉丁前缀、一个拉丁词根与一个表施动者的后缀组成，三部分都在日常英语中反复出现。"},"latinIntro":{"en":"Latin tribuere gives contribute, attribute, tribute and retribution; the prefix marks separation.","cn":"拉丁语 tribuere 衍生出「贡献」「归因」「纳贡」与「报应」等词；前缀标出「分开」的方向。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart')","meaning":"apart; in different directions","meaningCN":"分开；朝不同方向","example":"The prefix says the portions go to separate places.","exampleCN":"这个前缀表示各份被送往不同地方。"},{"word":"tribuere","structure":"tribuere, tribui, tributum (Latin verb, third conjugation)","meaning":"to allot, assign, grant","meaningCN":"分配；分给；授予","example":"The root carries the idea of handing out shares.","exampleCN":"这个词根带着「分发份额」的意思。"},{"word":"distribuere","structure":"dis- + tribuere (Latin verb)","meaning":"to divide up, deal out","meaningCN":"分开；按份分出","example":"Distribuere names the act behind the English word.","exampleCN":"distribuere 点明英语词背后的动作。"},{"word":"distribute","structure":"distribuere through French","meaning":"to hand out or spread","meaningCN":"分发；分配；散布","example":"Volunteers distribute the kits at the gate.","exampleCN":"志愿者在门口分发物资包。"},{"word":"distribution","structure":"distribute + -ion (act or result)","meaning":"the act or pattern of handing out","meaningCN":"分发（动作或结果）","example":"The distribution of the grant was uneven.","exampleCN":"这笔拨款的分配并不均衡。"},{"word":"distributor","structure":"distribute + -or (one who acts)","meaning":"the one that hands goods out","meaningCN":"把货物分发出去的一方","example":"The distributor supplies forty shops.","exampleCN":"这家经销商为四十家店铺供货。"},{"word":"distributive","structure":"distribute + -ive (having the quality)","meaning":"relating to sharing out","meaningCN":"与分配有关的","example":"The scheme had a distributive aim.","exampleCN":"该方案带有分配方面的目的。"},{"word":"redistribution","structure":"re- + distribution","meaning":"a fresh sharing out","meaningCN":"重新分配","example":"Tax and benefits produce redistribution.","exampleCN":"税收与福利带来再分配。"}],"latinEntries":[{"word":"tribuere","structure":"tribuere, tribui, tributum (verb, third conjugation)","meaning":"to allot, assign","meaningCN":"分配；分给"},{"word":"distribuere","structure":"distribuere, distribui, distributum (verb, third conjugation)","meaning":"to divide up, distribute","meaningCN":"分开；分发"},{"word":"tribus","structure":"tribus, tribus (f., fourth declension)","meaning":"a division of the people, tribe","meaningCN":"人群的划分；部落"}],"derivatives":[{"word":"distribute","pos":"v.","zh":"分发；分配；配送"},{"word":"distribution","pos":"n.","zh":"分发；分配；分布"},{"word":"distributive","pos":"adj.","zh":"分配的；分发的"},{"word":"redistribute","pos":"v.","zh":"重新分配"},{"word":"redistribution","pos":"n.","zh":"再分配"},{"word":"distributable","pos":"adj.","zh":"可分配的"}]}},{"word":"wholesale","ipa_uk":"/ˈhəʊlseɪl/","ipa_us":"/ˈhoʊlseɪl/","definition_zh":"批发；批发业；批发的；以批发价；大规模的、不加区分的","definition_en":"the selling of goods in large lots to shops that will resell them, or action carried out on a large and undiscriminating scale","core_image":"整板货物不拆箱、不零卖，一次整批推走，成交的是一大宗","scene":"天还没亮，整板货物从仓库直接推向等在外面的货车，中间没有人拆开其中一箱。The wholesale price is fixed before the crates leave the yard.","sceneCN":"仓库卷帘门刚升起，整托盘货物被直接推上货车，没有任何一箱被拆开零售；句中的 wholesale 指「以整批数量卖给再销售者、不向最终消费者零售的」（第 1 个义项：整批转售给店铺的交易方式）。图中可辨识物件：托盘、货车、卷帘门、价目单。","pos":[{"tag":"n.","zh":"批发；批发业"},{"tag":"adj.","zh":"批发的；大规模的、不加区分的"},{"tag":"adv.","zh":"以批发方式；以批发价"},{"tag":"v.","zh":"整批出售"}],"collocations":[{"phrase":"wholesale price","zh":"批发价"},{"phrase":"wholesale market","zh":"批发市场"},{"phrase":"wholesale trade","zh":"批发贸易"},{"phrase":"wholesale funding","zh":"批发融资"},{"phrase":"wholesale changes","zh":"大规模改动"},{"phrase":"buy wholesale","zh":"整批买进"}],"forms":[{"label":"三单（整批出售）","form":"wholesales"},{"label":"过去式","form":"wholesaled"},{"label":"过去分词","form":"wholesaled"},{"label":"现在分词","form":"wholesaling"},{"label":"施动者名词","form":"wholesaler"},{"label":"名词（批发业务）","form":"wholesaling"}],"derivatives":[{"word":"wholesaler","pos":"n.","zh":"批发商"},{"word":"wholesaling","pos":"n.","zh":"批发业务"},{"word":"wholesaled","pos":"adj.","zh":"以批发方式售出的"}],"senses":[{"no":"01","title":"Selling whole lots to resellers","titleCN":"整批卖给再销售者而不零售","definition":"the sale of goods in large quantities to shops or traders who will sell them on","definitionCN":"把货物成批卖给店铺或商人，由其继续转售","example":"Wholesale keeps the price low because one crate is never opened.","exampleCN":"批发能把价格压低，因为整箱从不拆开。","why":"the compound joins 'whole' and 'sale', so the original point is that the whole lot is sold at once.","whyCN":"这个复合词由「整」与「卖」合成，原义就是整批一次卖出。"},{"no":"02","title":"The trade as an industry","titleCN":"作为行业的批发业","definition":"the branch of commerce that buys from producers and supplies shops","definitionCN":"从生产者处进货并向店铺供货的商业分支","example":"Wholesale employs fewer people than retail but moves far more stock.","exampleCN":"批发业用人比零售业少，搬动的货却多得多。","why":"once the practice was established, the same word came to name the whole sector that lives by it.","whyCN":"这种做法确立之后，同一个词就用来指靠它生存的整个行业。"},{"no":"03","title":"The bulk price","titleCN":"批量成交时的批发价","definition":"the price charged when goods are bought in large lots rather than singly","definitionCN":"货物成批买进而非单件购买时适用的价格","example":"The wholesale price leaves the shop a narrow margin.","exampleCN":"批发价留给店铺的利润很薄。","why":"price follows quantity: a buyer who takes a whole pallet pays less per unit, and the name of the trade became the name of that price.","whyCN":"价格随数量走：买下整托盘的买家每件付得更少，行业名于是成了这种价格的名。"},{"no":"04","title":"In bulk, as a manner","titleCN":"以整批方式买卖（副词用法）","definition":"by the large lot rather than by the single item","definitionCN":"按大宗而非单件地进行买卖","example":"They buy wholesale and sell retail from the same yard.","exampleCN":"他们在同一个场院里整批买进、零散卖出。","why":"English lets a noun of manner stand as an adverb, so the trade name describes how the dealing is done.","whyCN":"英语允许表方式的名词直接作副词，因此行业名可以直接说明买卖是怎么做的。"},{"no":"05","title":"Done on a large, undiscriminating scale","titleCN":"大规模的、不加区分的（贬义）","definition":"carried out in great numbers without examining each case","definitionCN":"数量巨大而不逐件审视地进行的","example":"The report urged against wholesale demolition of old housing.","exampleCN":"报告反对整片拆除老住宅。","why":"the leap is from 'whole lot' to 'without distinction': when everything goes at once, no item is judged on its own.","whyCN":"词义的跳跃从「整批」到「不加区分」：一次整批处理时，没有哪一件被单独评判。"},{"no":"06","title":"Large transactions between institutions","titleCN":"机构之间的大额融资（金融术语）","definition":"lending and funding arranged in large sums between financial institutions rather than with households","definitionCN":"在金融机构之间而非与家庭进行的大额借贷与融资","example":"The bank leaned on wholesale funding during the credit squeeze.","exampleCN":"信贷紧缩期间，这家银行依赖批发融资。","why":"bankers borrowed the trade word for money raised in big blocks from other firms, as opposed to small deposits from savers.","whyCN":"银行家借用了这个词，指从其他机构成块筹来的钱，以区别于储户的小额存款。"},{"no":"07","title":"The bulk energy market","titleCN":"大宗电力与燃气的批发市场","definition":"the market in which electricity or gas is bought in large blocks before it reaches households","definitionCN":"电力或燃气在到达家庭之前成批买卖的市场","example":"Wholesale electricity prices doubled after the cold snap.","exampleCN":"寒潮过后，批发电价翻了一倍。","why":"energy is sold twice, first in bulk between suppliers and then to homes, and the first stage inherited the trade name.","whyCN":"能源被卖两次，先在供应商之间成批交易，再卖给家庭，前一阶段沿用了这个行业名。"},{"no":"08","title":"Goods or a market at the bulk level","titleCN":"处在整批层面的商品或市场（定语用法）","definition":"goods, markets or buyers that operate at the bulk level of a supply chain","definitionCN":"在供应链的整批层面上运作的商品、市场或买家","example":"Wholesale buyers set the tone for the whole season.","exampleCN":"批发买家为整个季节定下基调。","why":"as an attributive adjective the word simply marks the level at which a thing sits, one step before the shop.","whyCN":"作定语时，这个词只标明某事物所处的层级，即店铺之前的那一步。"}],"etymology":{"intro":{"en":"Wholesale is a native English compound of whole and sale, first recorded in the late Middle Ages. Dates are approximate.","cn":"wholesale 是英语本族的复合词，由「整」与「卖」两个词合成，最早见于中世纪末。年代均为约数。"},"items":[{"era":"OLD ENGLISH HĀL","en":"Hāl meant 'entire, unhurt, healthy', the ancestor of whole; the 'entire' branch supplied the compound, not the 'healthy' branch.","cn":"hāl 意为「完整的、未受损的、健康的」，是 whole 的祖先；进入复合词的是「完整」这一支，不是「健康」那一支。"},{"era":"OLD ENGLISH SALA","en":"Sala meant 'a sale, a transfer of goods for money', the ancestor of sale.","cn":"sala 意为「买卖、以物换钱的转让」，是 sale 的祖先。"},{"era":"MIDDLE ENGLISH COMPOUND","en":"Whole plus sale named the selling of an entire lot rather than pieces, and the spelling settled as one word.","cn":"「整」加「卖」指整批而非零片地售出，后来拼写固定为一个词。"},{"era":"TRADE SENSE","en":"By the eighteenth century the word named the trade that stands between maker and shop, together with its prices and markets.","cn":"到十八世纪，这个词已指站在制造商与店铺之间的行业，并连同其价格与市场一并得名。"},{"era":"FIGURATIVE SENSE","en":"The nineteenth century extended it to anything done in one great undiscriminating sweep, such as wholesale slaughter.","cn":"十九世纪把它扩展到任何一次大规模、不加区分的行动，如整批屠杀。"},{"era":"FINANCE SENSE","en":"Twentieth-century banking applied the word to large institutional sums, and energy markets followed with wholesale power.","cn":"二十世纪的银行业把这个词用于机构间的大额资金，能源市场随后也有了批发电力的说法。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but belong to other branches; group two holds near neighbours in the same trade.","cn":"第一组是形近或音近但属于其他义支的词；第二组是同一行业里语义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sale","ipa":"/seɪl/","tag":"the second half","definition":"The plain noun for a transfer of goods for money; wholesale adds the idea of an entire lot.","definitionCN":"指以物换钱的普通名词；wholesale 在其上加了「整批」的意思。"},{"word":"resale","ipa":"/ˌriːˈseɪl/","tag":"selling again","definition":"The sale of something already bought, which is what a wholesale buyer intends to do.","definitionCN":"把已买下的东西再卖出，这正是批发买家的打算。"},{"word":"wholesome","ipa":"/ˈhəʊlsəm/","tag":"different branch","definition":"Built on the 'healthy' sense of whole plus a suffix meaning 'in the manner of', so it means health-giving, not bulk.","definitionCN":"由前半部分在「健康」一义上加表「具有某种性质」的后缀构成，意为有益健康，与整批无关。"},{"word":"whole","ipa":"/həʊl/","tag":"the first half","definition":"The adjective for something complete and undivided; in the compound it means one lot taken as a unit.","definitionCN":"指完整、未分割的形容词；在复合词里表示把一整批当作一个单位。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bulk sale","ipa":"/bʌlk seɪl/","tag":"quantity focus","definition":"A sale described by its large quantity; wholesale is the trade term for that kind of dealing.","definitionCN":"以数量大来描述的一笔交易；wholesale 是这种交易方式的行业术语。"},{"word":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃn/","tag":"the moving stage","definition":"The stage that moves goods from maker to shop; wholesale names who buys and sells, distribution names the flow.","definitionCN":"把货从制造商送到店铺的环节；wholesale 指谁买谁卖，distribution 指货的流动。"},{"word":"trade price","ipa":"/treɪd praɪs/","tag":"price for insiders","definition":"The price offered to businesses rather than the public, close to the wholesale price.","definitionCN":"面向企业而非公众的价格，与批发价接近。"},{"word":"clearance","ipa":"/ˈklɪərəns/","tag":"selling off stock","definition":"The sale of remaining stock at low prices; it can be large in quantity but is not trade between firms.","definitionCN":"以低价卖掉剩余存货；数量可能很大，但不是企业之间的批发。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real halves of the compound and the real trade phrases.","cn":"正常联想使用这个复合词真实的两半，以及真实的行业搭配。"},"normal":[{"en":"Whole plus sale: the whole lot is sold in one deal, not item by item.","cn":"「整」加「卖」：一整批一次成交，而不是一件一件地卖。"},{"en":"The pair wholesale and retail mark the two ends: bulk to shops, single items to people.","cn":"批发与零售标出两端：整批给店铺，单件给个人。"},{"en":"Fixed phrases mark it: wholesale price, wholesale market, wholesale trade.","cn":"固定搭配标出这个词：批发价、批发市场、批发贸易。"},{"en":"The same first half gives wholesome, but through the 'healthy' sense.","cn":"同一个前半部分也构成「有益健康的」一词，但走的是「健康」那一义。"},{"en":"Wholesale is not a place; it is a level of trade, one step before the shop.","cn":"批发不是地点，而是交易层级，位于店铺之前的一步。"}],"abstract":[{"en":"Picture a pallet that never gets unpacked, sliding straight from truck to truck.","cn":"想象一整托盘货始终没被拆开，直接从一辆车滑到另一辆车。"},{"en":"Picture a door marked trade only, where the public is not allowed to buy.","cn":"想象一扇只对同行开放的门，普通顾客不许在此购买。"},{"en":"Picture a broom that sweeps a whole street in one stroke instead of picking up each scrap.","cn":"想象一把扫帚一扫就扫过整条街，而不是逐片捡起碎屑。"}]},"examples":[{"en":"Wholesale margins are thin, so volume has to be high.","cn":"批发的利润薄，因此数量必须大。"},{"en":"The shop buys wholesale and prices each item for the public.","cn":"店铺整批进货，再给每件商品标出面向公众的价格。"},{"en":"The committee rejected wholesale cuts and asked for case-by-case review.","cn":"委员会否决了一刀切的削减，要求逐案审查。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「whole（整）+ sale（卖）」——整批一起卖 → 批发","word":"wholesale"},"root":"英语本族复合词：whole（完整的，来自古英语 hāl「完整、未损」）＋sale（买卖，来自古英语 sala）。字面即「整批卖出」，与拉丁语无同族关系。","sensesIntro":{"en":"Eight senses follow one idea: a whole lot sold as one unit, and that idea then becomes a trade, a price, a manner, a scale and finally a market level.","cn":"八个义项沿同一个想法展开：一整批货作为一个单位卖出；这个想法随后变成行业、价格、方式、规模，最后成为一种市场层级。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unopened pallet moving straight from one truck to another.","cn":"核心意象：一整托盘货始终未拆，从一辆车直接转到另一辆车。"},"chain":["WHOLE LOT","NO BREAKING UP","TRADE BETWEEN FIRMS","ONE PRICE FOR ALL","LARGE SCALE","NO DISTINCTIONS"],"branches":[{"senses":"01 · 02","en":"BULK TRADE: the whole lot changes hands, and the habit hardens into an industry.","cn":"整批交易：整批货易手，这种做法固定成一个行业。"},{"senses":"03 · 04","en":"PRICE AND MANNER: because the lot is whole, the unit price falls and the dealing can be named by its manner.","cn":"价格与方式：因为成整批，单件价格下降，交易也可以直接用方式命名。"},{"senses":"05","en":"NO DISTINCTION: one sweep leaves no item judged on its own, which is where the word turns critical.","cn":"不分彼此：一扫而过时没有哪一件被单独评判，词义在此带上批评色彩。"},{"senses":"06 · 07","en":"INSTITUTIONAL LEVEL: money and energy are also bought in blocks, one step before households.","cn":"机构层面：资金与能源同样成块买进，位于家庭之前的一步。"},{"senses":"08","en":"CHAIN LEVEL: as a label it simply marks the bulk floor of the supply chain.","cn":"链条层级：作定语时，它只标出供应链中的整批那一层。"}]},"affixes":{"intro":{"en":"The word is a native compound, not a Latin derivative, so it is read as two Old English morphemes plus an agent suffix.","cn":"这个词是本族复合词而非拉丁派生词，因此按两个古英语语素加一个施动后缀来读。"},"latinIntro":{"en":"No Latin entries apply: whole and sale are both inherited Germanic words, and the compound has no Latin source.","cn":"不适用拉丁条目：whole 与 sale 都是承继的日耳曼语词，这个复合词没有拉丁语来源。"},"items":[{"word":"whole","structure":"whole (Old English hāl, 'entire')","meaning":"complete, undivided","meaningCN":"完整的；未分割的","example":"The whole lot goes out at once.","exampleCN":"整批货一次发走。"},{"word":"sale","structure":"sale (Old English sala, 'a transfer for money')","meaning":"the act of selling","meaningCN":"出售的行为","example":"The sale is recorded on one invoice.","exampleCN":"这笔买卖记在一张发票上。"},{"word":"wholesale","structure":"whole + sale (compound noun)","meaning":"the sale of a whole lot","meaningCN":"整批出售","example":"Wholesale moves stock faster than retail.","exampleCN":"批发比零售走货更快。"},{"word":"wholesale","structure":"wholesale (attributive adjective)","meaning":"belonging to bulk trade","meaningCN":"属于整批交易的","example":"Wholesale buyers arrive before dawn.","exampleCN":"批发买家天亮前就到。"},{"word":"wholesale","structure":"wholesale (adverb of manner)","meaning":"in bulk","meaningCN":"以整批方式","example":"They buy wholesale and store the surplus.","exampleCN":"他们整批买进并把余货存起来。"},{"word":"wholesaler","structure":"wholesale + -er (one who does)","meaning":"a bulk trader","meaningCN":"批发商","example":"The wholesaler fills the shop's shelves.","exampleCN":"批发商把店铺的货架填满。"},{"word":"wholesaling","structure":"wholesale + -ing (activity)","meaning":"the business of bulk selling","meaningCN":"批发业务","example":"Wholesaling is regulated by local licence.","exampleCN":"批发业务受本地许可制度管理。"},{"word":"wholesaled","structure":"wholesale + -ed (past participle)","meaning":"sold in bulk","meaningCN":"以整批方式售出的","example":"The crop was wholesaled before harvest.","exampleCN":"这批作物在收割前就整批卖掉了。"}],"latinEntries":[],"derivatives":[{"word":"wholesaler","pos":"n.","zh":"批发商"},{"word":"wholesaling","pos":"n.","zh":"批发业务"},{"word":"wholesaled","pos":"adj.","zh":"以批发方式售出的"}]}},{"word":"wholesaler","ipa_uk":"/ˈhəʊlseɪlə/","ipa_us":"/ˈhoʊlseɪlər/","definition_zh":"批发商；批发企业","definition_en":"a trader or firm that buys goods in large lots from producers and sells them on to shops","core_image":"一只大漏斗：上游整车倒进来，下游分给许多小店，漏斗自己不做零售","scene":"天刚亮，整箱水果从产地车卸到批发商的摊位上，小店的车再把这些箱子分走。The wholesaler buys by the truckload and sells by the crate.","sceneCN":"批发市场的摊位前，整箱水果从产地车卸下，再由小店的车分装带走；句中的 wholesaler 指「从生产者大批进货、转售给零售商的批发商」（第 1 个义项：处在供应链中间、只与店铺打交道的商人）。图中可辨识物件：产地货车、整箱水果、摊位、小推车。","pos":[{"tag":"n.","zh":"批发商；批发企业"}],"collocations":[{"phrase":"cash-and-carry wholesaler","zh":"现购自运批发商"},{"phrase":"food wholesaler","zh":"食品批发商"},{"phrase":"wholesaler margin","zh":"批发商利润"},{"phrase":"wholesaler and retailer","zh":"批发商与零售商"},{"phrase":"wholesaler licence","zh":"批发许可证"},{"phrase":"energy wholesaler","zh":"能源批发商"}],"forms":[{"label":"复数","form":"wholesalers"},{"label":"形容词（批发的）","form":"wholesale"},{"label":"名词（批发业务）","form":"wholesaling"},{"label":"动词（整批出售）","form":"wholesale"},{"label":"过去分词","form":"wholesaled"},{"label":"现在分词","form":"wholesaling"}],"derivatives":[{"word":"wholesale","pos":"adj./n.","zh":"批发的 / 批发"},{"word":"wholesaling","pos":"n.","zh":"批发业务"},{"word":"wholesaled","pos":"adj.","zh":"以批发方式售出的"}],"senses":[{"no":"01","title":"Trader between producer and shop","titleCN":"从生产者大批进货、转售给零售商的批发商","definition":"a merchant who buys in bulk from producers and sells to retailers in smaller but still wholesale lots","definitionCN":"从生产者处大批买进、再以较小的整批规模卖给零售商的商人","example":"The wholesaler buys by the truckload and sells by the crate.","exampleCN":"批发商按整车买进，按整箱卖出。","why":"the agent suffix on the trade name marks the person who lives by selling whole lots.","whyCN":"行业名加上表施动者的后缀，指以整批出售为生的人。"},{"no":"02","title":"A firm in the chain","titleCN":"供应链中间环节的批发企业","definition":"a company whose business is to hold stock and supply many shops","definitionCN":"以持有存货并向多家店铺供货为业务的公司","example":"The wholesaler keeps three months of stock in its depot.","exampleCN":"这家批发企业的仓库常备三个月的存货。","why":"the role survives as a company rather than a person, and the word covers both.","whyCN":"这一角色以公司而非个人的形式延续下来，而这个词两者都能指。"},{"no":"03","title":"Trader in one commodity","titleCN":"经营某一类商品的批发商","definition":"a bulk trader specialising in a single line, such as grain, medicine or fruit","definitionCN":"专营某一类商品（如粮食、药品或水果）的批发商","example":"A grain wholesaler sets the price that mills pay.","exampleCN":"粮食批发商定下磨坊要付的价格。","why":"specialising narrows the role, so the commodity name is simply attached in front of it.","whyCN":"专业化使角色收窄，于是把商品名直接加在它前面即可。"},{"no":"04","title":"Cash-and-carry operator","titleCN":"现购自运式批发商","definition":"a wholesaler that lets small shops pay on the spot and carry the goods away themselves","definitionCN":"允许小店当场付款、自行把货带走的批发商","example":"The cash-and-carry wholesaler serves corner shops without delivery.","exampleCN":"这家现购自运批发商服务街角小店，但不送货。","why":"the trade may drop delivery and credit while keeping the bulk role, and a phrase marks that variant.","whyCN":"批发可以省去送货与赊账而保留整批角色，这个变体用固定说法来标明。"},{"no":"05","title":"The middle party","titleCN":"站在生产与零售之间的中间方","definition":"the party that stands between maker and shop and takes a margin for the service","definitionCN":"站在制造商与店铺之间、靠这项服务赚取差价的一方","example":"Removing the wholesaler did not lower prices as promised.","exampleCN":"去掉批发商并没有像承诺的那样压低价格。","why":"because the role is defined by position, it can be discussed as an obstacle or a convenience without naming a firm.","whyCN":"这一角色由位置来定义，因此不必指名某家公司，也能把它当作障碍或便利来讨论。"},{"no":"06","title":"Bulk seller of energy","titleCN":"向供电公司成批转售电力的能源批发商","definition":"a company that buys power or gas in bulk and resells it to suppliers or large users","definitionCN":"成批买下电力或燃气、再转售给供应商或大用户的公司","example":"An energy wholesaler hedges the winter load in advance.","exampleCN":"能源批发商会提前对冬季负荷做对冲。","why":"the word spreads to any market where blocks of a commodity change hands between firms.","whyCN":"一词扩散到任何企业之间成块买卖大宗商品的市场。"},{"no":"07","title":"The bulk stage of a supply chain","titleCN":"供应链中承担整批集散的那一环","definition":"the stage that gathers output from many producers and distributes it to many shops","definitionCN":"把众多生产者的产出汇集起来、再分给众多店铺的那个阶段","example":"The wholesaler stage adds the cost of storage and transport.","exampleCN":"批发商这一环加上了仓储与运输的成本。","why":"economics describes the chain in stages, and the trader's name became the name of the stage.","whyCN":"经济学把链条分段描述，商人的名字于是成了这一阶段的名字。"},{"no":"08","title":"Any party that aggregates supply","titleCN":"抽象义：任何把零散供应汇集起来再分出去的一方","definition":"any intermediary that collects scattered supply into one place and passes it on","definitionCN":"任何把零散的供应汇集到一处再传出去的中介","example":"The platform acts as a wholesaler of attention.","exampleCN":"这个平台充当注意力的批发商。","why":"strip away the goods and the shape remains: gather small lots, hold them, hand them out in bigger ones.","whyCN":"把货物抽掉，形状仍在：收拢零散的小份、持有一段时间、再以大份发出去。"}],"etymology":{"intro":{"en":"Wholesaler is the agent noun of wholesale, itself a compound of whole and sale. Dates are approximate.","cn":"wholesaler 是 wholesale 的施动名词，而 wholesale 由「整」与「卖」两个本族词合成。年代均为约数。"},"items":[{"era":"OLD ENGLISH HĀL","en":"Hāl 'entire, unhurt' is the ancestor of whole, and the 'entire' sense entered the compound.","cn":"hāl「完整的、未损的」是 whole 的祖先，进入复合词的是「完整」这一义。"},{"era":"OLD ENGLISH SALA","en":"Sala 'a sale, a transfer for money' is the ancestor of sale.","cn":"sala「买卖、以物换钱的转让」是 sale 的祖先。"},{"era":"MIDDLE ENGLISH WHOLESALE","en":"The compound named the selling of a whole lot; its trade meaning is recorded from the late Middle Ages.","cn":"这个复合词指整批售出，其行业义在中世纪末已有记载。"},{"era":"AGENT SUFFIX","en":"Adding the suffix that marks a person or firm produced wholesaler, the one who sells by the whole lot.","cn":"加上表人或机构的后缀，构成 wholesaler，即按整批出售的一方。"},{"era":"MODERN TRADE","en":"With industrial distribution the wholesaler became a distinct firm with depots, delivery fleets and credit terms.","cn":"随着工业化流通，批发商成为拥有仓库、车队与赊账条件的独立企业。"}]},"similar":{"note":{"en":"Group one holds words from the same compound that are easily swapped; group two holds other names for a trading intermediary.","cn":"第一组是同出该复合词、容易互换的词；第二组是交易中介的其他称呼。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"wholesale","ipa":"/ˈhəʊlseɪl/","tag":"the trade, not the trader","definition":"The activity or price level of bulk selling; the longer word names the party that performs it.","definitionCN":"指整批出售的活动或价格层级；较长的那个词指执行它的那一方。"},{"word":"wholesaling","ipa":"/ˈhəʊlseɪlɪŋ/","tag":"the activity","definition":"The business of selling in bulk, seen as a process rather than as a person.","definitionCN":"把整批出售看作一项业务过程，而不是一个人。"},{"word":"retailer","ipa":"/ˈriːteɪlə/","tag":"the other end","definition":"The trader who sells single items to the public; the two names mark opposite ends of the chain.","definitionCN":"把单件商品卖给公众的商人；两个名称标出链条的两端。"},{"word":"sale","ipa":"/seɪl/","tag":"the second half","definition":"The plain noun for a transfer of goods for money, one half of the compound behind the name.","definitionCN":"指以物换钱的普通名词，是该名称背后复合词的一半。"}]},{"heading":"NEAR MEANING","entries":[{"word":"distributor","ipa":"/dɪˈstrɪbjuːtə/","tag":"appointed channel","definition":"A firm that supplies shops, often under a brand contract; a wholesaler is defined by bulk buying rather than by appointment.","definitionCN":"向店铺供货、常受品牌合同约束的公司；批发商以大批进货为定义，而不以授权为定义。"},{"word":"jobber","ipa":"/ˈdʒɒbə/","tag":"old trade word","definition":"An older British term for a wholesaler who buys from importers and sells to retailers.","definitionCN":"较旧的英式说法，指从进口商买进、卖给零售商的批发商。"},{"word":"supplier","ipa":"/səˈplaɪə/","tag":"provides goods","definition":"Any party that provides goods, often directly to the user; it does not imply resale to shops.","definitionCN":"任何提供货物的一方，常直接卖给使用者；并不含转售给店铺之意。"},{"word":"middleman","ipa":"/ˈmɪdlmæn/","tag":"positional term","definition":"A neutral name for any trader between producer and buyer, including a wholesaler.","definitionCN":"对生产者与买家之间任何商人的中性称呼，批发商是其中之一。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real compound, the real agent suffix and the real trade phrases.","cn":"正常联想使用真实的复合词、真实的施动后缀与真实的行业搭配。"},"normal":[{"en":"Wholesale plus the person suffix: the one who sells whole lots.","cn":"批发一词加上表人的后缀：卖整批货的那一方。"},{"en":"The pair wholesaler and retailer face each other across the shop door.","cn":"批发商与零售商隔着店铺的门相对而立。"},{"en":"Fixed phrases mark it: cash-and-carry wholesaler, food wholesaler, wholesaler margin.","cn":"固定搭配标出这个词：现购自运批发商、食品批发商、批发商毛利。"},{"en":"A jobber is the older British cousin of the wholesaler.","cn":"jobber 是批发商较旧的英式同义词。"},{"en":"The wholesaler never sells one apple; it sells the box.","cn":"批发商从不卖一个苹果，它卖一整箱。"}],"abstract":[{"en":"Picture a wide funnel that catches truckloads and lets crates out at the bottom.","cn":"想象一只宽漏斗接住整车货物，从底下放出一箱箱货。"},{"en":"Picture a reservoir that holds the season's water and lets it out to many small canals.","cn":"想象一座水库蓄住一季的水，再放给许多小渠。"},{"en":"Picture a warehouse that never opens a box, only moves whole pallets.","cn":"想象一间从不拆箱、只搬整托盘的仓库。"}]},"examples":[{"en":"The wholesaler's depot holds stock that no single shop could afford to keep.","cn":"批发商的仓库持有任何一家店都无力囤积的存货。"},{"en":"Small shops depend on the wholesaler for credit as much as for goods.","cn":"小店依赖批发商的，不只是货，还有赊账。"},{"en":"Cutting out the wholesaler shifts storage costs onto the retailer.","cn":"去掉批发商，就把仓储成本转给了零售商。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「whole（整）+ saler（卖的人）」——整批卖货的人 → 批发商","word":"wholesaler"},"root":"英语本族复合词 wholesale（whole「完整」＋sale「买卖」）加表施动者的后缀构成，指按整批出售的一方；与拉丁语无同族关系。","sensesIntro":{"en":"Eight senses circle one role: the party that gathers large lots and passes them on, whether as a person, a firm, a stage or a metaphor.","cn":"八个义项围绕同一个角色：把大批货汇集起来再传出去的一方，它可以是一个人、一家公司、一个环节，也可以是一个比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wide funnel that receives truckloads and releases crates.","cn":"核心意象：一只宽漏斗接住整车货物，再从底下放出整箱。"},"chain":["BUY IN BULK","HOLD STOCK","SUPPLY SHOPS","TAKE A MARGIN","SERVE A MARKET","AGGREGATE SUPPLY"],"branches":[{"senses":"01 · 02","en":"THE PARTY: the trader and the firm are the same role seen as a person and as an organization.","cn":"当事方：商人与人手下的公司，是同一角色在个人与组织两个层面的呈现。"},{"senses":"03 · 04","en":"SPECIALISATION: one line or one payment style narrows the bulk role without changing it.","cn":"专业化：专营一类货或改用现款自运，只收窄整批角色而不改变它。"},{"senses":"05 · 07","en":"POSITION: defined by standing between maker and shop, the role can be praised, blamed or costed as a stage.","cn":"位置：因站在制造商与店铺之间而被定义，这一角色可被称赞、指责或按环节计价。"},{"senses":"06","en":"OTHER MARKETS: power and gas show that the role does not need physical goods.","cn":"其他市场：电力与燃气说明这一角色不需要实物商品。"},{"senses":"08","en":"PURE SHAPE: gather small lots and hand out bigger ones, with nothing left but the movement.","cn":"纯形状：收拢小份、发出大份，最后只剩下这一动作本身。"}]},"affixes":{"intro":{"en":"The word is a native compound plus an agent suffix, so it is read as three English morphemes.","cn":"这个词是本族复合词加一个施动后缀，可按三个英语语素来读。"},"latinIntro":{"en":"No Latin entries apply: the whole word is built from inherited Germanic material.","cn":"不适用拉丁条目：整个词都由承继的日耳曼语材料构成。"},"items":[{"word":"whole","structure":"whole (Old English hāl, 'entire')","meaning":"complete, undivided","meaningCN":"完整的；未分割的","example":"The whole lot is sold in one deal.","exampleCN":"整批货一次成交。"},{"word":"sale","structure":"sale (Old English sala, 'a transfer for money')","meaning":"the act of selling","meaningCN":"出售的行为","example":"One invoice records the sale.","exampleCN":"一张发票记录了这笔买卖。"},{"word":"wholesale","structure":"whole + sale (compound)","meaning":"bulk selling","meaningCN":"整批出售","example":"Wholesale supplies the shops.","exampleCN":"批发向店铺供货。"},{"word":"-er","structure":"-er (English suffix, 'one who does')","meaning":"the person or firm that acts","meaningCN":"执行动作的人或机构","example":"The suffix turns the trade into the trader.","exampleCN":"这个后缀把行业名变成从业者。"},{"word":"wholesaler","structure":"wholesale + -er","meaning":"a bulk trader","meaningCN":"批发商","example":"The wholesaler fills the depot before winter.","exampleCN":"批发商在入冬前把仓库备满。"},{"word":"wholesaling","structure":"wholesale + -ing (activity)","meaning":"the business of bulk selling","meaningCN":"批发业务","example":"Wholesaling needs a large floor area.","exampleCN":"批发业务需要很大的场地。"},{"word":"wholesaled","structure":"wholesale + -ed (past participle)","meaning":"sold in bulk","meaningCN":"以整批方式售出的","example":"The harvest was wholesaled in advance.","exampleCN":"收成提前整批卖掉了。"},{"word":"wholesale price","structure":"wholesale + price (compound noun)","meaning":"the bulk price","meaningCN":"批发价格","example":"The wholesale price is printed on the docket.","exampleCN":"批发价印在货单上。"}],"latinEntries":[],"derivatives":[{"word":"wholesale","pos":"adj./n.","zh":"批发的 / 批发"},{"word":"wholesaling","pos":"n.","zh":"批发业务"},{"word":"wholesaled","pos":"adj.","zh":"以批发方式售出的"}]}},{"word":"retail","ipa_uk":"/ˈriːteɪl/","ipa_us":"/ˈriːteɪl/","definition_zh":"零售；零售业；零售的；以零售方式；（按零售方式）出售","definition_en":"the selling of goods in small quantities to the people who will use them, rather than to shops for resale","core_image":"一整批货被拆成一小份一小份，摆在柜台上，等人一件件拿走","scene":"收银台前，整箱的商品被一包一包拆开扫码，顾客只买走其中一件，剩下的仍留在货架上。Shops retail goods directly to the people who use them.","sceneCN":"收银台前，整箱货被拆成单件逐一扫码，顾客只拿走自己要的那一件；句中的 retail 指「把商品少量卖给最终使用者」（第 1 个义项：面向个人消费者的零散出售）。图中可辨识物件：收银台、扫码枪、购物袋、货架。","pos":[{"tag":"n.","zh":"零售；零售业"},{"tag":"adj.","zh":"零售的"},{"tag":"adv.","zh":"以零售方式"},{"tag":"v.","zh":"零售；以零售方式出售"}],"collocations":[{"phrase":"retail price","zh":"零售价"},{"phrase":"retail store","zh":"零售店"},{"phrase":"retail sales","zh":"零售额"},{"phrase":"retail banking","zh":"零售银行（个人银行业务）"},{"phrase":"retail investor","zh":"个人投资者"},{"phrase":"sell retail","zh":"零卖"}],"forms":[{"label":"三单","form":"retails"},{"label":"过去式","form":"retailed"},{"label":"过去分词","form":"retailed"},{"label":"现在分词","form":"retailing"},{"label":"施动者名词","form":"retailer"},{"label":"复数（零售业务）","form":"retails"}],"derivatives":[{"word":"retailer","pos":"n.","zh":"零售商"},{"word":"retailing","pos":"n.","zh":"零售业"},{"word":"retailed","pos":"adj.","zh":"以零售方式售出的"}],"senses":[{"no":"01","title":"Selling single items to users","titleCN":"把商品单件卖给最终使用者","definition":"the sale of goods in small amounts to the person who will use them","definitionCN":"把货物少量卖给最终使用它的人","example":"Retail begins where the shop door opens to the public.","exampleCN":"零售从店门向公众打开的那一刻开始。","why":"the Old French verb behind it means 'to cut off a piece', so the word pictures a bulk broken into small parts.","whyCN":"其背后的古法语动词意为「切下一块」，因此这个词描绘的是把整批切成小份。"},{"no":"02","title":"The retail sector","titleCN":"作为行业的零售业","definition":"the branch of trade that sells to the public and employs shop staff","definitionCN":"向公众出售并雇用店员的那一支商业","example":"Retail accounts for a large share of city employment.","exampleCN":"零售业占城市就业的很大一部分。","why":"the practice gave its name to the whole sector, just as wholesale named its own industry.","whyCN":"这种做法把名字给了整个行业，正如批发改名了自己的行业一样。"},{"no":"03","title":"The shop price","titleCN":"面向公众的零售价","definition":"the price a member of the public pays in a shop","definitionCN":"公众在商店里支付的价格","example":"The retail price is twice what the shop paid.","exampleCN":"零售价是店铺进价的两倍。","why":"the last price in the chain is named after the stage that charges it.","whyCN":"链条上的最后一个价格，以收取它的那个环节命名。"},{"no":"04","title":"In small quantities, as a manner","titleCN":"以零散方式买卖（副词用法）","definition":"by the single item rather than by the lot","definitionCN":"按单件而非整批地进行","example":"The farm retails its honey at the gate.","exampleCN":"农场在门口零卖自家蜂蜜。","why":"the noun of manner behaves as an adverb, so the trade name can describe how the selling is done.","whyCN":"表方式的名词可作副词，因此行业名能说明售卖是怎么做的。"},{"no":"05","title":"Everyday banking for individuals","titleCN":"面向个人的零售银行业务","definition":"financial services sold in small accounts to ordinary customers rather than to companies","definitionCN":"以小账户面向普通客户而非企业出售的金融服务","example":"Retail banking lost customers to the digital apps.","exampleCN":"个人银行业务的客户被数字应用抢走。","why":"banks borrowed the shop contrast: small accounts to individuals are retail, large deals between firms are wholesale.","whyCN":"银行借用了商店里的对比：给个人的小额账户是零售，企业之间的大额交易是批发。"},{"no":"06","title":"The small private investor","titleCN":"以个人身份小额投资的零售投资者","definition":"an ordinary individual investing small sums, as opposed to an institution","definitionCN":"以小额资金投资的普通人，以区别于机构","example":"Retail investors bought the shares on the first day.","exampleCN":"个人投资者在第一天买入了这些股票。","why":"the same small-versus-large contrast moved from shops to markets, where individuals are the retail side.","whyCN":"同样的「小对与大」对比从商店移到市场，个人成了零售那一端。"},{"no":"07","title":"Politics conducted face to face","titleCN":"逐户接触选民式的零售政治","definition":"campaigning by meeting voters directly in small groups rather than through mass advertising","definitionCN":"通过小组直接会见选民、而非依靠大众广告的竞选方式","example":"The candidate chose retail politics over television spots.","exampleCN":"这位候选人选择逐户接触选民，而不是电视广告。","why":"the metaphor treats each voter as a single customer, so direct contact is selling retail.","whyCN":"这个比喻把每位选民当作单个顾客，因此直接接触就是零售式推销。"},{"no":"08","title":"Selling through online shops","titleCN":"通过网络店铺进行的零售","definition":"the sale of single items to consumers through websites and apps","definitionCN":"通过网站与应用向消费者出售单件商品","example":"Online retail grew while high-street shops shrank.","exampleCN":"网络零售增长，商业街的店铺却在收缩。","why":"the channel changed but the unit of sale did not, so the old trade name simply took a new companion word.","whyCN":"渠道变了，出售的单位没变，因此旧的行业名只添了一个新的搭配词。"}],"etymology":{"intro":{"en":"Retail comes from Old French retaillier 'to cut off, cut up', built on re- 'back' and taillier 'to cut'. Dates are approximate.","cn":"retail 来自古法语 retaillier「切下、切碎」，由表示「回、再」的前缀与表示「切」的动词构成。年代均为约数。"},"items":[{"era":"LATE LATIN TALIARE","en":"Taliare 'to cut' is recorded in Late Latin and is usually connected with talea 'a cutting, a rod'; the deeper origin of talea is not fully settled.","cn":"taliare「切」见于晚期拉丁语，通常与 talea「切下的部分、枝条」相联系；talea 更早的来源尚无完全定论。"},{"era":"OLD FRENCH TAILLIER","en":"Old French taillier 'to cut, carve, divide' supplied the verb that English borrowed.","cn":"古法语 taillier「切、刻、分割」提供了英语借入的那个动词。"},{"era":"OLD FRENCH RETAILLIER","en":"Re- 'back, again' plus taillier gave retaillier 'to cut off a piece', the source of the English word.","cn":"表示「回、再」的前缀加 taillier 构成 retaillier「切下一块」，是英语词的来源。"},{"era":"ENGLISH RETAIL","en":"In the fourteenth century the word entered English for selling in small cut-off portions, and the shop sense followed.","cn":"十四世纪这个词进入英语，指把货物切成小份出售，店铺义随后出现。"},{"era":"MODERN SECTOR","en":"Retailing became a named industry in the nineteenth century, and the word then spread to banking, investing and politics.","cn":"零售在十九世纪成为一个有名称的行业，随后扩展到银行业、投资与政治。"}]},"similar":{"note":{"en":"Group one holds words cut from the same old 'cut' root, whose meanings have drifted far apart; group two holds verbs of selling.","cn":"第一组同出古老的「切」词根，但意义已各自漂远；第二组是表示出售的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"detail","ipa":"/dɪˈteɪl/","tag":"same root, small piece","definition":"The prefix for 'fully' plus the cutting verb: a small piece cut out, hence a particular item of information.","definitionCN":"由表示「完全」的前缀加「切」的动词构成：切下来的小片，因此指某一具体条目。"},{"word":"tailor","ipa":"/ˈteɪlə/","tag":"one who cuts cloth","definition":"From the same cutting verb: the person who cuts cloth to fit a customer.","definitionCN":"同出那个「切」的动词：把布按顾客身形剪裁的人。"},{"word":"entail","ipa":"/ɪnˈteɪl/","tag":"a cut-in limitation","definition":"Built on the noun for a cutting: originally to limit an inheritance, later to involve as a consequence.","definitionCN":"由表「切」的名词构成：原指限定继承，后指作为后果而牵涉。"},{"word":"curtail","ipa":"/kɜːˈteɪl/","tag":"cut short","definition":"From the phrase 'cut short': to reduce or trim something, keeping the old image of a blade.","definitionCN":"由「切短」的说法而来：削减或裁剪某物，保留了刀口的旧意象。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sell","ipa":"/sel/","tag":"plain verb","definition":"The general verb for handing over goods for money; retail specifies selling to the final user.","definitionCN":"以物换钱的普通动词；retail 特指卖给最终使用者。"},{"word":"vend","ipa":"/vend/","tag":"formal or machine","definition":"A formal verb for selling, now mostly in vending machines and legal prose.","definitionCN":"正式的出售动词，如今多用于自动售货机与法律文本。"},{"word":"peddle","ipa":"/ˈpedl/","tag":"carry and sell","definition":"To sell goods by going from place to place, often in small amounts.","definitionCN":"带着货物四处走动售卖，常常是少量出售。"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","tag":"move to shops","definition":"To supply goods to shops in bulk; retail is the step after that, where the public buys.","definitionCN":"成批把货供给店铺；retail 是其后的那一步，由公众购买。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real 'cutting' image, the real family and the real shop phrases.","cn":"正常联想使用真实的「切」意象、真实词族与真实的店铺搭配。"},"normal":[{"en":"The root means 'to cut': retail takes a bulk and cuts it into single items.","cn":"词根意为「切」：零售把整批货切成一件一件。"},{"en":"The family runs retail, retailer, retailing and retailed.","cn":"同族词围绕零售展开，包括零售商、零售业与已售出的形式。"},{"en":"Fixed phrases mark it: retail price, retail store, retail banking.","cn":"固定搭配标出这个词：零售价、零售店、个人银行业务。"},{"en":"The same cutting root gives detail, tailor, entail and curtail.","cn":"同一个「切」词根也构成「细节」「裁缝」「牵涉」与「削减」。"},{"en":"Retail is the last step: after this, the goods are used, not resold.","cn":"零售是最后一步：此后货物被使用，而不是再转售。"}],"abstract":[{"en":"Picture a loaf cut into slices so that each buyer takes one.","cn":"想象一整条面包被切成片，每位买家拿走一片。"},{"en":"Picture a rope being unwound and sold by the arm's length.","cn":"想象一卷绳子被放开，按一臂之长来卖。"},{"en":"Picture a market stall where the crate behind the counter is never shown whole.","cn":"想象一个摊位，柜台后的箱子从不整个示人。"}]},"examples":[{"en":"Retail margins are wider than wholesale margins, but each sale is small.","cn":"零售的利润比批发厚，但每笔交易都小。"},{"en":"The company moved from retail into online delivery.","cn":"这家公司从门店零售转向网络配送。"},{"en":"Retail investors often buy at the top of the market.","cn":"个人投资者常常在市场高点买入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「re（再）+ tail（切尾）」——把整批一再切小来卖 → 零售","word":"retail"},"root":"古法语 retaillier（切下、切碎）＝表示「回、再」的前缀＋taillier（切）；taillier 来自晚期拉丁语 taliare（切），与 talea（切下的部分）相关。字面即「切成小份出售」，故为零售。","sensesIntro":{"en":"Eight senses start from cutting a bulk into pieces and then follow that small-unit idea into shopkeeping, pricing, banking, investing, politics and online selling.","cn":"八个义项从「把整批切成小份」出发，再让这个「小单位」的想法依次进入店铺经营、定价、银行、投资、政治与网络销售。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole loaf sliced so that each buyer takes one piece.","cn":"核心意象：一整条面包被切片，每位买家拿走一片。"},"chain":["CUT INTO PIECES","SMALL UNIT","SELL TO USER","SHOP PRICE","PERSONAL SCALE","FINAL STEP"],"branches":[{"senses":"01 · 02","en":"SMALL UNIT TRADE: pieces rather than lots, and the habit becomes an industry.","cn":"小单位交易：卖的是片而不是整批，这种做法固定成一个行业。"},{"senses":"03 · 04","en":"LAST PRICE AND MANNER: the final price and the manner of selling both descend from the shop counter.","cn":"末端价格与方式：最后的价格与售卖方式都来自店铺柜台。"},{"senses":"05 · 06","en":"PERSONAL SCALE: small accounts and small holdings make an individual the retail side of finance.","cn":"个人尺度：小额账户与小额头寸使个人成为金融的零售一端。"},{"senses":"07","en":"ONE VOTER AT A TIME: direct contact treats the citizen as a single customer.","cn":"一次一位选民：直接接触把公民当成单个顾客。"},{"senses":"08","en":"NEW CHANNEL, SAME UNIT: the website changes where the sale happens, not how small it is.","cn":"新渠道、同单位：网站改变的是成交地点，而不是份额的大小。"}]},"affixes":{"intro":{"en":"The word is a French prefix plus a French cutting verb, with an English agent noun built on top.","cn":"这个词由一个法语前缀加一个法语「切」动词构成，英语又在其上加了施动名词。"},"latinIntro":{"en":"Late Latin taliare gives the cutting verb, and talea gives the noun for a cutting; detail, tailor and entail share the same stock.","cn":"晚期拉丁语 taliare 提供「切」的动词，talea 提供表「切下之物」的名词；「细节」「裁缝」「牵涉」同出这一词干。"},"items":[{"word":"re-","structure":"re- (Old French prefix, 'back, again')","meaning":"back; again","meaningCN":"回；再","example":"The prefix suggests cutting a piece off the whole.","exampleCN":"这个前缀表示从整块上切下一片。"},{"word":"taillier","structure":"taillier (Old French verb, 'to cut')","meaning":"to cut, divide","meaningCN":"切；分割","example":"The verb pictures a blade going through a whole.","exampleCN":"这个动词描绘刀锋穿过整块物体。"},{"word":"retaillier","structure":"re- + taillier (Old French verb)","meaning":"to cut off a piece","meaningCN":"切下一块","example":"Retaillier is the direct source of retail.","exampleCN":"这个古法语动词是 retail 的直接来源。"},{"word":"retail","structure":"retaillier through Middle English","meaning":"to sell in small pieces","meaningCN":"切成小份出售","example":"The farm retails honey by the jar.","exampleCN":"农场按罐零卖蜂蜜。"},{"word":"retailer","structure":"retail + -er (one who does)","meaning":"a shop that sells to the public","meaningCN":"面向公众出售的商店","example":"The retailer sets the shelf price.","exampleCN":"零售商定下货架价格。"},{"word":"retailing","structure":"retail + -ing (activity)","meaning":"the business of selling to users","meaningCN":"面向使用者的销售业务","example":"Retailing employs shop assistants.","exampleCN":"零售业雇用店员。"},{"word":"retailed","structure":"retail + -ed (past participle)","meaning":"sold in small amounts","meaningCN":"以少量方式售出的","example":"The cloth was retailed by the metre.","exampleCN":"这种布按米零卖。"},{"word":"detail","structure":"de- + taillier (French)","meaning":"a small piece cut out","meaningCN":"切下来的小片；细节","example":"Every detail of the order was checked.","exampleCN":"订单的每个细节都被核对过。"},{"word":"tailor","structure":"taillier + -or (one who cuts)","meaning":"one who cuts cloth to fit","meaningCN":"按身形裁剪布料的人","example":"The tailor measured the sleeve twice.","exampleCN":"裁缝把袖子量了两次。"}],"latinEntries":[{"word":"taliare","structure":"taliare (Late Latin verb, first conjugation)","meaning":"to cut","meaningCN":"切"},{"word":"talea","structure":"talea, taleae (f., first declension)","meaning":"a cutting, a rod","meaningCN":"切下的部分；枝条"}],"derivatives":[{"word":"retailer","pos":"n.","zh":"零售商"},{"word":"retailing","pos":"n.","zh":"零售业"},{"word":"retailed","pos":"adj.","zh":"以零售方式售出的"}]}},{"word":"retailer","ipa_uk":"/ˈriːteɪlə/","ipa_us":"/ˈriːteɪlər/","definition_zh":"零售商；零售店；零售企业","definition_en":"a person or firm that sells goods in small quantities directly to the public","core_image":"店门向街面打开，货架上一件件商品等着被单个顾客拿走","scene":"店门刚开，货架上每件商品都单独标价，顾客一次只拿一两件到柜台前。The retailer decides what sits on the shelf and at what price.","sceneCN":"店铺开门后，每件商品单独标价，顾客只买走少量几件；句中的 retailer 指「直接把商品少量卖给公众的零售商」（第 1 个义项：处在链条末端、与消费者直接打交道的一方）。图中可辨识物件：店门、货架、价签、收银台。","pos":[{"tag":"n.","zh":"零售商；零售店；零售企业"}],"collocations":[{"phrase":"online retailer","zh":"网络零售商"},{"phrase":"retailer margin","zh":"零售商利润"},{"phrase":"independent retailer","zh":"独立零售商"},{"phrase":"big-box retailer","zh":"大型仓储式零售商"},{"phrase":"specialty retailer","zh":"专业零售商"},{"phrase":"retailer discount","zh":"零售商折扣"}],"forms":[{"label":"复数","form":"retailers"},{"label":"名词（零售业）","form":"retailing"},{"label":"名词（零售）","form":"retail"},{"label":"形容词（零售的）","form":"retail"},{"label":"过去分词","form":"retailed"},{"label":"现在分词","form":"retailing"}],"derivatives":[{"word":"retail","pos":"n./adj.","zh":"零售 / 零售的"},{"word":"retailing","pos":"n.","zh":"零售业"},{"word":"retailed","pos":"adj.","zh":"以零售方式售出的"}],"senses":[{"no":"01","title":"Shop that sells to the public","titleCN":"直接面向公众出售商品的零售商","definition":"a trader who sells single items or small quantities directly to the final customer","definitionCN":"把单件或少量商品直接卖给最终顾客的商人","example":"The retailer decides what sits on the shelf and at what price.","exampleCN":"零售商决定货架上摆什么、卖什么价。","why":"the agent suffix on the trade word names the party at the counter, the last hand before the goods are used.","whyCN":"行业词加上施动后缀，指站在柜台后的一方，即货物被使用前的最后一手。"},{"no":"02","title":"A retail chain","titleCN":"拥有多家门店的零售连锁企业","definition":"a company operating many shops under one brand","definitionCN":"以同一品牌经营多家店铺的公司","example":"The retailer closed thirty stores in one quarter.","exampleCN":"这家零售连锁在一个季度里关了三十家店。","why":"scale turns the single shop into a firm, yet the word still names the same role at the counter.","whyCN":"规模把单家店变成企业，但这个词指的仍是柜台后的同一角色。"},{"no":"03","title":"Online shop","titleCN":"通过网络向顾客出售商品的网络零售商","definition":"a business that sells single items to customers through a website or app","definitionCN":"通过网站或应用向顾客出售单件商品的商家","example":"The online retailer ships from a single warehouse.","exampleCN":"这家网络零售商从一个仓库发货。","why":"the counter moved to a screen, but the unit of sale and the final customer stayed the same.","whyCN":"柜台移到屏幕上，但出售单位与最终顾客都没有变。"},{"no":"04","title":"Single-brand shop","titleCN":"只卖一个品牌的专卖零售商","definition":"a retailer that carries only one maker's goods","definitionCN":"只经营一家制造商商品的零售商","example":"The brand retailer refused to stock rival models.","exampleCN":"这家品牌专卖店拒绝进竞品的货。","why":"narrowing the assortment, not the role, produces this label.","whyCN":"收窄的是货品种类而非角色，于是有了这个说法。"},{"no":"05","title":"The party that takes the shop margin","titleCN":"赚取零售差价的那一方","definition":"the party whose income is the gap between wholesale cost and shop price","definitionCN":"收入来自进价与售价之间差额的一方","example":"The retailer absorbed the tax rise instead of raising prices.","exampleCN":"零售商自己吸收了税率上调，而没有提价。","why":"because the role is economic as well as physical, it can be described by the margin it keeps.","whyCN":"这个角色既是实体的也是经济的，因此也可以用它所留的差价来描述。"},{"no":"06","title":"Large-format shop","titleCN":"以大面积卖场经营的大型零售商","definition":"a retailer trading from a large floor area with a wide range of goods","definitionCN":"以大面积卖场经营、货品种类很宽的零售商","example":"The big-box retailer undercut every local shop.","exampleCN":"大型卖场把本地店铺的价格全压了下去。","why":"format is a visible variant of the same role, so English names it with a descriptive phrase.","whyCN":"业态是同一角色可见的变体，英语用描述性短语来命名它。"},{"no":"07","title":"The last link in the chain","titleCN":"供应链末端的零售环节","definition":"the final stage of distribution, where goods meet the people who use them","definitionCN":"流通的最后阶段，货物在此与使用者相遇","example":"The retailer, not the maker, hears the complaint first.","exampleCN":"最先听到抱怨的是零售商，而不是制造商。","why":"economics names stages, and the trader's name became the name of the last stage.","whyCN":"经济学给各阶段命名，商人的名字于是成了最后阶段的名字。"},{"no":"08","title":"Any party facing the end user","titleCN":"抽象义：任何直接面对最终使用者的一方","definition":"any intermediary whose customer is the final user rather than another business","definitionCN":"任何以最终使用者而非另一家企业为顾客的中介","example":"The clinic is the retailer of the drug's promise.","exampleCN":"诊所是这种药之承诺的零售端。","why":"remove the goods and the shape remains: the one who stands closest to the user and sells in small units.","whyCN":"抽掉货物，形状仍在：站得离使用者最近、以小单位出售的那一方。"}],"etymology":{"intro":{"en":"Retailer is the agent noun of retail, which comes from Old French retaillier 'to cut off a piece'. Dates are approximate.","cn":"retailer 是 retail 的施动名词，而 retail 来自古法语 retaillier「切下一块」。年代均为约数。"},"items":[{"era":"LATE LATIN TALIARE","en":"Taliare 'to cut' is recorded in Late Latin and is usually linked with talea 'a cutting, a rod'.","cn":"taliare「切」见于晚期拉丁语，通常与 talea「切下的部分、枝条」相联系。"},{"era":"OLD FRENCH TAILLIER","en":"Taillier 'to cut, divide' gave the base verb, and the prefix for 'back, again' produced retaillier 'to cut off'.","cn":"taillier「切、分割」提供了基础动词，表示「回、再」的前缀又构成 retaillier「切下」。"},{"era":"ENGLISH RETAIL","en":"English borrowed the word in the fourteenth century for selling goods in small portions.","cn":"英语在十四世纪借入这个词，指把货物切成小份出售。"},{"era":"AGENT SUFFIX","en":"The suffix marking the one who acts produced retailer, the trader at the counter.","cn":"表动作执行者的后缀构成 retailer，即站在柜台后的商人。"},{"era":"MODERN RETAILING","en":"Department stores, chains and online shops each reshaped the role, but the name stayed with the party closest to the buyer.","cn":"百货公司、连锁店与网店各自重塑了这个角色，但名称始终留给最靠近买家的那一方。"}]},"similar":{"note":{"en":"Group one holds words from the same 'cutting' stock that are often mistaken for relatives in meaning; group two holds other names for a seller.","cn":"第一组同出「切」这一词干，常被误认为意义同族；第二组是卖方的其他称呼。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"retail","ipa":"/ˈriːteɪl/","tag":"the trade, not the trader","definition":"The activity or price level of selling to the public; the longer word names the shop itself.","definitionCN":"指面向公众出售的活动或价格层级；较长的词指店铺本身。"},{"word":"detail","ipa":"/dɪˈteɪl/","tag":"same root, different meaning","definition":"A small piece cut out of a whole, hence a single item of information; it shares the cutting root but not the shop sense.","definitionCN":"从整块上切下的小片，因此指一条具体信息；与零售同根，但无店铺义。"},{"word":"tailor","ipa":"/ˈteɪlə/","tag":"one who cuts cloth","definition":"The person who cuts and sews cloth to fit a customer, from the same old cutting verb.","definitionCN":"把布剪裁缝制成顾客所需的人，同出那个古老的「切」动词。"},{"word":"retailing","ipa":"/ˈriːteɪlɪŋ/","tag":"the activity","definition":"The business seen as a process; retailer names the party that carries it on.","definitionCN":"把这一行业看作过程；retailer 指从事它的那一方。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shopkeeper","ipa":"/ˈʃɒpkiːpə/","tag":"person behind the counter","definition":"The person who runs a small shop; retailer is broader and includes chains and websites.","definitionCN":"经营小店的人；retailer 范围更广，包括连锁与网站。"},{"word":"merchant","ipa":"/ˈmɜːtʃənt/","tag":"trader, often wholesale","definition":"A trader in goods, historically at a larger scale; it does not fix the final-consumer role.","definitionCN":"经营货物的商人，历史上规模较大；并不限定面向最终消费者。"},{"word":"vendor","ipa":"/ˈvendə/","tag":"selling party","definition":"The party that sells in a given transaction, from a stall to a software firm.","definitionCN":"某笔交易中出售的一方，可以是摊位，也可以是软件公司。"},{"word":"dealer","ipa":"/ˈdiːlə/","tag":"trades one category","definition":"A trader in a particular class of goods, such as cars or antiques, without defining the customer.","definitionCN":"经营某一类商品（如汽车或古董）的商人，不限定顾客是谁。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real cutting root, the real family and the real shop phrases.","cn":"正常联想使用真实的「切」词根、真实词族与真实的店铺搭配。"},"normal":[{"en":"Retail plus the person suffix: the one who cuts the bulk into single sales.","cn":"零售一词加表人的后缀：把整批切成单笔买卖的那一方。"},{"en":"The pair retailer and wholesaler stand at opposite ends of the same chain.","cn":"零售商与批发商站在同一链条的两端。"},{"en":"Fixed phrases mark it: online retailer, independent retailer, retailer margin.","cn":"固定搭配标出这个词：网络零售商、独立零售商、零售商毛利。"},{"en":"The same cutting root gives detail, tailor, entail and curtail.","cn":"同一个「切」词根也构成「细节」「裁缝」「牵涉」与「削减」。"},{"en":"The retailer is the only trader the public actually meets.","cn":"零售商是公众真正会打交道的那个商人。"}],"abstract":[{"en":"Picture a counter where the crate is hidden and only single items are shown.","cn":"想象一个柜台，箱子藏在后面，只摆出单件商品。"},{"en":"Picture the last hand that touches a product before a home does.","cn":"想象一件商品进入家庭之前，最后经手的那只手。"},{"en":"Picture a screen that does the work of a shop door.","cn":"想象一块屏幕承担了店门的功能。"}]},"examples":[{"en":"The retailer bought the stock wholesale and priced it for the public.","cn":"零售商整批进货，再按面向公众的价格标价。"},{"en":"An online retailer can reach buyers that no high-street shop could.","cn":"网络零售商能接触到商业街店铺无法触及的买家。"},{"en":"The retailer takes the complaint even when the fault lies with the maker.","cn":"即使问题出在制造商，零售商仍要接下投诉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「retail（零售）+ er（人）」——做零售的人 → 零售商","word":"retailer"},"root":"retail（古法语 retaillier「切下一块」，由 re-「回、再」＋taillier「切」构成）加表施动者的后缀，指把整批货切成小份卖给公众的一方。","sensesIntro":{"en":"Eight senses keep one figure in view: the party nearest the buyer, whether a corner shop, a chain, a website or a metaphor for whoever faces the end user.","cn":"八个义项始终看着同一个人物：最靠近买家的一方，可以是街角小店、连锁企业、网站，也可以是任何直接面对最终使用者的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shop door open to the street with single items priced on the shelf.","cn":"核心意象：店门朝向街面打开，货架上的商品单件标价。"},"chain":["SMALL UNITS","MEET THE BUYER","SET THE SHELF","KEEP THE MARGIN","LAST LINK","FACE THE USER"],"branches":[{"senses":"01 · 02","en":"THE PARTY: the single shop and the chain differ in size, not in role.","cn":"当事方：单店与连锁的差别在规模，不在角色。"},{"senses":"03 · 04","en":"ASSORTMENT AND CHANNEL: a screen or a single brand changes what is offered, not who is served.","cn":"货品与渠道：屏幕或单一品牌改变的是提供什么，而不是服务谁。"},{"senses":"05 · 06","en":"ECONOMICS AND FORMAT: the margin and the floor area are the two visible ways the role is measured.","cn":"经济与业态：差价与卖场面积是衡量这一角色的两种可见方式。"},{"senses":"07","en":"LAST LINK: the chain ends where goods meet the people who use them.","cn":"最后一环：链条在货物与使用者相遇之处结束。"},{"senses":"08","en":"PURE POSITION: whoever stands closest to the end user is the retailer, goods or no goods.","cn":"纯位置：谁离最终使用者最近，谁就是零售商，无论有没有货物。"}]},"affixes":{"intro":{"en":"The word is a French cutting verb plus an English agent suffix, and its relatives all keep the image of a blade.","cn":"这个词由一个法语「切」动词加一个英语施动后缀构成，其同族词都保留刀口的意象。"},"latinIntro":{"en":"Late Latin taliare and talea supply the cutting stock; the agent suffix is English.","cn":"晚期拉丁语 taliare 与 talea 提供「切」的词干，施动后缀来自英语。"},"items":[{"word":"re-","structure":"re- (Old French prefix, 'back, again')","meaning":"back; again","meaningCN":"回；再","example":"The prefix marks a piece taken off a whole.","exampleCN":"这个前缀标记从整块上取下一片。"},{"word":"taillier","structure":"taillier (Old French verb, 'to cut')","meaning":"to cut, divide","meaningCN":"切；分割","example":"The verb keeps the picture of a blade.","exampleCN":"这个动词保留刀锋的画面。"},{"word":"retail","structure":"retaillier through Middle English","meaning":"to sell in small pieces","meaningCN":"切成小份出售","example":"The shop retails cloth by the metre.","exampleCN":"这家店按米零卖布料。"},{"word":"-er","structure":"-er (English suffix, 'one who does')","meaning":"the one that acts","meaningCN":"执行动作的一方","example":"The suffix turns the trade into the trader.","exampleCN":"这个后缀把行业名变成从业者。"},{"word":"retailer","structure":"retail + -er","meaning":"a shop selling to the public","meaningCN":"面向公众出售的商店","example":"The retailer sets the shelf price.","exampleCN":"零售商定下货架价格。"},{"word":"retailing","structure":"retail + -ing (activity)","meaning":"the business of small-unit selling","meaningCN":"小单位出售的业务","example":"Retailing fills the high street.","exampleCN":"零售业占满了商业街。"},{"word":"retailed","structure":"retail + -ed (past participle)","meaning":"sold in small amounts","meaningCN":"以少量方式售出的","example":"The honey was retailed at the gate.","exampleCN":"蜂蜜在门口零卖。"},{"word":"detail","structure":"de- + taillier (French)","meaning":"a small piece cut out","meaningCN":"切下的小片；细节","example":"The detail was easy to miss.","exampleCN":"这个细节很容易被忽略。"},{"word":"tailor","structure":"taillier + -or (one who cuts)","meaning":"one who cuts cloth","meaningCN":"裁剪布料的人","example":"The tailor cut the coat to measure.","exampleCN":"裁缝按尺寸裁好外套。"}],"latinEntries":[{"word":"taliare","structure":"taliare (Late Latin verb, first conjugation)","meaning":"to cut","meaningCN":"切"},{"word":"talea","structure":"talea, taleae (f., first declension)","meaning":"a cutting, a rod","meaningCN":"切下的部分；枝条"}],"derivatives":[{"word":"retail","pos":"n./adj.","zh":"零售 / 零售的"},{"word":"retailing","pos":"n.","zh":"零售业"},{"word":"retailed","pos":"adj.","zh":"以零售方式售出的"}]}},{"word":"merchandise","ipa_uk":"/ˈmɜːtʃəndaɪs/","ipa_us":"/ˈmɜːrtʃəndaɪz/","definition_zh":"商品；货物；（品牌或作品的）周边商品；推销、把……包装成商品；陈列商品以促进销售","definition_en":"goods offered for sale, or the act of promoting goods by presenting them in an attractive or branded form","core_image":"货架上一排排贴着价签的货物，它们生来就是等着被换走的东西","scene":"货架上的帽子、杯子和海报都印着同一个名字，它们不是日用品，而是被专门摆出来卖的东西。The merchandise sells faster than the tickets themselves.","sceneCN":"商店入口处的架子上摆着帽子、杯子与海报，全都印着同一个名字，卖的是这个名号而不是实用品；句中的 merchandise 指「供出售的商品总称」（第 1 个义项：一切摆在货架上等待成交的货物）。图中可辨识物件：货架、帽子、杯子、海报、价签。","pos":[{"tag":"n.","zh":"商品；货物（总称）"},{"tag":"n.","zh":"（品牌或作品的）周边商品"},{"tag":"v.","zh":"推销；把……包装成商品；陈列商品"}],"collocations":[{"phrase":"general merchandise","zh":"日用百货"},{"phrase":"licensed merchandise","zh":"授权周边商品"},{"phrase":"merchandise trade","zh":"货物贸易"},{"phrase":"merchandise inventory","zh":"商品存货"},{"phrase":"merchandise exports","zh":"货物出口"},{"phrase":"sporting merchandise","zh":"体育用品"}],"forms":[{"label":"三单（推销）","form":"merchandises"},{"label":"过去式","form":"merchandised"},{"label":"过去分词","form":"merchandised"},{"label":"现在分词","form":"merchandising"},{"label":"名词（促销陈列）","form":"merchandising"},{"label":"复数（罕用，指品类）","form":"merchandises"}],"derivatives":[{"word":"merchandising","pos":"n.","zh":"商品促销；陈列设计"},{"word":"merchandiser","pos":"n.","zh":"商品企划人员；促销陈列商"},{"word":"merchandised","pos":"adj.","zh":"以商品形式推出的"}],"senses":[{"no":"01","title":"Goods offered for sale","titleCN":"供出售的商品与货物总称","definition":"goods that are bought and sold, considered as a mass rather than one by one","definitionCN":"被买卖的货物，按整体而不逐件看待","example":"The merchandise sells faster than the tickets themselves.","exampleCN":"这些商品比门票本身卖得还快。","why":"the word descends from the Latin noun for wares, so it names goods as a category rather than a particular item.","whyCN":"这个词源自拉丁语中指「货物」的名词，因此它把货物当作一个类别，而非某一具体物件。"},{"no":"02","title":"Branded fan goods","titleCN":"印有品牌或作品标识的周边商品","definition":"items carrying a brand, band or film name, sold as souvenirs or identity goods","definitionCN":"印有品牌、乐队或影片名称，作为纪念品或身份象征出售的物品","example":"The band made more from merchandise than from the tour.","exampleCN":"这支乐队靠周边商品赚的比巡演还多。","why":"when a name itself becomes the thing bought, the old word for goods narrows to branded goods.","whyCN":"当被买走的是名号本身时，旧的「货物」一词就收窄为带品牌的商品。"},{"no":"03","title":"To promote as a product","titleCN":"把某物包装成商品来推销","definition":"to present something as an attractive product in order to sell it","definitionCN":"把某物呈现为有吸引力的产品以促成出售","example":"The studio merchandised the character across every format.","exampleCN":"工作室把这个角色在各种载体上包装推销。","why":"the noun turned into a verb: to merchandise is to make a thing behave like goods on a shelf.","whyCN":"名词转为动词：所谓推销，就是让一件东西表现得像货架上的商品。"},{"no":"04","title":"To arrange goods for sale","titleCN":"通过陈列与展示促进销售","definition":"to display and present goods in a shop so that customers buy them","definitionCN":"在店内陈列与布置商品，使顾客愿意购买","example":"She merchandised the window with autumn colours.","exampleCN":"她用秋色调布置了橱窗。","why":"in retailing, the verb covers the whole craft of making goods look buyable, from shelf height to lighting.","whyCN":"在零售业，这个动词涵盖让货看起来值得买的一整套手艺，从货架高度到灯光。"},{"no":"05","title":"Goods held as stock in accounts","titleCN":"会计账上列为存货的商品","definition":"goods held for sale and recorded as a current asset in the accounts","definitionCN":"为出售而持有、在账上记为流动资产的产品","example":"The audit found merchandise worth less than the book value.","exampleCN":"审计发现商品的实际价值低于账面价值。","why":"accounting needs a name for goods before they are sold, and it uses the trade word for them.","whyCN":"会计需要为尚未售出的货物取名，于是用了这个行业词。"},{"no":"06","title":"Trade in physical goods","titleCN":"以实物货物为对象的贸易（区别于服务贸易）","definition":"international trade in physical goods, as opposed to trade in services","definitionCN":"以实物货物进行的国际贸易，以区别于服务贸易","example":"Merchandise trade fell while services trade held steady.","exampleCN":"货物贸易下滑，服务贸易则保持平稳。","why":"statistics split trade into goods and services, and the older word for goods supplied the label for the first half.","whyCN":"统计把贸易分为货物与服务两类，而指货物的旧词给了前一类名称。"},{"no":"07","title":"To trade, in older use","titleCN":"古义：做买卖、进行交易","definition":"to buy and sell, or to trade in goods, in older English usage","definitionCN":"在较早的英语中表示买卖或经营货物","example":"Merchants merchandised along the river in those years.","exampleCN":"那些年商人们沿河做买卖。","why":"the verb once meant simply to carry on trade, before the modern sense of packaging goods for sale.","whyCN":"这个动词一度只表示从事交易，后来才出现「把货包装成商品」的现代义。"},{"no":"08","title":"Anything packaged for selling","titleCN":"抽象义：被包装成可售卖形式的内容或形象","definition":"any content, image or idea reshaped so that it can be sold like goods","definitionCN":"任何被重新塑形、可以像货物一样出售的内容、形象或观念","example":"The documentary turned a private grief into merchandise.","exampleCN":"这部纪录片把私人的悲伤变成了可售卖的商品。","why":"the abstract sense strips away the shelf: what is sold is no longer an object but a packaged form.","whyCN":"抽象义抽掉了货架：被卖的不再是实物，而是一种被包装过的形式。"}],"etymology":{"intro":{"en":"Merchandise comes through Old French marchandise from marchand 'merchant', which rests on Latin mercari 'to trade' and the noun merx 'wares'. Dates are approximate.","cn":"merchandise 经古法语 marchandise 来自 marchand「商人」，其根源是拉丁语 mercari「做买卖」与名词 merx「货物」。年代均为约数。"},"items":[{"era":"LATIN MERX","en":"Merx (genitive mercis) meant 'wares, merchandise'. Its deeper origin is not established; the suggestions linking it to other Italic trading words or to Etruscan remain hypotheses.","cn":"merx（属格 mercis）意为「货物、商品」。其更早来源未有定论；把它与其他意大利语族交易词或伊特鲁里亚语相联系的看法仍属假说。"},{"era":"LATIN MERCARI","en":"Mercari 'to trade, deal in goods' is the verb built on merx, and its participle mercatus gave the Latin word for a market.","cn":"mercari「做买卖、经营货物」是由 merx 构成的动词，其分词 mercatus 又给出拉丁语中「市场」一词。"},{"era":"OLD FRENCH MARCHAND","en":"Old French marchand 'merchant, trader' carried the Latin stock into French, and marchandise named what such a trader dealt in.","cn":"古法语 marchand「商人、交易者」把这一拉丁词干带入法语，marchandise 则指这种商人所经营的货。"},{"era":"ENGLISH MERCHANDISE","en":"English borrowed the word in the fourteenth century for goods bought and sold, and the verb followed soon after.","cn":"英语在十四世纪借入这个词指买卖的货物，动词义随后出现。"},{"era":"RETAIL SENSE","en":"In the twentieth century merchandising came to mean the craft of presenting goods, and branded fan goods took the same name.","cn":"到二十世纪，商品陈列与促销成了一门手艺，带品牌的周边商品也用了同一个词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the Latin etymon merx has no agreed pre-Latin origin, so any older form offered for it is a reconstruction.","cn":"来源不确定（更深词根）：拉丁语词源 merx 没有公认的拉丁语之前来源，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same trading root; group two holds ordinary words for things that are sold.","cn":"第一组同出「交易」这一词根；第二组是表示可售之物的常用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"merchant","ipa":"/ˈmɜːtʃənt/","tag":"the person","definition":"A trader in goods, from the same French stem; it names the person where merchandise names the goods.","definitionCN":"经营货物的商人，同出这一法语词干；它指人，而 merchandise 指货。"},{"word":"mercantile","ipa":"/ˌmɜːkənˈtaɪl/","tag":"the adjective","definition":"Relating to trade and merchants, built on the same stem with a Latin adjective suffix.","definitionCN":"与贸易和商人有关的，由同一词干加拉丁形容词后缀构成。"},{"word":"commerce","ipa":"/kəˈmɜːs/","tag":"same root, wider scope","definition":"Trade in general, built with the prefix for 'together' and the same root for wares.","definitionCN":"泛指贸易，由表示「共同」的前缀与同一「货物」词根构成。"},{"word":"market","ipa":"/ˈmɑːkɪt/","tag":"the place","definition":"The place or system of buying and selling, from the Latin participle of the trading verb.","definitionCN":"买卖的场所或体系，来自那个交易动词的拉丁分词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"goods","ipa":"/ɡʊdz/","tag":"plain everyday word","definition":"The ordinary plural noun for things that are sold; merchandise is its commercial and formal counterpart.","definitionCN":"指可售之物的普通复数名词；merchandise 是其商业、正式的说法。"},{"word":"wares","ipa":"/weəz/","tag":"goods for sale","definition":"An older word for articles offered for sale, still used in pottery and street trading.","definitionCN":"指待售物品的较旧说法，仍用于陶器与街头买卖。"},{"word":"stock","ipa":"/stɒk/","tag":"goods held","definition":"Goods kept in a shop or store; it stresses being held rather than being offered.","definitionCN":"店铺或仓库中持有的货物；强调「存放」而非「待售」。"},{"word":"product","ipa":"/ˈprɒdʌkt/","tag":"thing made","definition":"Anything made for sale, seen as the output of production rather than as goods on a shelf.","definitionCN":"为出售而制造的任何东西，着眼点是生产产出而非货架上的货。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real merchant family, the real trade phrases and the real accounting use.","cn":"正常联想使用真实的商人词族、真实的贸易搭配与真实的会计用法。"},"normal":[{"en":"The word and merchant share one stem: the merchant deals in merchandise.","cn":"这个词与「商人」同出一个词干：商人经营的就是商品。"},{"en":"Fixed phrases mark the trade: general merchandise, licensed merchandise, merchandise trade.","cn":"固定搭配标出行业义：日用百货、授权周边、货物贸易。"},{"en":"The same stem gives commerce and market; all three circle buying and selling.","cn":"同一词干还给出「商业」与「市场」，三者都围绕买卖。"},{"en":"In shops, merchandising means how goods are displayed, not what they are.","cn":"在店铺里，商品陈列讲的是货怎么摆，而不是货是什么。"},{"en":"Accounting keeps merchandise for goods not yet sold; once sold, it becomes revenue.","cn":"会计用这个词指尚未售出的货；一旦售出，它就变成收入。"}],"abstract":[{"en":"Picture a shelf where every object wears the same name tag.","cn":"想象一个货架，每件东西都挂着同一个名字的标签。"},{"en":"Picture a memory being wrapped in paper and given a price.","cn":"想象一段回忆被包上纸、标上价格。"},{"en":"Picture a warehouse where the boxes are ideas rather than objects.","cn":"想象一座仓库，箱子里装的不是物品而是观念。"}]},"examples":[{"en":"The shop ordered too much merchandise before the season changed.","cn":"季节变化前，这家店订了太多商品。"},{"en":"Merchandise trade between the two countries fell for a third year.","cn":"两国之间的货物贸易连续第三年下滑。"},{"en":"The museum merchandised its collection into posters, mugs and toys.","cn":"博物馆把藏品做成了海报、杯子和玩具等商品。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「merchant（商人）+ ise」——商人手里经营的东西 → 商品、货物","word":"merchandise"},"root":"古法语 marchandise（货物）来自 marchand（商人），再往上为拉丁语 mercari（做买卖）与 merx（货物）。merx 的更早来源无定论。","sensesIntro":{"en":"Eight senses follow goods from the shelf outward: as stock, as a brand, as something to display, as an accounting entry, as a trade category and finally as anything packaged for sale.","cn":"八个义项让货物从货架向外走：它是存货、是品牌、是要陈列的东西、是账目上的一行、是贸易的一大类，最后成了任何被包装出售之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shelf of objects that all wait to be exchanged for money.","cn":"核心意象：一货架物品，全都等着被换成钱。"},"chain":["WARES","PRICED FOR SALE","BRANDED GOODS","DISPLAYED WELL","COUNTED AS STOCK","TRADE IN GOODS"],"branches":[{"senses":"01 · 07","en":"PLAIN TRADING: goods and the act of trading them are the oldest layer of the word.","cn":"朴素交易：货物与买卖货物这一动作，是这个词最古老的一层。"},{"senses":"02","en":"THE NAME ITSELF: when a brand is what sells, goods become souvenirs of a name.","cn":"名号本身：当卖的是品牌时，货物成了名号的纪念品。"},{"senses":"03 · 04","en":"MAKING IT BUYABLE: the verb covers both packaging a thing and arranging it on a shelf.","cn":"让它值得买：动词既指把东西包装成商品，也指把它摆上货架。"},{"senses":"05 · 06","en":"COUNTING AND TRADE: accounts and statistics both need goods to be a measurable mass.","cn":"记账与贸易：会计与统计都需要把货物当作可计量的一团。"},{"senses":"08","en":"JUST THE PACKAGE: what remains is a form made sellable, with no object underneath.","cn":"只剩包装：剩下的是一种被做成可售的形状，底下并没有实物。"}]},"affixes":{"intro":{"en":"The word is a Latin root for wares plus a French noun ending, and the same root builds several everyday trading words.","cn":"这个词是拉丁语「货物」词根加一个法语名词词尾，同一词根还构成了若干日常交易词。"},"latinIntro":{"en":"Latin merx gives mercari, mercatus, commerce and merchant; the ending marks a noun of state or collection.","cn":"拉丁语 merx 衍生出 mercari、mercatus、商业与商人等词；词尾标记状态或集合名词。"},"items":[{"word":"merx","structure":"merx, mercis (Latin noun, third declension)","meaning":"wares, merchandise","meaningCN":"货物；商品","example":"The root names goods as a mass.","exampleCN":"这个词根把货物当作一团整体来命名。"},{"word":"mercari","structure":"mercari, mercatus sum (Latin verb, first conjugation)","meaning":"to trade, deal","meaningCN":"做买卖；经营","example":"The verb describes the activity behind the goods.","exampleCN":"这个动词描述货物背后的活动。"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, market","meaningCN":"贸易；市场","example":"The participle became the Latin word for a market.","exampleCN":"这个分词成了拉丁语中「市场」一词。"},{"word":"marchand","structure":"marchand (Old French noun, 'merchant')","meaning":"trader","meaningCN":"商人；交易者","example":"The French noun names the person in the trade.","exampleCN":"这个法语名词指从事交易的人。"},{"word":"merchandise","structure":"marchandise (Old French noun)","meaning":"goods for sale","meaningCN":"待售货物","example":"The shelves were full of merchandise.","exampleCN":"货架上摆满了商品。"},{"word":"merchant","structure":"marchand through Old French","meaning":"a trader in goods","meaningCN":"货物商人","example":"The merchant shipped cloth to three ports.","exampleCN":"这位商人把布运往三个港口。"},{"word":"merchandising","structure":"merchandise + -ing (activity)","meaning":"the craft of presenting goods","meaningCN":"商品陈列与促销","example":"Good merchandising lifts sales without a price cut.","exampleCN":"好的陈列能在不降价的情况下提升销量。"},{"word":"merchandiser","structure":"merchandise + -er (one who does)","meaning":"a person who plans product display","meaningCN":"负责商品企划与陈列的人","example":"The merchandiser chose the shelf layout.","exampleCN":"商品企划人员选定了货架布局。"},{"word":"commerce","structure":"com- + merx (Latin commercium)","meaning":"trade together","meaningCN":"共同的交易；商业","example":"Commerce grew along the river.","exampleCN":"商业沿河发展起来。"}],"latinEntries":[{"word":"merx","structure":"merx, mercis (f., third declension)","meaning":"wares, goods","meaningCN":"货物；商品"},{"word":"mercari","structure":"mercari, mercatus sum (verb, first conjugation)","meaning":"to trade","meaningCN":"做买卖"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, market","meaningCN":"贸易；市场"}],"derivatives":[{"word":"merchandising","pos":"n.","zh":"商品促销；陈列设计"},{"word":"merchandiser","pos":"n.","zh":"商品企划人员；促销陈列商"},{"word":"merchandised","pos":"adj.","zh":"以商品形式推出的"}]}},{"word":"inventory","ipa_uk":"/ɪnˈventəri/","ipa_us":"/ɪnˈventɔːri/","definition_zh":"存货；库存；清单、目录；盘点；（把……）列入清单","definition_en":"goods held in stock, or a full list of items recorded one by one","core_image":"仓库门被拉开，每一格里的东西都被记在同一张表上，表与实物一一对应","scene":"盘点员拿着表走过货架，把每一格的数量念出来，表上的数字与格子里的实物一一对上。The inventory showed far more unsold stock than the accounts suggested.","sceneCN":"盘点员沿货架逐格清点，把数量记在表上，纸面数字与实物一一对应；句中的 inventory 指「仓中现存的全部存货」（第 1 个义项：尚未售出、实际存放在库的商品与原料）。图中可辨识物件：盘点表、货架、纸箱、记号笔。","pos":[{"tag":"n.","zh":"存货；库存"},{"tag":"n.","zh":"清单；目录；盘点"},{"tag":"v.","zh":"编制清单；清点存货"}],"collocations":[{"phrase":"inventory control","zh":"库存管理"},{"phrase":"inventory turnover","zh":"存货周转率"},{"phrase":"inventory level","zh":"库存水平"},{"phrase":"take inventory","zh":"盘点存货"},{"phrase":"inventory management","zh":"库存管理"},{"phrase":"personality inventory","zh":"人格量表"}],"forms":[{"label":"复数","form":"inventories"},{"label":"三单（清点）","form":"inventories"},{"label":"过去式","form":"inventoried"},{"label":"过去分词","form":"inventoried"},{"label":"现在分词","form":"inventorying"},{"label":"形容词（清单的）","form":"inventorial"}],"derivatives":[{"word":"inventoried","pos":"adj.","zh":"已列入清单的"},{"word":"inventorying","pos":"n.","zh":"清点存货的过程"},{"word":"inventorial","pos":"adj.","zh":"清单的；存货的"}],"senses":[{"no":"01","title":"Goods held in stock","titleCN":"仓中现存的全部存货","definition":"the goods and materials a business keeps on hand for sale or production","definitionCN":"企业为出售或生产而现存的货物与原料","example":"The inventory showed far more unsold stock than the accounts suggested.","exampleCN":"盘点显示未售出的存货远多于账面上的数字。","why":"the word first meant a list of what was found, and the goods on the list took over the name.","whyCN":"这个词最初指「找到之物」的清单，清单上的货物后来接管了这个名字。"},{"no":"02","title":"A list of items","titleCN":"逐项列出的清单或目录","definition":"a detailed list of goods, property or objects, item by item","definitionCN":"逐项开列货物、财产或物品的详细清单","example":"The museum keeps an inventory of every coin in the vault.","exampleCN":"博物馆为库房里的每一枚硬币留有清单。","why":"this is the oldest sense: an inventory is literally that which has been come upon and written down.","whyCN":"这是最古老的义项：清单字面上就是「被发现并记下来」的东西。"},{"no":"03","title":"Stock as an asset","titleCN":"会计上列为资产的存货","definition":"the value of unsold goods carried as a current asset on a balance sheet","definitionCN":"未售货物作为流动资产列在资产负债表上的价值","example":"Slow inventory tied up the company's cash for a year.","exampleCN":"滞销库存把公司的现金占用了一整年。","why":"accounting turns the physical stock into a number, and keeps the same word for it.","whyCN":"会计把实物存货变成一个数字，却仍用同一个词来称呼。"},{"no":"04","title":"The act of counting stock","titleCN":"清点存货的盘点动作","definition":"the process of counting and checking everything held in stock","definitionCN":"逐件清点并核对库存的过程","example":"The shop closes early on the last day for inventory.","exampleCN":"店铺在盘点那天提前关门。","why":"the noun of result became a noun of action, as happens with many words for lists and records.","whyCN":"结果名词变成了动作名词，这在许多表示清单与记录的词中都会发生。"},{"no":"05","title":"To list and count","titleCN":"编制清单、逐项清点（动词）","definition":"to make a complete list of something or to count stock item by item","definitionCN":"为某物编制完整清单，或逐件清点存货","example":"Staff inventoried the shelves before the refit.","exampleCN":"改装之前，员工清点了货架上的货。","why":"the verb simply applies the list-making act to the object being listed.","whyCN":"动词只是把「造清单」的动作施加到被列的对象上。"},{"no":"06","title":"Stock management as a function","titleCN":"作为管理职能的库存控制","definition":"the function of deciding how much stock to hold and when to reorder","definitionCN":"决定持有多少存货、何时补货的管理职能","example":"Inventory control cut the average holding time by half.","exampleCN":"库存控制把平均持有时间缩短了一半。","why":"once stock is measured, it can be managed, and the word attaches to that managerial function.","whyCN":"存货一旦可以计量，就可以被管理，这个词于是附在这一管理职能上。"},{"no":"07","title":"A scored questionnaire","titleCN":"心理学中逐项评分的人格量表","definition":"a set of scored questions used to measure traits such as personality or depression","definitionCN":"用逐项评分来测量人格或抑郁等特征的一套题目","example":"The personality inventory flagged high anxiety but normal mood.","exampleCN":"这份人格量表显示焦虑偏高，情绪则属正常。","why":"psychology borrowed the list sense: a person is checked item by item, as goods are on a shelf.","whyCN":"心理学借用了清单义：人被逐项核对，正如货架上的货被逐件清点。"},{"no":"08","title":"A full assessment of one's resources","titleCN":"抽象义：对自身资源与处境的全面清点","definition":"a careful review of what one has, whether skills, debts or memories","definitionCN":"对自己拥有之物——技能、债务或记忆——的仔细梳理","example":"At fifty she took inventory of her life and changed course.","exampleCN":"五十岁时她清点了自己的人生，随后改变了方向。","why":"the image of counting every item generalizes to counting everything one has, including what cannot be seen.","whyCN":"逐件清点的意象被一般化，用来数自己拥有的一切，包括看不见的东西。"}],"etymology":{"intro":{"en":"Inventory comes from Medieval Latin inventorium 'a list of things found', built on the Latin verb invenire 'to come upon, find'. Dates are approximate.","cn":"inventory 来自中世纪拉丁语 inventorium「所列之物的清单」，其词根是拉丁语动词 invenire「遇到、发现」。年代均为约数。"},"items":[{"era":"LATIN VENIRE","en":"Venire 'to come' is the base verb; the prefix in- adds the idea of coming upon something.","cn":"venire「来」是基础动词，前缀 in- 增添「碰上、遇到」的意思。"},{"era":"LATIN INVENIRE","en":"Invenire meant 'to come upon, find, discover', and its participle inventum supplied the stem of the later noun.","cn":"invenire 意为「遇到、找到、发现」，其分词 inventum 提供了后来名词的词干。"},{"era":"MEDIEVAL LATIN INVENTORIUM","en":"Medieval Latin inventorium named a written list of goods or property found on an estate, drawn up item by item.","cn":"中世纪拉丁语 inventorium 指对某处产业中查得之物逐项开列的书面清单。"},{"era":"ENGLISH INVENTORY","en":"English adopted the word in the fifteenth century for such a list, and later for the goods themselves and the act of counting them.","cn":"英语在十五世纪采用这个词指这类清单，后来又用它指货物本身以及清点的动作。"},{"era":"MODERN BUSINESS","en":"With industrial retailing, inventory became a managed asset, and the word moved into accounting, logistics and computing.","cn":"随着工业化零售，存货成为被管理的资产，这个词也进入会计、物流与计算机领域。"}]},"similar":{"note":{"en":"Group one holds words from the same 'find' root that are often confused; group two holds words for goods held or for lists.","cn":"第一组同出「发现」这一词根，常被混淆；第二组指持有之物或清单。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"invent","ipa":"/ɪnˈvent/","tag":"same root, make new","definition":"The same verb 'to come upon': to devise something that did not exist, originally to find it out.","definitionCN":"同出「遇到」这一动词：创造出原先没有的东西，原义是把它找出来。"},{"word":"invention","ipa":"/ɪnˈvenʃn/","tag":"the made thing","definition":"The act or product of devising something new, from the same stem as inventory.","definitionCN":"设计出新事物的动作或产物，与 inventory 同出一个词干。"},{"word":"inventor","ipa":"/ɪnˈventə/","tag":"the person","definition":"The one who devises something new; the ending marks a person, where inventory marks a list.","definitionCN":"设计出新事物的人；词尾标记人，而 inventory 标记清单。"},{"word":"inventive","ipa":"/ɪnˈventɪv/","tag":"the quality","definition":"Able to devise new things, built on the same stem with an adjective suffix.","definitionCN":"能够设计出新事物的，由同一词干加形容词后缀构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stock","ipa":"/stɒk/","tag":"British everyday word","definition":"Goods kept for sale, the usual British term where American business says inventory.","definitionCN":"为出售而持有的货物；英式常用这个词，美式商业则用 inventory。"},{"word":"stockpile","ipa":"/ˈstɒkpaɪl/","tag":"large reserve","definition":"A large store built up deliberately, often of essentials; it stresses accumulation over routine stock.","definitionCN":"有意囤积的大量储备，常指必需品；强调积累而非日常库存。"},{"word":"catalogue","ipa":"/ˈkætəlɒɡ/","tag":"list for users","definition":"A list of items arranged for reference or sale; an inventory is a list for checking and control.","definitionCN":"为查阅或销售而编排的物品清单；inventory 是为核对与控制而作的清单。"},{"word":"ledger","ipa":"/ˈledʒə/","tag":"financial record","definition":"The book of accounts; an inventory counts goods, a ledger records money.","definitionCN":"账册；inventory 清点货物，ledger 记录钱款。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real 'find' root, the real business phrases and the real psychological use.","cn":"正常联想使用真实的「发现」词根、真实的商业搭配与真实的心理测量用法。"},"normal":[{"en":"The root means 'to come upon': an inventory is what you find when you go through every shelf.","cn":"词根意为「遇到、发现」：清单就是你走遍每个货架后查到的东西。"},{"en":"The family runs invent, invention, inventor and inventive, all from the same 'find' stem.","cn":"同族词包括发明、发明物、发明家与有创造力的，都出同一「发现」词干。"},{"en":"Fixed phrases mark it: inventory control, inventory turnover, take inventory.","cn":"固定搭配标出这个词：库存控制、存货周转、盘点。"},{"en":"British shops say stock where American accounts say inventory.","cn":"英国店铺多说 stock，美国会计多说 inventory。"},{"en":"A personality inventory checks a person item by item, like goods on a shelf.","cn":"人格量表逐项检查一个人，正如逐件清点货架上的货。"}],"abstract":[{"en":"Picture a clipboard that turns a room full of objects into numbered lines.","cn":"想象一块写字板，把满屋的东西变成一行行编号。"},{"en":"Picture a life laid out on a table and counted like coins.","cn":"想象一段人生被摊在桌上，像硬币一样被清点。"},{"en":"Picture a warehouse whose shelves are questions rather than boxes.","cn":"想象一座仓库，货架上放的不是箱子而是问题。"}]},"examples":[{"en":"The warehouse holds two months of inventory at all times.","cn":"这座仓库始终保有两个月的存货。"},{"en":"They took inventory and found a third of the stock missing.","cn":"他们盘点后发现三分之一的存货不见了。"},{"en":"Inventory turnover tells you how quickly goods are sold.","cn":"存货周转率说明货物卖得有多快。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（在内）+ vent（来）+ ory」——把里面查到的东西都记下来 → 清单、存货","word":"inventory"},"root":"中世纪拉丁语 inventorium（查得之物的清单）来自拉丁语 invenire（遇到、找到）＝in-（向内、在上）＋venire（来）。同族词有 invent、invention、inventor。","sensesIntro":{"en":"Eight senses begin with a list of things found and then follow the goods on that list into accounting, management, psychology and finally into a private accounting of one's own life.","cn":"八个义项从「查得之物的清单」开始，再让清单上的货物走进会计、管理、心理学，最后走进一个人对自己人生的私下清点。"},"semanticMap":{"core":{"en":"CORE IMAGE: a clipboard that turns a room of objects into numbered lines.","cn":"核心意象：一块写字板，把满屋物品变成一行行编号。"},"chain":["FIND","WRITE DOWN","LIST OF ITEMS","GOODS ON HAND","COUNT AND CHECK","MANAGE THE STOCK"],"branches":[{"senses":"01 · 02","en":"FOUND AND LISTED: the goods and the list are two sides of the same act of finding.","cn":"查到并记下：货物与清单是同一个「查」的动作的两面。"},{"senses":"03 · 06","en":"MEASURED AND MANAGED: once counted, stock becomes an asset and then a function.","cn":"计量与管理：一旦被清点，存货就成为资产，随后成为一项职能。"},{"senses":"04 · 05","en":"THE COUNT ITSELF: the noun of result turns into a noun and then a verb of counting.","cn":"清点本身：结果名词转为动作名词，再转为动词。"},{"senses":"07","en":"A PERSON SCORED: psychology counts a person as a shop counts goods.","cn":"被评分的人：心理学数人，正如店铺数货。"},{"senses":"08","en":"ONE'S OWN LEDGER: the last count is of resources that never sat on a shelf.","cn":"自己的账：最后一次清点的是从未上过货架的资源。"}]},"affixes":{"intro":{"en":"The word is a Latin prefix, a Latin verb and a medieval noun ending, and the family is shared with invention.","cn":"这个词由一个拉丁前缀、一个拉丁动词与一个中世纪名词词尾构成，与「发明」一族共享词干。"},"latinIntro":{"en":"Latin venire gives invent, invention and inventory; the prefix marks finding, and the ending marks a place or collection.","cn":"拉丁语 venire 衍生出「发明」「发明物」与「清单」；前缀标记「找到」，词尾标记处所或集合。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, upon')","meaning":"in; upon","meaningCN":"在内；在上","example":"The prefix turns coming into coming upon something.","exampleCN":"这个前缀把「来」变成「碰上某物」。"},{"word":"venire","structure":"venire, veni, ventum (Latin verb, fourth conjugation)","meaning":"to come","meaningCN":"来","example":"The root is the plain verb of motion.","exampleCN":"这个词根就是表示移动的普通动词。"},{"word":"invenire","structure":"in- + venire (Latin verb)","meaning":"to come upon, find","meaningCN":"遇到；找到","example":"Invenire is the act behind both invention and inventory.","exampleCN":"这个词既是「发明」也是「清单」背后的动作。"},{"word":"inventum","structure":"inventum (Latin participle, 'found')","meaning":"that which is found","meaningCN":"被找到之物","example":"The participle supplies the noun stem.","exampleCN":"这个分词提供了名词词干。"},{"word":"inventorium","structure":"inventorium (Medieval Latin noun)","meaning":"a list of things found","meaningCN":"查得之物的清单","example":"The medieval list named every item on the estate.","exampleCN":"这份中世纪清单列出了产业上的每一项。"},{"word":"inventory","structure":"inventorium through Anglo-French","meaning":"stock or a stock list","meaningCN":"存货或存货清单","example":"The inventory filled three pages.","exampleCN":"这份清单写满了三页。"},{"word":"invent","structure":"invenire through French","meaning":"to devise something new","meaningCN":"发明；设计出新事物","example":"She invented a quieter pump.","exampleCN":"她发明了一种更安静的泵。"},{"word":"invention","structure":"invent + -ion (act or result)","meaning":"the act or product of devising","meaningCN":"发明的动作或产物","example":"The invention changed the trade.","exampleCN":"这项发明改变了这个行业。"},{"word":"inventoried","structure":"inventory + -ed (past participle)","meaning":"entered in a list","meaningCN":"已列入清单的","example":"Every crate was inventoried.","exampleCN":"每一只箱子都被登记在册。"}],"latinEntries":[{"word":"venire","structure":"venire, veni, ventum (verb, fourth conjugation)","meaning":"to come","meaningCN":"来"},{"word":"invenire","structure":"invenire, inveni, inventum (verb, fourth conjugation)","meaning":"to come upon, find","meaningCN":"遇到；找到"},{"word":"inventorium","structure":"inventorium, inventori (n., second declension, Medieval Latin)","meaning":"a list of things found","meaningCN":"查得之物的清单"}],"derivatives":[{"word":"inventoried","pos":"adj.","zh":"已列入清单的"},{"word":"inventorying","pos":"n.","zh":"清点存货的过程"},{"word":"inventorial","pos":"adj.","zh":"清单的；存货的"}]}},{"word":"warehouse","ipa_uk":"/ˈweəhaʊs/","ipa_us":"/ˈwerhaʊs/","definition_zh":"仓库；货栈；把（货物）存入仓库；大型仓储式商店","definition_en":"a large building where goods are stored, or to place goods in such a building","core_image":"一栋没有橱窗的大房子，里面只有货架、托盘与叉车，货进来后等着再出去","scene":"叉车把托盘推进高大的货架深处，卷帘门在身后落下，这些货要等到下一批订单才会被取出。The warehouse holds the pallets until the shops place their orders.","sceneCN":"卷帘门在叉车后落下，整托货物被推进高架深处，等待着下一批订单；句中的 warehouse 指「存放货物、等待再运出的大建筑」（第 1 个义项：以储藏为主要功能的建筑）。图中可辨识物件：叉车、托盘、高货架、卷帘门。","pos":[{"tag":"n.","zh":"仓库；货栈"},{"tag":"v.","zh":"把（货物）存入仓库"},{"tag":"n.","zh":"大型仓储式商店（定语）"}],"collocations":[{"phrase":"warehouse manager","zh":"仓库主管"},{"phrase":"warehouse space","zh":"仓储空间"},{"phrase":"bonded warehouse","zh":"保税仓库"},{"phrase":"warehouse club","zh":"仓储式会员店"},{"phrase":"data warehouse","zh":"数据仓库"},{"phrase":"warehouse receipt","zh":"仓单"}],"forms":[{"label":"复数","form":"warehouses"},{"label":"三单（存入仓库）","form":"warehouses"},{"label":"过去式","form":"warehoused"},{"label":"过去分词","form":"warehoused"},{"label":"现在分词","form":"warehousing"},{"label":"名词（仓储业）","form":"warehousing"}],"derivatives":[{"word":"warehousing","pos":"n.","zh":"仓储；仓储业"},{"word":"warehoused","pos":"adj.","zh":"已存入仓库的"},{"word":"warehouseman","pos":"n.","zh":"仓库管理员；仓储工人"}],"senses":[{"no":"01","title":"A building for storing goods","titleCN":"存放货物、等待再运出的大建筑","definition":"a large building in which goods are kept until they are sold or moved on","definitionCN":"货物在售出或转运之前被存放其中的大型建筑","example":"The warehouse holds the pallets until the shops place their orders.","exampleCN":"仓库持有这些托盘，直到店铺下单为止。","why":"the compound joins the old word for goods with the word for a house, so the name says exactly what the building is for.","whyCN":"这个复合词把指货物的旧词与指房屋的词拼在一起，名称直接说明了建筑的用途。"},{"no":"02","title":"To store goods in such a building","titleCN":"把货物存入仓库（动词）","definition":"to place goods in a warehouse for keeping","definitionCN":"把货物放入仓库保存","example":"The grain was warehoused until prices improved.","exampleCN":"谷物被存入仓库，等价格好转再出。","why":"the building's name became a verb for putting things into it, a common shift in English.","whyCN":"建筑的名称变成了「把东西放进去」的动词，这在英语中很常见。"},{"no":"03","title":"A large no-frills shop","titleCN":"以仓储式陈列经营的大型商店","definition":"a large shop that displays goods on pallets in a plain building, often selling to members","definitionCN":"在朴素建筑里以托盘方式陈列货物、常面向会员销售的大型商店","example":"The warehouse club sells flour by the fifty-kilo sack.","exampleCN":"仓储式会员店按五十公斤一袋卖面粉。","why":"the shop borrows the building's look: goods sit on pallets, the room is plain, and the price is low.","whyCN":"这种商店借用了仓库的样子：货放在托盘上，空间朴素，价格低廉。"},{"no":"04","title":"The dispatch end of online selling","titleCN":"网络零售的配送仓储中心","definition":"a centre where goods are stored and packed for delivery to individual customers","definitionCN":"存放货物并打包、直接送往个人顾客的中心","example":"The online seller runs one warehouse for the whole country.","exampleCN":"这家网商在全国只用一个仓储中心。","why":"when the shop moves online, the warehouse takes over the packing that the shop counter once did.","whyCN":"商店搬到网上后，原本由柜台完成的打包工作转由仓库承担。"},{"no":"05","title":"A customs-controlled store","titleCN":"受海关监管、关税暂缓的保税仓库","definition":"a secured store where imported goods may be held before duty is paid","definitionCN":"进口货物在缴纳关税前可存放其中的受监管仓库","example":"The wine stayed in a bonded warehouse for two years.","exampleCN":"这批葡萄酒在保税仓库里放了两年。","why":"the state needs a place where goods are physically present but not yet legally imported, and calls it a warehouse.","whyCN":"国家需要一个地方，让货物实际在场但在法律上尚未进口，于是称之为仓库。"},{"no":"06","title":"A store of data in computing","titleCN":"计算机系统中的数据仓库","definition":"a central store that holds data gathered from many systems for analysis","definitionCN":"汇集来自多个系统的数据、供分析之用的中央存储","example":"The data warehouse pulls figures from every branch.","exampleCN":"数据仓库从每个分支机构抽取数据。","why":"computing reuses the building: data is stacked and kept, then drawn out when needed.","whyCN":"计算机领域复用了这座建筑：数据被堆起来保存，需要时再取出。"},{"no":"07","title":"Storage as a business","titleCN":"作为行业的仓储与仓储设施","definition":"the business of storing goods for others, or the space used for it","definitionCN":"替他人存放货物的行业，或用于此事的空间","example":"Warehousing near the port is cheaper than inland.","exampleCN":"港口附近的仓储比内陆便宜。","why":"once storage is sold as a service, the building's name extends to the trade and to the space itself.","whyCN":"当储存作为服务出售时，建筑名就扩展到整个行业以及所占的空间。"},{"no":"08","title":"A store of memories or records","titleCN":"抽象义：存放记忆或资料的储藏处","definition":"a place or system that keeps large amounts of memories, records or material","definitionCN":"保存大量记忆、记录或材料的场所或系统","example":"The archive is a warehouse of the city's ordinary voices.","exampleCN":"这座档案馆存放着这座城市普通人的声音。","why":"the physical image survives without walls: whatever is kept in quantity can be called a warehouse.","whyCN":"实体意象在没有墙壁时仍然成立：任何被大量保存的东西都可以叫仓库。"}],"etymology":{"intro":{"en":"Warehouse is a native English compound of ware 'goods' and house, both inherited from Old English. Dates are approximate.","cn":"warehouse 是英语本族复合词，由 ware「货物」与 house「房屋」构成，两者都承自古代英语。年代均为约数。"},"items":[{"era":"OLD ENGLISH WARU","en":"Waru meant 'goods, articles of merchandise, a kept thing', and its descendant ware survives in wares and in compounds.","cn":"waru 意为「货物、商品、被保存之物」，其后代 ware 仍存于「货品」及若干复合词中。"},{"era":"OLD ENGLISH HŪS","en":"Hūs meant 'house, dwelling, shelter', the direct ancestor of house.","cn":"hūs 意为「房屋、住所、遮蔽处」，是 house 的直接祖先。"},{"era":"MIDDLE ENGLISH COMPOUND","en":"Ware plus house named a building where goods were kept, and the word is recorded from the medieval period.","cn":"「货物」加「房屋」指存放货物的建筑，这个词在中世纪已有记载。"},{"era":"TRADE SENSE","en":"With overseas trade the warehouse became a port institution, with receipts, customs control and bonded storage.","cn":"随着海外贸易，仓库成为港口制度的一部分，出现仓单、海关监管与保税存放。"},{"era":"MODERN FORMATS","en":"The twentieth century added the warehouse club and the distribution centre, and computing added the data warehouse.","cn":"二十世纪添了仓储式会员店与配送中心，计算机领域又添了数据仓库。"}]},"similar":{"note":{"en":"Group one holds words built from the same two halves or their near kin; group two holds names for places that store things.","cn":"第一组由同样的两半或其近亲构成；第二组是存放物品的场所之名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ware","ipa":"/weə/","tag":"the first half","definition":"An old word for manufactured goods or articles for sale, still heard in wares and earthenware.","definitionCN":"指制成品或待售物品的旧词，仍见于「货品」与「陶器」等说法。"},{"word":"house","ipa":"/haʊs/","tag":"the second half","definition":"The ordinary word for a dwelling or building; in the compound it simply supplies the building.","definitionCN":"指住所或建筑的常用词；在复合词里只提供「建筑」这一层。"},{"word":"warehousing","ipa":"/ˈweəhaʊzɪŋ/","tag":"the activity","definition":"The business or process of storing goods; the longer form names the activity, not the building.","definitionCN":"存放货物的业务或过程；较长的形式指活动，而非建筑。"},{"word":"warehouseman","ipa":"/ˈweəhaʊsmən/","tag":"the person","definition":"A worker who handles goods in a warehouse; the compound plus a person suffix names the job.","definitionCN":"在仓库中搬运货物的人；复合词加表人后缀构成职业名。"}]},{"heading":"NEAR MEANING","entries":[{"word":"depot","ipa":"/ˈdiːpəʊ/","tag":"transport focus","definition":"A place where vehicles are kept or goods are received for transport; it stresses movement rather than storage.","definitionCN":"停放车辆或接收待运货物之处；强调运输而非储存。"},{"word":"storehouse","ipa":"/ˈstɔːhaʊs/","tag":"plain synonym","definition":"A building for storing things, close in meaning but without the commercial and customs associations.","definitionCN":"存放物品的建筑，意思接近，但不带商业与海关的联想。"},{"word":"stockroom","ipa":"/ˈstɒkruːm/","tag":"small scale","definition":"The room at the back of a shop where reserve stock is kept; much smaller than a warehouse.","definitionCN":"商店后面存放备用存货的房间，比仓库小得多。"},{"word":"distribution centre","ipa":"/dɪstrɪˈbjuːʃn ˈsentə/","tag":"flow focus","definition":"A large facility that sorts and sends goods onward; storage is a means, not the purpose.","definitionCN":"对货物进行分拣并继续发运的大型设施；储存只是手段而非目的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real halves, the real modern formats and the real customs phrase.","cn":"正常联想使用真实的两半、真实的现代业态与真实的海关说法。"},"normal":[{"en":"Ware plus house: a house for goods, not for people.","cn":"「货物」加「房屋」：给货住的房子，不是给人住的。"},{"en":"The family runs warehouse, warehousing, warehoused and warehouseman.","cn":"同族词包括仓库、仓储、已入库的与仓库工人。"},{"en":"Fixed phrases mark it: bonded warehouse, warehouse club, data warehouse.","cn":"固定搭配标出这个词：保税仓库、仓储式会员店、数据仓库。"},{"en":"A warehouse has no shop window; its whole purpose is to keep things out of view.","cn":"仓库没有橱窗；它的全部用途就是把东西放在看不见的地方。"},{"en":"Online selling turned the warehouse into the busiest part of the shop.","cn":"网络销售把仓库变成了店铺里最忙碌的部分。"}],"abstract":[{"en":"Picture a building with no windows and a door that only opens for trucks.","cn":"想象一栋没有窗、门只为货车而开的建筑。"},{"en":"Picture shelves that hold seasons of goods in silence.","cn":"想象一排排货架，静默地囤着好几个季节的货。"},{"en":"Picture a mind that stacks memories on pallets and fetches them years later.","cn":"想象一颗心把记忆码在托盘上，多年后再取出来。"}]},"examples":[{"en":"The warehouse is full, so new stock waits on the trucks.","cn":"仓库已满，新货只能在车上等着。"},{"en":"Goods in a bonded warehouse are stored before duty is paid.","cn":"保税仓库中的货物在缴税前存放。"},{"en":"The company warehoused the surplus rather than discount it.","cn":"公司把余货入库，而不是打折卖掉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ware（货物）+ house（房子）」——放货物的房子 → 仓库","word":"warehouse"},"root":"英语本族复合词：ware（货物，古英语 waru）＋house（房屋，古英语 hūs），字面即「放货的房子」，与拉丁语无同族关系。","sensesIntro":{"en":"Eight senses begin with a plain building for goods and then follow the same shape into shops, delivery centres, customs control, computing and finally into any store of kept things.","cn":"八个义项从一座放货的朴素建筑开始，再让同一形状走进商店、配送中心、海关监管、计算机，最后成为任何储藏之所。"},"semanticMap":{"core":{"en":"CORE IMAGE: a windowless building where pallets wait behind a rolling door.","cn":"核心意象：一栋没有窗的建筑，托盘在卷帘门后等待。"},"chain":["GOODS","A HOUSE FOR THEM","KEEP UNTIL NEEDED","SEND ONWARD","CONTROL BY RULE","STORE ANYTHING"],"branches":[{"senses":"01 · 07","en":"THE BUILDING AND THE TRADE: storage is first a place, then a service sold by the square metre.","cn":"建筑与行业：储存先是一个场所，后来成为按面积出售的服务。"},{"senses":"02 · 04","en":"PUT IN AND SEND OUT: the verb and the delivery centre are the two directions of the same door.","cn":"放入与发出：动词与配送中心是同一扇门的两个方向。"},{"senses":"03","en":"THE LOOK BECOMES A SHOP: pallets and plain aisles are turned into a retail format.","cn":"样子变成商店：托盘与朴素通道被改造成一种零售业态。"},{"senses":"05","en":"HELD BY LAW: goods may sit physically present yet not legally entered.","cn":"受法律扣留：货物可以实际在场，却在法律上尚未入境。"},{"senses":"06 · 08","en":"NO WALLS NEEDED: data and memories are stacked and fetched in exactly the same shape.","cn":"无需墙壁：数据与记忆以完全相同的形状被堆放和取出。"}]},"affixes":{"intro":{"en":"The word is two Old English nouns joined, so there is no Latin affix to read.","cn":"这个词由两个古英语名词并合而成，因此没有拉丁词缀可拆。"},"latinIntro":{"en":"No Latin entries apply: both halves are inherited Germanic words.","cn":"不适用拉丁条目：两半都是承继的日耳曼语词。"},"items":[{"word":"ware","structure":"ware (Old English waru, 'goods')","meaning":"goods, articles for sale","meaningCN":"货物；待售物品","example":"The ware in the yard was stacked high.","exampleCN":"场院里的货物堆得很高。"},{"word":"house","structure":"house (Old English hūs, 'dwelling')","meaning":"a building","meaningCN":"建筑；房屋","example":"The house has no windows on the street.","exampleCN":"这栋房子临街一面没有窗。"},{"word":"warehouse","structure":"ware + house (compound noun)","meaning":"a building for goods","meaningCN":"存放货物的建筑","example":"The warehouse holds the winter stock.","exampleCN":"仓库存着冬季的货。"},{"word":"warehouse","structure":"warehouse (verb, zero derivation)","meaning":"to store in such a building","meaningCN":"存入仓库","example":"They warehoused the grain for a year.","exampleCN":"他们把谷物存了一年。"},{"word":"warehousing","structure":"warehouse + -ing (activity)","meaning":"the business of storing","meaningCN":"仓储业务","example":"Warehousing takes space near the port.","exampleCN":"仓储需要在港口附近占用空间。"},{"word":"warehoused","structure":"warehouse + -ed (past participle)","meaning":"placed in storage","meaningCN":"已存入仓库的","example":"The goods were warehoused until spring.","exampleCN":"货物入库直到春天。"},{"word":"warehouseman","structure":"warehouse + man (person)","meaning":"a store worker","meaningCN":"仓库工人","example":"The warehouseman checked every pallet.","exampleCN":"仓库工人检查了每个托盘。"},{"word":"warehouse club","structure":"warehouse + club (compound noun)","meaning":"a members' bulk shop","meaningCN":"仓储式会员店","example":"The warehouse club sells in large packs.","exampleCN":"仓储式会员店按大包装出售。"}],"latinEntries":[],"derivatives":[{"word":"warehousing","pos":"n.","zh":"仓储；仓储业"},{"word":"warehoused","pos":"adj.","zh":"已存入仓库的"},{"word":"warehouseman","pos":"n.","zh":"仓库管理员；仓储工人"}]}},{"word":"procurement","ipa_uk":"/prəˈkjʊəmənt/","ipa_us":"/prəˈkjʊrmənt/","definition_zh":"采购；（机构）取得货物与服务的过程；获得","definition_en":"the process by which an organization obtains goods and services, or the act of obtaining something","core_image":"一张需求单从部门递出，经过比价与签约，最后变成仓库门口的一批货","scene":"需求单在几个部门之间传了一轮，几份报价摊在桌上，最后一份合同签下，货物才被允许进门。Public procurement must follow open tendering rules.","sceneCN":"需求、比价、签约三道手续走完，货物才被允许进门；句中的 procurement 指「机构取得货物与服务的整个采购过程」（第 1 个义项：从提出需求到签订合同、完成交付的流程）。图中可辨识物件：需求单、报价单、合同、仓库门。","pos":[{"tag":"n.","zh":"采购；采购过程"},{"tag":"n.","zh":"获得、取得（正式用语）"}],"collocations":[{"phrase":"public procurement","zh":"政府采购"},{"phrase":"procurement process","zh":"采购流程"},{"phrase":"procurement officer","zh":"采购主管"},{"phrase":"green procurement","zh":"绿色采购"},{"phrase":"e-procurement","zh":"电子采购"},{"phrase":"defence procurement","zh":"国防采购"}],"forms":[{"label":"复数","form":"procurements"},{"label":"动词（采购）","form":"procure"},{"label":"三单","form":"procures"},{"label":"过去式","form":"procured"},{"label":"现在分词","form":"procuring"},{"label":"形容词（可获得的）","form":"procurable"}],"derivatives":[{"word":"procure","pos":"v.","zh":"采购；取得"},{"word":"procurable","pos":"adj.","zh":"可获得的；可采购到的"},{"word":"procurer","pos":"n.","zh":"采购者；取得者"},{"word":"procuration","pos":"n.","zh":"取得；代理办理"}],"senses":[{"no":"01","title":"An organization's buying process","titleCN":"机构取得货物与服务的采购流程","definition":"the whole process by which an organization obtains the goods and services it needs","definitionCN":"机构为取得所需货物与服务而走的整个流程","example":"Public procurement must follow open tendering rules.","exampleCN":"政府采购必须遵守公开招标规则。","why":"the word began as a term for managing affairs on someone's behalf, and buying is the part of that care that leaves a paper trail.","whyCN":"这个词原指替他人料理事务，而采购正是这种照料中会留下纸面痕迹的那一部分。"},{"no":"02","title":"The purchasing department","titleCN":"承担采购职能的部门","definition":"the department or team responsible for buying on behalf of the organization","definitionCN":"代表机构负责采购的部门或团队","example":"Procurement blocked the order until three quotes arrived.","exampleCN":"采购部门压住订单，直到收到三份报价。","why":"the process gave its name to the unit that runs it, a common shift in institutional language.","whyCN":"流程把名字给了执行它的单位，这是机构用语中常见的转称。"},{"no":"03","title":"Government buying","titleCN":"以公共资金进行的政府采购","definition":"the purchase of goods and works by public bodies with public money","definitionCN":"公共机构用公共资金购买货物与工程","example":"Government procurement is opened to foreign bidders.","exampleCN":"政府采购向外国投标者开放。","why":"public money requires rules of fairness, so the general word is paired with the word for the state.","whyCN":"公共资金要求公平规则，因此一般词前面加上了指国家的词。"},{"no":"04","title":"Military supply acquisition","titleCN":"军需物资与装备的采购","definition":"the obtaining of weapons, supplies and services for armed forces","definitionCN":"为武装部队取得武器、物资与服务","example":"Defence procurement ran years behind the schedule.","exampleCN":"国防采购比计划晚了数年。","why":"armed forces buy in secret and at scale, so their buying developed its own vocabulary around the same word.","whyCN":"军队的秘密大批采购使同一词在其内部发展出专门说法。"},{"no":"05","title":"Buying through digital systems","titleCN":"通过电子系统完成的采购","definition":"the use of online platforms and systems to buy goods and services","definitionCN":"利用网络平台与系统购买货物与服务","example":"E-procurement cut the order cycle from weeks to days.","exampleCN":"电子采购把订单周期从数周缩短到数日。","why":"the channel changed, not the act, so a short prefix marks the electronic form.","whyCN":"变的是渠道而不是行为，因此只用一个短前缀标出电子形式。"},{"no":"06","title":"Buying with environmental criteria","titleCN":"把环境标准纳入评审的绿色采购","definition":"buying that includes environmental and social conditions in its award criteria","definitionCN":"在评标标准中纳入环境与社会条件的采购","example":"Green procurement favoured recycled paper and low-emission vans.","exampleCN":"绿色采购偏向再生纸与低排放货车。","why":"when price is no longer the only measure, an adjective is added to the same process.","whyCN":"当价格不再是唯一尺度时，只需在同一流程前加一个形容词。"},{"no":"07","title":"Obtaining something in general","titleCN":"正式用语中一般的「取得、获得」","definition":"the obtaining of something abstract, such as funds or evidence","definitionCN":"取得某种抽象之物，如资金或证据","example":"The procurement of funds delayed the whole project.","exampleCN":"资金迟迟未能取得，拖住了整个项目。","why":"the older and wider sense survives in formal prose, where what is obtained need not be goods.","whyCN":"较旧而较宽的含义留在正式文体中，被取得的东西不一定是货物。"},{"no":"08","title":"Buying as a strategic choice","titleCN":"作为战略决策的采购（自制或外购）","definition":"the strategic decision about what to make in house and what to buy outside","definitionCN":"决定什么自己做、什么向外部购买的策略选择","example":"Procurement now sits at the table when products are designed.","exampleCN":"如今产品设计时，采购部门也坐在桌边。","why":"once buying is planned rather than clerical, it becomes a lever on cost, risk and design.","whyCN":"当采购从文书工作变成事先规划，它就成了影响成本、风险与设计的杠杆。"}],"etymology":{"intro":{"en":"Procurement comes through Old French from Latin procurare 'to take care of, attend to', built on pro- 'for' and curare 'to care for'. Dates are approximate.","cn":"procurement 经古法语来自拉丁语 procurare「照料、料理」，由表示「为了、代表」的前缀与 curare「关心、照料」构成。年代均为约数。"},"items":[{"era":"LATIN CURA","en":"Cura meant 'care, concern, careful attention', and it also lies behind cure, accurate and curious.","cn":"cura 意为「关心、忧虑、仔细留意」，它也是「治愈」「准确的」「好奇的」等词的根源。"},{"era":"LATIN CURARE","en":"Curare 'to care for, look after, attend to' is the verb formed from cura.","cn":"curare「照料、看护、料理」是由 cura 构成的动词。"},{"era":"LATIN PROCURARE","en":"Pro- 'for, on behalf of' plus curare gave procurare 'to take care of something for someone, to manage'.","cn":"表示「为了、代表」的前缀加 curare 构成 procurare「替某人料理某事、管理」。"},{"era":"OLD FRENCH PROCURER","en":"Old French procurer meant 'to manage, take care of, obtain', and English borrowed it in the fourteenth century.","cn":"古法语 procurer 意为「管理、照料、取得」，英语在十四世纪借入。"},{"era":"ENGLISH PROCUREMENT","en":"The noun first meant management or the care of affairs, and only later narrowed to the obtaining of supplies.","cn":"这个名词最初指管理或料理事务，后来才收窄为取得物资。"},{"era":"MODERN BUYING","en":"In the twentieth century the word settled on formal institutional buying, with tenders, contracts and audit trails.","cn":"到二十世纪，这个词固定指机构的正式采购，伴随招标、合同与审计记录。"}]},"similar":{"note":{"en":"Group one holds words from the same 'care' root whose meanings have diverged; group two holds words for buying.","cn":"第一组同出「关心、照料」这一词根，意义已各自分化；第二组是表示购买的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"procure","ipa":"/prəˈkjʊə/","tag":"the verb","definition":"To obtain something, often with effort; the noun names the organized process that does it.","definitionCN":"取得某物，常需费一番功夫；名词指把这件事组织起来的流程。"},{"word":"procurator","ipa":"/ˌprɒkjʊˈreɪtə/","tag":"an officer","definition":"An official who acts on another's behalf, from the same root; it kept the old sense of managing for someone.","definitionCN":"代表他人行事的官员，同出该词根；保留了「替人管理」的旧义。"},{"word":"accurate","ipa":"/ˈækjərət/","tag":"done with care","definition":"Built from the prefix for 'to' plus the care verb: something done carefully, hence exact.","definitionCN":"由表示「朝向」的前缀加「照料」动词构成：仔细做成，因此精确。"},{"word":"curious","ipa":"/ˈkjʊəriəs/","tag":"full of care","definition":"From the same care noun: originally 'careful, attentive', later 'eager to know'.","definitionCN":"同出该「关心」名词：原为「仔细、留意」，后转指「想知道」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"purchasing","ipa":"/ˈpɜːtʃəsɪŋ/","tag":"everyday business term","definition":"The routine buying of goods; procurement adds planning, competition and formal rules.","definitionCN":"日常的货物购买；procurement 另有规划、竞争与正式规则之意。"},{"word":"acquisition","ipa":"/ˌækwɪˈzɪʃn/","tag":"formal obtaining","definition":"The obtaining of something, often an asset or a company; it says nothing about tendering.","definitionCN":"取得某物，常指资产或公司；并不涉及招标程序。"},{"word":"sourcing","ipa":"/ˈsɔːsɪŋ/","tag":"finding suppliers","definition":"The search for and selection of suppliers, the front half of procurement.","definitionCN":"寻找并挑选供应商，是采购流程的前半段。"},{"word":"supply","ipa":"/səˈplaɪ/","tag":"making available","definition":"The providing of goods to those who need them, seen from the giving side rather than the buying side.","definitionCN":"向需要者提供货物，站在给予方而非购买方来看。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real 'care' root, the real institutional phrases and the real family.","cn":"正常联想使用真实的「照料」词根、真实的机构搭配与真实词族。"},"normal":[{"en":"The root means 'care': procurement is buying done with care and on paper.","cn":"词根意为「照料」：采购就是带着小心、留下纸面记录的购买。"},{"en":"The family runs procure, procurable, procurer and procuration.","cn":"同族词包括采购、可取得的、取得者与代理办理。"},{"en":"Fixed phrases mark it: public procurement, procurement process, procurement officer.","cn":"固定搭配标出这个词：政府采购、采购流程、采购主管。"},{"en":"The same care root gives accurate and curious, both once meaning careful.","cn":"同一「照料」词根还给出「准确的」与「好奇的」，两者都曾表示「仔细」。"},{"en":"Procurement begins with a need and ends with a signed contract.","cn":"采购从一项需求开始，到一份签好的合同结束。"}],"abstract":[{"en":"Picture a request form travelling through three desks before it becomes a crate.","cn":"想象一张需求单走过三张办公桌，最后变成一只货箱。"},{"en":"Picture a scale that weighs not goods but promises.","cn":"想象一杆秤，称的不是货物，而是承诺。"},{"en":"Picture a gardener who plans what to bring in before winter.","cn":"想象一位园丁，在入冬前就盘算好要备进什么。"}]},"examples":[{"en":"Procurement rules require at least three competing bids.","cn":"采购规则要求至少三家竞标报价。"},{"en":"The hospital's procurement of masks began before the outbreak.","cn":"这家医院在疫情暴发前就已采购口罩。"},{"en":"She moved from procurement into supply-chain planning.","cn":"她从采购转到供应链规划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（为了）+ cure（关心）+ ment」——为机构所需之事操心办理 → 采购","word":"procurement"},"root":"古法语 procurement 来自拉丁语 procurare（照料、料理、管理）＝pro-（为了、代表）＋curare（关心、照料），词根 cura 意为「关心」。原义为管理事务，后收窄为采购。","sensesIntro":{"en":"Eight senses start from caring for an institution's affairs and narrow into the paper process of buying, which then spreads to government, defence, digital systems and strategy.","cn":"八个义项从「替机构料理事务」出发，收窄为有纸面流程的购买，再扩展到政府、国防、数字系统与战略。"},"semanticMap":{"core":{"en":"CORE IMAGE: a request form that becomes a signed contract and then a crate at the door.","cn":"核心意象：一张需求单变成一份签好的合同，再变成门口的一只货箱。"},"chain":["CARE FOR","MANAGE AFFAIRS","OBTAIN WHAT IS NEEDED","COMPARE AND CONTRACT","PUBLIC RULES","STRATEGIC BUYING"],"branches":[{"senses":"01 · 02","en":"THE PROCESS AND ITS OFFICE: a way of caring for needs hardens into a department.","cn":"流程与其部门：照料需求的方式固定为一个部门。"},{"senses":"03 · 04","en":"PUBLIC AND ARMED BUYING: public money and secrecy each add their own rules.","cn":"公共与军事购买：公共资金与保密各自添上一套规则。"},{"senses":"05 · 06","en":"NEW CRITERIA: a digital channel and environmental scoring change how the same act is done.","cn":"新标准：数字渠道与环境评分改变的是同一行为的做法。"},{"senses":"07","en":"WIDER OBTAINING: the old sense survives where what is obtained is funds or evidence.","cn":"更宽的取得：旧义留在取得资金或证据的场合。"},{"senses":"08","en":"AT THE DESIGN TABLE: buying becomes a decision about what not to make.","cn":"坐上设计桌：采购成了决定「不做什么」的决策。"}]},"affixes":{"intro":{"en":"The word is a Latin prefix, a Latin noun of care and its verb, plus a French noun ending.","cn":"这个词由一个拉丁前缀、一个表「关心」的拉丁名词及其动词，再加一个法语名词词尾构成。"},"latinIntro":{"en":"Latin cura gives cure, accurate and curious as well as procure and procurement.","cn":"拉丁语 cura 除构成「采购」一族外，还给出「治愈」「准确的」「好奇的」等词。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, 'for, on behalf of')","meaning":"for; in front of","meaningCN":"为了；在……之前","example":"The prefix says the care is exercised for someone else.","exampleCN":"这个前缀说明照料是替别人做的。"},{"word":"cura","structure":"cura, curae (f., first declension)","meaning":"care, concern","meaningCN":"关心；忧虑；照料","example":"The noun names the attention being given.","exampleCN":"这个名词指所付出的留意。"},{"word":"curare","structure":"curare, curavi, curatum (Latin verb, first conjugation)","meaning":"to care for, attend to","meaningCN":"照料；料理","example":"The verb turns care into an activity.","exampleCN":"这个动词把「关心」变成行动。"},{"word":"procurare","structure":"pro- + curare (Latin verb)","meaning":"to manage for someone","meaningCN":"替某人管理、料理","example":"Procurare is the source of the English family.","exampleCN":"这个词是英语这一词族的来源。"},{"word":"procure","structure":"procurare through Old French","meaning":"to obtain, bring about","meaningCN":"取得；促成","example":"They procured the parts within a week.","exampleCN":"他们一周内就取得了零件。"},{"word":"procurement","structure":"procurer + -ment (act or result)","meaning":"the act of obtaining","meaningCN":"取得的行为","example":"Procurement takes months for large works.","exampleCN":"大型工程的采购要花几个月。"},{"word":"procurable","structure":"procure + -able (can be)","meaning":"able to be obtained","meaningCN":"可取得的","example":"The rare alloy was no longer procurable.","exampleCN":"那种稀有合金已无法采购到。"},{"word":"procurer","structure":"procure + -er (one who does)","meaning":"one who obtains","meaningCN":"取得者；采购者","example":"The procurer dealt with every supplier.","exampleCN":"采购者与每一家供应商打交道。"},{"word":"accurate","structure":"ad- + curare (Latin accuratus)","meaning":"done with care","meaningCN":"仔细做成的；准确的","example":"The count was accurate to the last crate.","exampleCN":"清点精确到最后一箱。"}],"latinEntries":[{"word":"cura","structure":"cura, curae (f., first declension)","meaning":"care, concern","meaningCN":"关心；照料"},{"word":"curare","structure":"curare, curavi, curatum (verb, first conjugation)","meaning":"to care for","meaningCN":"照料；料理"},{"word":"procurare","structure":"procurare, procuravi, procuratum (verb, first conjugation)","meaning":"to take care of, manage","meaningCN":"照料；管理"}],"derivatives":[{"word":"procure","pos":"v.","zh":"采购；取得"},{"word":"procurable","pos":"adj.","zh":"可获得的；可采购到的"},{"word":"procurer","pos":"n.","zh":"采购者；取得者"},{"word":"procuration","pos":"n.","zh":"取得；代理办理"}]}},{"word":"purchaser","ipa_uk":"/ˈpɜːtʃəsə/","ipa_us":"/ˈpɜːrtʃəsər/","definition_zh":"购买者；买方；采购人员；购房人","definition_en":"the person or organization that buys something, especially property or goods on behalf of a group","core_image":"一只手递出钱，另一只手接过钥匙或货，钱货交换的那一刻定下「买方」","scene":"签约桌两边坐着人，一边交钥匙，一边交支票，买下这栋房子的人在最后一页写下名字。The purchaser signed before the keys changed hands.","sceneCN":"桌上一串钥匙与一张支票同时移动，签字之后钥匙才易手；句中的 purchaser 指「付钱买下某物的买方」（第 1 个义项：交易中付出价款、取得标的的一方）。图中可辨识物件：钥匙、支票、合同、签字笔。","pos":[{"tag":"n.","zh":"购买者；买方"},{"tag":"n.","zh":"采购人员；购房人"}],"collocations":[{"phrase":"first-time purchaser","zh":"首次购房者"},{"phrase":"prospective purchaser","zh":"潜在买家"},{"phrase":"the purchaser of record","zh":"登记在册的买方"},{"phrase":"intending purchaser","zh":"有意购买者"},{"phrase":"purchaser's name","zh":"买方姓名"},{"phrase":"home purchaser","zh":"购房人"}],"forms":[{"label":"复数","form":"purchasers"},{"label":"动词（购买）","form":"purchase"},{"label":"三单","form":"purchases"},{"label":"过去式","form":"purchased"},{"label":"现在分词","form":"purchasing"},{"label":"形容词（可购买的）","form":"purchasable"}],"derivatives":[{"word":"purchase","pos":"v./n.","zh":"购买 / 购买之物"},{"word":"purchasing","pos":"n.","zh":"采购；购买行为"},{"word":"purchasable","pos":"adj.","zh":"可购买的"}],"senses":[{"no":"01","title":"The party that pays","titleCN":"交易中付出价款、取得标的的买方","definition":"the person or firm that pays for something and takes it","definitionCN":"为某物付款并取得它的个人或公司","example":"The purchaser signed before the keys changed hands.","exampleCN":"买方在钥匙易手之前先签了字。","why":"the word began as a verb meaning to pursue and obtain, so the agent noun names the one who obtains by paying.","whyCN":"这个词原是一个意为「追求并取得」的动词，因此施动名词指靠付钱而取得的一方。"},{"no":"02","title":"A buying officer","titleCN":"代表机构进行采购的人员","definition":"an employee who buys goods or services on behalf of an organization","definitionCN":"代表机构购买货物或服务的雇员","example":"The purchaser negotiated a discount for the whole year.","exampleCN":"采购人员谈下了全年的折扣。","why":"institutions put one person in the buying seat, and the generic word becomes a job description.","whyCN":"机构把一个人放在采购的位置上，普通名词于是成了职务名称。"},{"no":"03","title":"The buyer of a property","titleCN":"不动产交易中的购房人或购地人","definition":"the party buying land or a building, often named in the title documents","definitionCN":"买下土地或建筑的一方，常被记入产权文件","example":"The purchaser of the flat paid the deposit in cash.","exampleCN":"这套公寓的买家以现金支付了定金。","why":"property sales are formal and recorded, so the legal word for the buyer dominates this context.","whyCN":"房产交易正式且需登记，因此法律上对买方的称呼在这一语境中占主导。"},{"no":"04","title":"The buyer in a contract","titleCN":"合同条款中被称为买方的当事人","definition":"the party named as the buyer in a sale contract, with the duties that follow","definitionCN":"销售合同中被列为买方、并因此承担相应义务的一方","example":"The contract binds the purchaser to complete within sixty days.","exampleCN":"合同要求买方在六十天内完成交割。","why":"a contract needs a stable label for each side, and the plain noun is used as that label.","whyCN":"合同需要给每一方一个稳定称谓，于是把这个普通名词拿来当标签。"},{"no":"05","title":"The acquiring company","titleCN":"并购交易中买下公司的一方","definition":"the company that buys another company or a controlling stake in it","definitionCN":"买下另一家公司或其控股股权的公司","example":"The purchaser promised to keep the factory open.","exampleCN":"收购方承诺让工厂继续开工。","why":"a company is bought as a whole, yet the buyer is still called by the ordinary word for a buyer.","whyCN":"公司被整体买下，但买方仍用那个指买家的普通词来称呼。"},{"no":"06","title":"A first-time home buyer","titleCN":"首次置业的购房者","definition":"someone buying a home for the first time, often eligible for special terms","definitionCN":"第一次买房的人，常可适用特别条件","example":"First-time purchasers received a lower deposit rate.","exampleCN":"首次购房者获得了较低的首付比例。","why":"policy creates a category of buyer, so the word is preceded by a phrase that marks the first purchase.","whyCN":"政策造出一类买家，于是在这个词前加一个标记「第一次购买」的短语。"},{"no":"07","title":"An impulse buyer","titleCN":"受陈列与促销驱使而临时购买的顾客","definition":"a customer who buys on the spot without planning, prompted by display or price","definitionCN":"没有预先计划、受陈列或价格驱使当场购买的顾客","example":"The display turned browsers into purchasers.","exampleCN":"这组陈列把浏览者变成了购买者。","why":"marketing talks about converting a person into a buyer, and the noun marks the moment of conversion.","whyCN":"营销谈论如何把一个人转化为买家，这个名词标记转化的那一刻。"},{"no":"08","title":"Anyone who obtains at a cost","titleCN":"抽象义：以某种代价换得某物的人","definition":"anyone who obtains something by accepting a cost, whether money, time or risk","definitionCN":"以付出金钱、时间或风险为代价而取得某物的人","example":"Every purchaser of speed pays with patience somewhere else.","exampleCN":"每个购买速度的人，都在别处用耐心付款。","why":"the commercial frame generalizes: to purchase is to obtain at a price, and the price need not be money.","whyCN":"商业框架被一般化：购买就是以代价取得，而代价未必是钱。"}],"etymology":{"intro":{"en":"Purchaser comes from the verb purchase, borrowed from Anglo-Norman French purchacer 'to seek to obtain', built on pur- 'forth' and chacier 'to chase'. Dates are approximate.","cn":"purchaser 来自动词 purchase，借自盎格鲁-诺曼法语 purchacer「设法取得」，由表示「向前」的前缀与「追逐」的动词构成。年代均为约数。"},"items":[{"era":"LATE LATIN CAPTIARE","en":"Captiare 'to try to catch, hunt' is the Late Latin verb behind the French word for chasing, and it rests on capere 'to take'.","cn":"captiare「设法抓住、猎取」是法语「追逐」一词背后的晚期拉丁语动词，其根源是 capere「拿取」。"},{"era":"OLD FRENCH CHACIER","en":"Chacier 'to chase, hunt, drive' carried the Latin verb into French, and English chase comes from the same source.","cn":"chacier「追赶、猎取、驱赶」把这一拉丁动词带入法语，英语的「追逐」也出自同一来源。"},{"era":"ANGLO-NORMAN PURCHACER","en":"Pur- 'forth' plus chacier gave purchacer 'to pursue, obtain', which English borrowed in the fourteenth century.","cn":"表示「向前」的前缀加 chacier 构成 purchacer「追求、取得」，英语在十四世纪借入。"},{"era":"ENGLISH PURCHASE","en":"The verb first meant to obtain by effort or pursuit, and the commercial sense of buying for money came later.","cn":"这个动词最初指通过努力或追求而获得，后来才出现用钱购买的商业义。"},{"era":"AGENT NOUN","en":"Adding the agent suffix produced purchaser, the party that obtains, and in law the named buyer of property.","cn":"加上表施动者的后缀构成 purchaser，指取得的一方，在法律上指被记名的买受人。"}]},"similar":{"note":{"en":"Group one holds words from the same chasing root, all originally about pursuit; group two holds other names for a buyer.","cn":"第一组同出「追逐」这一词根，原义都与追赶有关；第二组是买方的其他称呼。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"purchase","ipa":"/ˈpɜːtʃəs/","tag":"the act","definition":"The verb and noun for obtaining something, now chiefly by paying; the longer word names the party.","definitionCN":"取得某物的动词与名词，今主要指付钱取得；较长的词指那一方。"},{"word":"chase","ipa":"/tʃeɪs/","tag":"same second half","definition":"To run after something in order to catch it, from the same French verb that gave purchase.","definitionCN":"为抓住某物而追赶，同出构成 purchase 的那个法语动词。"},{"word":"catch","ipa":"/kætʃ/","tag":"same Latin base","definition":"To take hold of something moving, from the same Late Latin verb for trying to seize.","definitionCN":"抓住移动中的东西，同出那个表示「设法抓住」的晚期拉丁语动词。"},{"word":"capture","ipa":"/ˈkæptʃə/","tag":"same Latin base","definition":"To take a person or place by force, from the Latin verb 'to take' behind the whole family.","definitionCN":"以武力拿下人或地方，来自整个词族背后那个拉丁语「拿取」动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"buyer","ipa":"/ˈbaɪə/","tag":"plain everyday word","definition":"The ordinary word for the party that pays; purchaser is its formal and legal counterpart.","definitionCN":"指付钱一方的普通词；purchaser 是其正式、法律上的对应词。"},{"word":"consumer","ipa":"/kənˈsjuːmə/","tag":"the user","definition":"The person who uses goods or services, who may or may not be the one who paid for them.","definitionCN":"使用货物或服务的人，可能是付款者，也可能不是。"},{"word":"client","ipa":"/ˈklaɪənt/","tag":"ongoing relationship","definition":"A customer served over time, especially in professional services; it stresses the relationship, not the single deal.","definitionCN":"长期接受服务的顾客，尤用于专业服务；强调关系而非单笔交易。"},{"word":"acquirer","ipa":"/əˈkwaɪərə/","tag":"corporate buyer","definition":"A company that buys another company; in finance it is the standard term where purchaser sounds plain.","definitionCN":"买下另一家公司的企业；在金融语境中它是标准说法，而 purchaser 显得朴素。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real 'chase and obtain' root, the real property phrases and the real legal use.","cn":"正常联想使用真实的「追逐取得」词根、真实的房产搭配与真实的法律用法。"},"normal":[{"en":"The root means 'to chase': a purchaser is one who pursues a thing until it is obtained.","cn":"词根意为「追逐」：买方就是追着一件东西直到把它取得的人。"},{"en":"The family runs purchase, purchasing and purchasable.","cn":"同族词包括购买、采购行为与可购买的。"},{"en":"Fixed phrases mark it: first-time purchaser, prospective purchaser, home purchaser.","cn":"固定搭配标出这个词：首次购房者、潜在买家、购房人。"},{"en":"The same chase root gives chase, catch and capture.","cn":"同一「追逐」词根还给出「追赶」「抓住」与「俘获」。"},{"en":"In contracts the purchaser is a label, not a description: it fixes who owes what.","cn":"在合同里，买方是一个标签而非描述：它固定谁该付什么。"}],"abstract":[{"en":"Picture a hand that must close on an object before it can call it bought.","cn":"想象一只手必须先握住某物，才能说它被买下。"},{"en":"Picture a hunter who pays the forest for what he carries out.","cn":"想象一个猎人，为带出森林的东西向森林付钱。"},{"en":"Picture a signature that turns a browser into an owner.","cn":"想象一个签名把浏览者变成所有者。"}]},"examples":[{"en":"The purchaser must complete the payment within thirty days.","cn":"买方必须在三十天内完成付款。"},{"en":"Prospective purchasers were shown the survey before bidding.","cn":"潜在买家在出价前被出示了勘测报告。"},{"en":"The purchaser of the firm kept all the staff on.","cn":"收购这家公司的一方留用了全部员工。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pur（向前）+ chase（追）」——追着把东西弄到手的人 → 购买者","word":"purchaser"},"root":"盎格鲁-诺曼法语 purchacer（追求、取得）＝pur-（向前）＋chacier（追逐）；chacier 来自晚期拉丁语 captiare（设法抓住），再往上为 capere（拿取）。加表施动者的后缀即成 purchaser。","sensesIntro":{"en":"Eight senses follow one figure: the party that obtains by paying, whether at a shop, in a contract, in a property deal, in a takeover or in a bargain where the price is not money.","cn":"八个义项围绕同一个人物：靠付钱而取得的一方，无论在店里、合同里、房产交易里、收购里，还是在代价并非金钱的交易里。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand gives money while the other closes on the thing.","cn":"核心意象：一只手付出钱，另一只手握住那件东西。"},"chain":["PURSUE","OBTAIN","PAY THE PRICE","TAKE DELIVERY","NAMED IN LAW","PAY ANY COST"],"branches":[{"senses":"01 · 07","en":"THE MOMENT OF CONVERSION: paying turns a browser into a buyer, and the word marks that moment.","cn":"转化的时刻：付钱把浏览者变成买家，这个词标记的正是那一刻。"},{"senses":"02","en":"BUYING FOR OTHERS: an employee sits in the buying seat on the organization's behalf.","cn":"替人购买：雇员代表机构坐在采购的位置上。"},{"senses":"03 · 04 · 06","en":"THE RECORDED BUYER: property, contracts and first-home schemes all need one stable name for the party that pays.","cn":"被记录的买方：房产、合同与首次置业政策都需要给付款方一个稳定名称。"},{"senses":"05","en":"WHOLE COMPANIES: a firm can be the object, yet the buyer keeps the ordinary name.","cn":"整个公司：公司可以成为标的，买方却仍用普通名称。"},{"senses":"08","en":"ANY PRICE: the commercial frame widens until time and risk become the currency.","cn":"任何代价：商业框架扩展，直到时间与风险也成了货币。"}]},"affixes":{"intro":{"en":"The word is a French prefix, a French verb of chasing and an English agent suffix, resting on a Latin verb of taking.","cn":"这个词由一个法语前缀、一个法语「追逐」动词与一个英语施动后缀构成，底座是拉丁语「拿取」动词。"},"latinIntro":{"en":"Latin capere gives capture, captive and catch through captiare; the French prefix marks pursuit forward.","cn":"拉丁语 capere 经 captiare 给出「俘获」「俘虏」与「抓住」等词；法语前缀标记向前追赶。"},"items":[{"word":"pur-","structure":"pur- (Anglo-Norman prefix, 'forth')","meaning":"forth; forward","meaningCN":"向前；出去","example":"The prefix sends the action outward after the thing.","exampleCN":"这个前缀把动作指向向外追索。"},{"word":"chacier","structure":"chacier (Old French verb, 'to chase')","meaning":"to chase, hunt","meaningCN":"追赶；猎取","example":"The verb supplies the picture of pursuit.","exampleCN":"这个动词提供追逐的画面。"},{"word":"purchacer","structure":"pur- + chacier (Anglo-Norman verb)","meaning":"to pursue and obtain","meaningCN":"追求并取得","example":"Purchacer is the direct source of purchase.","exampleCN":"这个词是 purchase 的直接来源。"},{"word":"purchase","structure":"purchacer through Middle English","meaning":"to obtain, later to buy","meaningCN":"取得，后指购买","example":"They purchased the land in spring.","exampleCN":"他们在春天买下了这块地。"},{"word":"-er","structure":"-er (English suffix, 'one who does')","meaning":"the one that acts","meaningCN":"执行动作的一方","example":"The suffix turns the act into the actor.","exampleCN":"这个后缀把行为变成行为人。"},{"word":"purchaser","structure":"purchase + -er","meaning":"the party that buys","meaningCN":"买下某物的一方","example":"The purchaser signed first.","exampleCN":"买方先签了字。"},{"word":"purchasing","structure":"purchase + -ing (activity)","meaning":"the buying function","meaningCN":"采购职能","example":"Purchasing reports to the finance director.","exampleCN":"采购部门向财务总监汇报。"},{"word":"purchasable","structure":"purchase + -able (can be)","meaning":"able to be bought","meaningCN":"可购买的","example":"The licence is purchasable online.","exampleCN":"许可证可以在线购买。"},{"word":"catch","structure":"captiare through Old French","meaning":"to seize something moving","meaningCN":"抓住移动之物","example":"He caught the falling box.","exampleCN":"他接住了落下的箱子。"}],"latinEntries":[{"word":"capere","structure":"capere, cepi, captum (verb, third conjugation)","meaning":"to take, seize","meaningCN":"拿取；抓住"},{"word":"captiare","structure":"captiare (Late Latin verb, first conjugation)","meaning":"to try to catch, hunt","meaningCN":"设法抓住；猎取"}],"derivatives":[{"word":"purchase","pos":"v./n.","zh":"购买 / 购买之物"},{"word":"purchasing","pos":"n.","zh":"采购；购买行为"},{"word":"purchasable","pos":"adj.","zh":"可购买的"}]}},{"word":"outsourcing","ipa_uk":"/ˈaʊtsɔːsɪŋ/","ipa_us":"/ˈaʊtsɔːrsɪŋ/","definition_zh":"外包；把业务、工序或职能交给外部供应商承做的做法","definition_en":"the practice of arranging for an outside supplier to perform work that a firm once did itself","core_image":"一间办公室把整摞文件推出门外，另一家公司的人在门外接住并签收","scene":"公司的客服电话被转到另一座城市的接线中心，工位空了下来，电话仍有人接。The outsourcing of customer support cut costs but weakened loyalty.","sceneCN":"办公区里一排工位空着，电话却被转到另一座城市的话务中心，铃声照常有人接；句中的 outsourcing 指「把某项业务交给外部供应商承做」（第 1 个义项：原本自做的工作转由外部机构完成的安排）。图中可辨识物件：空工位、电话、接线耳机、合同。","pos":[{"tag":"n.","zh":"外包；外判"}],"collocations":[{"phrase":"IT outsourcing","zh":"信息技术外包"},{"phrase":"business process outsourcing","zh":"业务流程外包"},{"phrase":"offshore outsourcing","zh":"离岸外包"},{"phrase":"outsourcing contract","zh":"外包合同"},{"phrase":"outsourcing decision","zh":"外包决策"},{"phrase":"domestic outsourcing","zh":"境内外包"}],"forms":[{"label":"动词（外包）","form":"outsource"},{"label":"三单","form":"outsources"},{"label":"过去式","form":"outsourced"},{"label":"过去分词","form":"outsourced"},{"label":"现在分词","form":"outsourcing"},{"label":"施动者名词（承接方）","form":"outsourcer"}],"derivatives":[{"word":"outsource","pos":"v.","zh":"外包；把……交给外部承做"},{"word":"outsourced","pos":"adj.","zh":"已外包的"},{"word":"outsourcer","pos":"n.","zh":"外包服务承接方"}],"senses":[{"no":"01","title":"Contracting work to an outside firm","titleCN":"把原本自做的工作交给外部公司承做","definition":"the practice of hiring an outside supplier to do work that the organization used to do in house","definitionCN":"雇请外部供应商承担本机构原先自己做的工作的做法","example":"The outsourcing of customer support cut costs but weakened loyalty.","exampleCN":"客服外包降低了成本，却削弱了顾客忠诚。","why":"the word joins 'out' to 'source': the source of the work is moved outside the organization.","whyCN":"这个词把「向外」与「来源」拼在一起：工作的来源被移到组织之外。"},{"no":"02","title":"Handing over a whole function","titleCN":"把整个职能或部门交给外部运营","definition":"the transfer of an entire function, such as payroll or cleaning, to an external operator","definitionCN":"把整个职能（如薪酬发放或清洁）转交给外部机构运营","example":"The outsourcing of payroll removed an entire department.","exampleCN":"薪酬发放外包使整个部门被撤掉。","why":"the unit moved is not one task but a whole function, which is the sense that dominated the 1990s.","whyCN":"被移走的不是一个任务，而是一整个职能，这是它在九十年代占主导的含义。"},{"no":"03","title":"Information technology outsourcing","titleCN":"信息技术系统的外包","definition":"the handing of systems, networks or software support to an external provider","definitionCN":"把系统、网络或软件维护交给外部服务商","example":"IT outsourcing moved the servers into a supplier's hall.","exampleCN":"信息技术外包把服务器搬进了供应商的机房。","why":"computing was the industry where the practice first became a named strategy, so the label attached there first.","whyCN":"计算机业最早把这种做法变成有名称的策略，因此这个标签最先附在那里。"},{"no":"04","title":"Sending work overseas","titleCN":"把业务转到海外承做的离岸外包","definition":"outsourcing to a supplier in another country, usually where labour costs less","definitionCN":"把业务交给另一国的供应商，通常那里人工更便宜","example":"Offshore outsourcing moved the call centre to another continent.","exampleCN":"离岸外包把话务中心搬到了另一个大洲。","why":"location is a separate variable from ownership, so a second word marks the foreign version.","whyCN":"地点与归属是两件不同的事，因此另用一个词来标出海外版本。"},{"no":"05","title":"Business process outsourcing","titleCN":"把整套业务流程交给外部运营","definition":"the transfer of a complete back-office process, such as billing or claims, to a specialist","definitionCN":"把一整套后台流程（如计费或理赔）交给专门公司","example":"Business process outsourcing handled claims for twelve insurers.","exampleCN":"业务流程外包为十二家保险公司处理理赔。","why":"once a process rather than a department is moved, the practice needs a name for that wider unit.","whyCN":"当被移走的是一个流程而非一个部门时，这种做法需要一个更宽的单位名称。"},{"no":"06","title":"Keeping the work in the country","titleCN":"把业务交给境内供应商的境内外包","definition":"outsourcing to a supplier within the same country rather than abroad","definitionCN":"把业务交给同一国境内的供应商，而不是海外","example":"Domestic outsourcing kept the jobs but changed the employer.","exampleCN":"境内外包保住了工作，却换了雇主。","why":"the same act without a border crossing needs a contrastive label.","whyCN":"同一行为若没有跨越国界，就需要一个对比性的标签。"},{"no":"07","title":"A make-or-buy decision","titleCN":"作为自制或外购的战略选择","definition":"the strategic choice between producing something internally and buying it from outside","definitionCN":"在内部生产与向外部购买之间作出的战略选择","example":"Outsourcing was treated as a question of core competence.","exampleCN":"外包被当作一个核心能力问题来讨论。","why":"when the practice became strategy, it named a decision about what a firm should not do itself.","whyCN":"当这种做法成为战略时，它命名的是一项「企业不该自己做什么」的决策。"},{"no":"08","title":"Handing mental work to devices","titleCN":"抽象义：把记忆与判断交给外部工具","definition":"the habit of relying on external tools or other people to remember and decide","definitionCN":"依靠外部工具或他人来记忆与作决定的习惯","example":"Outsourcing memory to a phone leaves the mind oddly light.","exampleCN":"把记忆外包给手机，会让头脑变得异样地轻。","why":"the business image survives without a contract: what is moved outside is not work but mental load.","whyCN":"商业意象在无需合同时仍然成立：被移到外面的不是工作，而是心智负担。"}],"etymology":{"intro":{"en":"Outsourcing is a twentieth-century compound of out and sourcing, where source goes back through French to Latin surgere 'to rise'. Dates are approximate.","cn":"outsourcing 是二十世纪由「向外」与「来源」构成的复合词，其中「来源」经法语上溯到拉丁语 surgere「升起」。年代均为约数。"},"items":[{"era":"LATIN SURGERE","en":"Surgere meant 'to rise, spring up', built from the prefix for 'from below' and a verb meaning 'to lead straight'.","cn":"surgere 意为「升起、涌出」，由表示「从下方」的前缀与意为「引导直行」的动词构成。"},{"era":"OLD FRENCH SOURSE","en":"Sourse meant 'a rising, a spring, the place where water begins', the source of the English word source.","cn":"sourse 意为「涌出、泉眼、水开始的地方」，是英语 source 的来源。"},{"era":"ENGLISH SOURCE","en":"Source came to mean the point of origin of anything, from water to information to supply.","cn":"source 逐渐指任何事物的起源点，从水到信息到供应。"},{"era":"OUT + SOURCE","en":"Business writing of the late twentieth century joined out to source: to obtain from an outside origin.","cn":"二十世纪后期的商业写作把「向外」与「来源」拼合：从外部来源取得。"},{"era":"OUTSOURCING AS A TERM","en":"The noun outsourcing became a management term in the 1970s and spread worldwide in the following decade.","cn":"名词 outsourcing 在二十世纪七十年代成为管理术语，并在随后十年传遍世界。"},{"era":"MODERN SCOPE","en":"It now covers IT, back-office processes, manufacturing and even the delegating of memory to devices.","cn":"如今它涵盖信息技术、后台流程、制造，甚至把记忆交给设备的做法。"}]},"similar":{"note":{"en":"Group one holds words from the same 'rise' root that look close; group two holds near terms in the same business strategy.","cn":"第一组同出「升起」这一词根、形貌相近；第二组是同一商业策略里的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"outsource","ipa":"/ˌaʊtˈsɔːs/","tag":"the verb","definition":"The action of moving work outside; the noun names the practice or the arrangement itself.","definitionCN":"把工作移到外部的动作；名词指这种做法或安排本身。"},{"word":"source","ipa":"/sɔːs/","tag":"the origin","definition":"The point from which something comes; outsourcing moves that point outside the firm.","definitionCN":"某物来源的起点；外包把这个起点移到企业之外。"},{"word":"resource","ipa":"/rɪˈsɔːs/","tag":"same root, added prefix","definition":"A supply that can be drawn on, built with the prefix for 'again' and the same rising root.","definitionCN":"可供取用的资源，由表示「再」的前缀与同一「升起」词根构成。"},{"word":"surge","ipa":"/sɜːdʒ/","tag":"same Latin base","definition":"To rise suddenly and strongly, from the same Latin verb of rising behind source.","definitionCN":"突然而有力地涌起，同出 source 背后那个表示「升起」的拉丁动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"subcontracting","ipa":"/ˌsʌbkənˈtræktɪŋ/","tag":"one task at a time","definition":"Giving a specific piece of contracted work to another firm; outsourcing is usually wider and longer.","definitionCN":"把合同中的某一具体工作交给另一家公司；外包通常范围更广、期限更长。"},{"word":"offshoring","ipa":"/ˈɒfʃɔːrɪŋ/","tag":"location only","definition":"Moving work abroad, whether or not an outside firm does it; it names geography, not ownership.","definitionCN":"把工作移到海外，无论是否由外部公司承做；它命名的是地理，不是归属。"},{"word":"contracting out","ipa":"/kənˈtræktɪŋ aʊt/","tag":"public-sector phrase","definition":"The practice of having public services run by private firms; a close cousin in government use.","definitionCN":"让私营公司运营公共服务的做法；在政府用语中是近亲。"},{"word":"delegation","ipa":"/ˌdiːlɪˈɡeɪʃn/","tag":"passing authority","definition":"Handing a task and its authority to another person; it carries no commercial contract.","definitionCN":"把任务与权限交给他人；不必然涉及商业合同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real 'outside origin' image, the real strategy phrases and the real root family.","cn":"正常联想使用真实的「外部来源」意象、真实的策略搭配与真实词根家族。"},"normal":[{"en":"Out plus source: the origin of the work is moved outside the company.","cn":"「向外」加「来源」：工作的来源被移到公司之外。"},{"en":"Fixed phrases mark it: IT outsourcing, business process outsourcing, offshore outsourcing.","cn":"固定搭配标出这个词：信息技术外包、业务流程外包、离岸外包。"},{"en":"The same source root gives resource and surge, all about where something rises from.","cn":"同一「来源」词根还给出「资源」与「涌起」，都与事物从何处升起有关。"},{"en":"Outsourcing is about who does the work; offshoring is about where it is done.","cn":"外包讲的是谁来做，离岸讲的是在哪里做。"},{"en":"A firm outsources what it decides not to be good at.","cn":"企业外包的是它决定不去擅长的部分。"}],"abstract":[{"en":"Picture a desk being wheeled out of a building while another desk waits outside.","cn":"想象一张办公桌被推出大楼，门外已有另一张桌子等着。"},{"en":"Picture a river whose source is redirected to another hill.","cn":"想象一条河的源头被改到另一座山。"},{"en":"Picture a memory stored in a phone instead of a head.","cn":"想象一段记忆不放在头脑里，而存放在手机里。"}]},"examples":[{"en":"Outsourcing allowed the firm to cut fixed costs but reduced control.","cn":"外包让企业削减了固定成本，却降低了控制力。"},{"en":"The union opposed the outsourcing of warehouse jobs.","cn":"工会反对把仓库岗位外包出去。"},{"en":"Outsourcing payroll is common among small firms.","cn":"小型企业把薪酬发放外包很常见。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「out（向外）+ sourcing（找来源）」——到外面去找人干活 → 外包","word":"outsourcing"},"root":"英语复合词：out（向外）＋sourcing（取得来源）。source 经古法语 sourse（泉眼、涌出处）来自拉丁语 surgere（升起），该动词由表示「从下方」的前缀与意为「引导直行」的词根构成。","sensesIntro":{"en":"Eight senses follow work as it leaves the building: a function, a system, a process, a country and finally a piece of mental load.","cn":"八个义项跟着工作离开大楼：先是一个职能、一套系统、一个流程、一个国家，最后是一份心智负担。"},"semanticMap":{"core":{"en":"CORE IMAGE: a desk pushed out of the office while another firm's desk waits outside.","cn":"核心意象：一张桌子被推出办公室，门外另一家公司的桌子等着接。"},"chain":["MOVE OUT","FIND AN OUTSIDE SOURCE","HAND OVER A FUNCTION","HAND OVER A PROCESS","CHANGE COUNTRY","SHIFT THE LOAD"],"branches":[{"senses":"01 · 02","en":"THE BASIC MOVE: work leaves the building, first as tasks and then as a whole function.","cn":"基本移动：工作离开大楼，先以任务形式，后以整个职能的形式。"},{"senses":"03 · 05","en":"SYSTEMS AND PROCESSES: computing and back-office work are the two big blocks that moved.","cn":"系统与流程：计算机与后台工作是被移走的两大块。"},{"senses":"04 · 06","en":"WHERE: the same move may cross a border or stay inside one, and each case gets its own label.","cn":"在哪里：同一移动可以跨过国界，也可以留在境内，各有标签。"},{"senses":"07","en":"WHETHER TO MOVE: the practice becomes a decision about core competence.","cn":"是否移动：这种做法成为关于核心能力的决策。"},{"senses":"08","en":"NO CONTRACT NEEDED: the last version moves memory and judgment, not work.","cn":"无需合同：最后一个版本移走的是记忆与判断，而非工作。"}]},"affixes":{"intro":{"en":"The word is an English adverb plus a noun whose Latin root means 'to rise', with an English activity ending.","cn":"这个词由一个英语副词加一个拉丁词根意为「升起」的名词，再加一个英语表活动的词尾。"},"latinIntro":{"en":"Latin surgere gives source, resource and surge; the prefix inside it marks rising from below.","cn":"拉丁语 surgere 给出「来源」「资源」与「涌起」；其内部前缀标记「从下方升起」。"},"items":[{"word":"out-","structure":"out- (English adverb, 'outside')","meaning":"outside; outward","meaningCN":"在外；向外","example":"The prefix sends the sourcing beyond the firm.","exampleCN":"这个成分把「找来源」推到企业之外。"},{"word":"sub-","structure":"sub- (Latin prefix, 'from below')","meaning":"from below; upward","meaningCN":"从下方；向上","example":"The prefix gives the image of water rising.","exampleCN":"这个前缀带来水向上涌的画面。"},{"word":"regere","structure":"regere, rexi, rectum (Latin verb, third conjugation)","meaning":"to lead straight, guide","meaningCN":"引直；引导","example":"The root adds direction to the rising.","exampleCN":"这个词根给「升起」加上方向。"},{"word":"surgere","structure":"sub- + regere (Latin verb)","meaning":"to rise, spring up","meaningCN":"升起；涌出","example":"Surgere is the picture behind a spring of water.","exampleCN":"这个词是泉水涌出的画面来源。"},{"word":"source","structure":"sourse (Old French) from surgere","meaning":"the point of origin","meaningCN":"起源点；来源","example":"Every river has a source.","exampleCN":"每条河都有源头。"},{"word":"outsource","structure":"out + source","meaning":"to obtain from outside","meaningCN":"向外部取得","example":"They outsource the night shift.","exampleCN":"他们把夜班包了出去。"},{"word":"outsourcing","structure":"outsource + -ing (activity)","meaning":"the practice of moving work outside","meaningCN":"把工作移到外部的做法","example":"Outsourcing grew through the 1990s.","exampleCN":"外包在九十年代迅速增长。"},{"word":"outsourced","structure":"outsource + -ed (past participle)","meaning":"moved to an outside supplier","meaningCN":"已交给外部供应商的","example":"The cleaning is outsourced.","exampleCN":"清洁工作已外包。"},{"word":"outsourcer","structure":"outsource + -er (one who does)","meaning":"a firm that takes on outsourced work","meaningCN":"承接外包业务的公司","example":"The outsourcer runs three call centres.","exampleCN":"承接方运营着三个话务中心。"}],"latinEntries":[{"word":"surgere","structure":"surgere, surrexi, surrectum (verb, third conjugation)","meaning":"to rise, spring up","meaningCN":"升起；涌出"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to lead straight, guide","meaningCN":"引直；引导"}],"derivatives":[{"word":"outsource","pos":"v.","zh":"外包；把……交给外部承做"},{"word":"outsourced","pos":"adj.","zh":"已外包的"},{"word":"outsourcer","pos":"n.","zh":"外包服务承接方"}]}},{"word":"outsource","ipa_uk":"/ˌaʊtˈsɔːs/","ipa_us":"/ˌaʊtˈsɔːrs/","definition_zh":"把（工作、工序、职能）外包；向外部供应商购买（服务或部件）","definition_en":"to arrange for an outside supplier or another country to do work that could be done internally","core_image":"一只手把一叠待办工作递出窗口，窗外的人接过并立刻开始干活","scene":"项目经理把整块测试工作递给窗外的团队，自己只留下验收清单。The firm outsources payroll so that a specialist handles the tax filings.","sceneCN":"项目经理隔着窗把一叠测试任务递出去，只留下验收清单；句中的 outsource 指「把某项工作交给外部方承做」（第 1 个义项：把本可自做的工作移交给外部供应商）。图中可辨识物件：工作清单、窗口、文件夹、验收表。","pos":[{"tag":"v.","zh":"外包；把……交给外部承做"}],"collocations":[{"phrase":"outsource production","zh":"外包生产"},{"phrase":"outsource services","zh":"外包服务"},{"phrase":"outsource jobs","zh":"把岗位外包出去"},{"phrase":"outsource work","zh":"把工作外包"},{"phrase":"outsource to a supplier","zh":"外包给供应商"},{"phrase":"outsource payroll","zh":"外包薪酬发放"}],"forms":[{"label":"三单","form":"outsources"},{"label":"过去式","form":"outsourced"},{"label":"过去分词","form":"outsourced"},{"label":"现在分词","form":"outsourcing"},{"label":"名词（外包）","form":"outsourcing"},{"label":"施动者名词（承接方）","form":"outsourcer"}],"derivatives":[{"word":"outsourcing","pos":"n.","zh":"外包；外包做法"},{"word":"outsourced","pos":"adj.","zh":"已外包的"},{"word":"outsourcer","pos":"n.","zh":"外包承接方"}],"senses":[{"no":"01","title":"Move a whole job outside","titleCN":"把整项工作交给外部承做","definition":"to give an entire piece of work to an outside organization instead of doing it in house","definitionCN":"把整项工作交给外部机构，而不是在内部完成","example":"The firm outsources payroll so that a specialist handles the tax filings.","exampleCN":"公司把薪酬发放外包出去，让专门机构处理报税。","why":"the verb is the action behind the noun: the source of the work is placed outside.","whyCN":"这个动词是名词背后的动作：工作的来源被放到外面。"},{"no":"02","title":"Contract out one task","titleCN":"把某一具体任务分包出去","definition":"to give one defined task, such as translation or testing, to an outside contractor","definitionCN":"把一项界定明确的任务（如翻译或测试）交给外部承包商","example":"They outsourced the translation of the manual to a local agency.","exampleCN":"他们把手册翻译外包给了本地一家机构。","why":"the verb can take a single task as its object, not only a whole department.","whyCN":"这个动词的宾语可以是一项任务，而不必是一整个部门。"},{"no":"03","title":"Buy components from outside","titleCN":"从外部供应商购买零部件","definition":"to obtain parts or materials from an outside maker rather than producing them","definitionCN":"从外部制造商取得零件或材料，而不是自行生产","example":"The carmaker outsources the seats but builds its own engines.","exampleCN":"这家车企外购座椅，却自造发动机。","why":"in manufacturing, what leaves is not a service but a piece of the product, and the verb covers it.","whyCN":"在制造业，被移出去的不是服务，而是产品的一部分，这个动词也涵盖这种情况。"},{"no":"04","title":"Send jobs abroad","titleCN":"把岗位转到海外","definition":"to move work and jobs to a lower-cost country","definitionCN":"把工作与岗位移到成本更低的国家","example":"The plant outsourced assembly to a factory across the border.","exampleCN":"工厂把组装外包给了边境另一侧的工厂。","why":"location is often the point of the verb in public debate, even though it is not part of the word's shape.","whyCN":"在公共争论中，地点常是这个动词的重点，尽管它并不在词形之中。"},{"no":"05","title":"Hand over an IT function","titleCN":"把信息技术职能交给外部服务商","definition":"to transfer systems, support or development to an external technology provider","definitionCN":"把系统、技术支持或开发转交给外部技术提供商","example":"The bank outsources its data backup to a cloud firm.","exampleCN":"银行把数据备份外包给一家云服务公司。","why":"technology was the first field to make the verb routine, so an IT object is one of its most common uses.","whyCN":"技术领域最早让这个动词成为日常用语，因此以信息技术为宾语是其最常见用法之一。"},{"no":"06","title":"Hand over manufacturing","titleCN":"把生产环节交给外部工厂","definition":"to have goods made by another company, often under contract and to one's specification","definitionCN":"让另一家公司按合同与规格生产自己的货物","example":"The brand outsources all its clothing to three factories.","exampleCN":"这个品牌把全部服装交给三家工厂生产。","why":"the object may be the making of a product, not just its parts.","whyCN":"宾语可以是产品的制造过程，而不只是零件。"},{"no":"07","title":"Hand over a service","titleCN":"把某项服务（客服、物流、薪酬）交给外部","definition":"to have a service delivered by a specialist rather than by one's own staff","definitionCN":"让专业公司提供服务，而不是由自己的员工来做","example":"Small clinics outsource billing to keep overheads low.","exampleCN":"小型诊所把账单处理外包，以压低管理费用。","why":"services are invisible, yet they move outside the firm in exactly the same way as goods.","whyCN":"服务是无形的，但它们移出企业的方式与货物完全相同。"},{"no":"08","title":"Delegate a decision","titleCN":"抽象义：把判断或决策交给外部方","definition":"to let an outside party or tool make a judgment one could make oneself","definitionCN":"让外部一方或工具作出自己本可作出的判断","example":"It is risky to outsource editorial judgment to an algorithm.","exampleCN":"把编辑判断外包给算法是有风险的。","why":"the verb's shape allows any object: once judgment can be moved outside, it too can be outsourced.","whyCN":"这个动词的词形允许任何宾语：一旦判断可以被移到外部，它也能被外包。"}],"etymology":{"intro":{"en":"Outsource is a back-formation from outsourcing, coined in late twentieth-century business writing and built on out plus source. Dates are approximate.","cn":"outsource 是由 outsourcing 逆构而成的动词，产生于二十世纪后期的商业写作，由「向外」与「来源」构成。年代均为约数。"},"items":[{"era":"LATIN SURGERE","en":"Surgere 'to rise, spring up' combines the prefix for 'from below' with a verb meaning 'to lead straight'.","cn":"surgere「升起、涌出」把表示「从下方」的前缀与意为「引导直行」的动词组合起来。"},{"era":"OLD FRENCH SOURSE","en":"Sourse 'a spring, the place where water rises' is the ancestor of the English noun source.","cn":"sourse「泉眼、水涌出之处」是英语名词 source 的祖先。"},{"era":"ENGLISH SOURCE","en":"Source widened to any point of origin, including the supplier of goods or work.","cn":"source 扩展到任何起源点，包括货物或工作的供应方。"},{"era":"OUTSOURCING","en":"The noun naming the practice appeared in the 1970s and spread widely in the 1980s and 1990s.","cn":"指这种做法的名词在二十世纪七十年代出现，并在八九十年代广泛传播。"},{"era":"BACK-FORMATION","en":"Speakers then clipped the noun to form the verb outsource, treating the ending as if it were a suffix.","cn":"随后使用者从名词中截出动词 outsource，把词尾当作后缀去掉。"}]},"similar":{"note":{"en":"Group one holds words from the same 'rise' root and the same compound; group two holds verbs of handing work to others.","cn":"第一组同出「升起」词根或同一复合结构；第二组是把工作交给他人的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"outsourcing","ipa":"/ˈaʊtsɔːsɪŋ/","tag":"the noun","definition":"The practice or arrangement of moving work outside; the verb names the act of doing it.","definitionCN":"把工作移到外部的做法或安排；动词指做出这一动作。"},{"word":"source","ipa":"/sɔːs/","tag":"the origin","definition":"The point something comes from; the verb moves that point beyond the organization.","definitionCN":"事物来源的起点；这个动词把该起点移到组织之外。"},{"word":"resource","ipa":"/rɪˈsɔːs/","tag":"same root","definition":"A supply available for use, from the same rising root with a prefix meaning 'again'.","definitionCN":"可供使用的资源，同出该「升起」词根，前缀意为「再」。"},{"word":"surge","ipa":"/sɜːdʒ/","tag":"same Latin base","definition":"To rise suddenly, from the same Latin verb of rising that gave source.","definitionCN":"突然升起，同出给出 source 的那个拉丁语「升起」动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"subcontract","ipa":"/ˌsʌbkənˈtrækt/","tag":"one defined piece","definition":"To give a specific contracted task to another firm; narrower than to outsource.","definitionCN":"把合同中一项具体任务交给另一家公司；比 outsource 范围窄。"},{"word":"delegate","ipa":"/ˈdiːlɪɡeɪt/","tag":"pass authority","definition":"To hand a task and its authority to a person, usually inside the same organization.","definitionCN":"把任务与权限交给一个人，通常在同一组织内部。"},{"word":"farm out","ipa":"/fɑːm aʊt/","tag":"informal phrase","definition":"An informal verb for sending work to others, often used of repetitive tasks.","definitionCN":"把工作送交他人的口语说法，常用于重复性任务。"},{"word":"contract out","ipa":"/kənˈtrækt aʊt/","tag":"public services","definition":"To have a service provided by an outside firm under contract, common in government.","definitionCN":"按合同让外部公司提供某项服务，常见于政府用语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real compound, the real verb phrases and the real root family.","cn":"正常联想使用真实的复合结构、真实的动词搭配与真实词根家族。"},"normal":[{"en":"Out plus source: put the source of the work outside the firm.","cn":"「向外」加「来源」：把工作的来源放到企业之外。"},{"en":"Fixed phrases mark it: outsource production, outsource services, outsource payroll.","cn":"固定搭配标出这个词：外包生产、外包服务、外包薪酬发放。"},{"en":"The family runs outsource, outsourcing, outsourced and outsourcer.","cn":"同族词包括外包、外包做法、已外包的与承接方。"},{"en":"Outsource answers who does the work; offshore answers where.","cn":"外包回答谁来做，离岸回答在哪里做。"},{"en":"The verb is a back-formation: the noun came first, the verb was cut from it.","cn":"这个动词是逆构词：名词先出现，动词由它截成。"}],"abstract":[{"en":"Picture a hand passing a stack of papers through a window.","cn":"想象一只手把一叠文件递出窗口。"},{"en":"Picture a tap whose water is redirected to another garden.","cn":"想象一只水龙头的水被改道流向另一座花园。"},{"en":"Picture a mind that lets a machine choose for it.","cn":"想象一颗心让机器替它作选择。"}]},"examples":[{"en":"They outsource the night shift to a security firm.","cn":"他们把夜班外包给一家安保公司。"},{"en":"The publisher outsources printing but keeps editing in house.","cn":"出版社外包印刷，却把编辑留在内部。"},{"en":"It is unwise to outsource a decision you cannot audit.","cn":"把无法审计的决策外包出去并不明智。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「out（向外）+ source（来源）」——把活的来源挪到外面 → 外包","word":"outsource"},"root":"由名词 outsourcing 逆构而成，由 out（向外）＋source（来源）构成。source 经古法语 sourse（泉眼）来自拉丁语 surgere（升起），该动词由表示「从下方」的前缀与意为「引导直行」的词根构成。","sensesIntro":{"en":"Eight senses follow the same verb applied to different objects: a task, a part, a job, a system, a product, a service and finally a judgment.","cn":"八个义项是同一个动词施加在不同宾语上：一项任务、一个零件、一个岗位、一套系统、一件产品、一项服务，最后是一个判断。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stack of work passed out through a window.","cn":"核心意象：一叠工作从窗口递了出去。"},"chain":["PUSH OUT","FIND AN OUTSIDE SOURCE","NAME THE OBJECT","CROSS A BORDER","BUY THE RESULT","HAND OVER JUDGMENT"],"branches":[{"senses":"01 · 02","en":"WHOLE JOB OR SINGLE TASK: the verb takes either scope without changing meaning.","cn":"整项工作或单一任务：动词对两种范围都适用，意义不变。"},{"senses":"03 · 06","en":"PARTS AND PRODUCTS: manufacturing shows that objects can be handed over at any stage.","cn":"零件与产品：制造业说明，任何阶段的物件都可以被交出去。"},{"senses":"04","en":"THE BORDER: location enters public debate even though it is not in the word.","cn":"国界：地点进入公共争论，尽管它并不在词形里。"},{"senses":"05 · 07","en":"SYSTEMS AND SERVICES: invisible work moves out exactly as goods do.","cn":"系统与服务：无形的工作与货物一样移出。"},{"senses":"08","en":"JUDGMENT: the final object is not work but the right to decide.","cn":"判断：最后的宾语不是工作，而是决定权。"}]},"affixes":{"intro":{"en":"The word is an English adverb plus an English noun of French and Latin origin; it is read as a compound, not as a suffixed stem.","cn":"这个词由一个英语副词加一个源自法语与拉丁语的英语名词构成，应按复合词而非词缀派生来读。"},"latinIntro":{"en":"The Latin root surgere gives source, resource and surge; out is English.","cn":"拉丁语词根 surgere 给出「来源」「资源」与「涌起」；「向外」这一半来自英语。"},"items":[{"word":"out-","structure":"out- (English adverb, 'outside')","meaning":"outside; outward","meaningCN":"在外；向外","example":"The first half sends the action outward.","exampleCN":"前半部分把动作推向外面。"},{"word":"source","structure":"source (English noun from Old French)","meaning":"the origin or supplier","meaningCN":"来源；供应方","example":"The firm found a cheaper source.","exampleCN":"企业找到了更便宜的来源。"},{"word":"outsource","structure":"out + source (compound verb)","meaning":"to obtain from outside","meaningCN":"向外部取得","example":"They outsource the testing.","exampleCN":"他们把测试包了出去。"},{"word":"outsourcing","structure":"outsource + -ing (activity or result)","meaning":"the practice of moving work out","meaningCN":"把工作移到外部的做法","example":"Outsourcing saved the firm a floor of staff.","exampleCN":"外包让企业省掉一层楼的员工。"},{"word":"outsourced","structure":"outsource + -ed (past participle)","meaning":"handed to an outside supplier","meaningCN":"已交给外部供应商的","example":"The payroll is outsourced.","exampleCN":"薪酬发放已外包。"},{"word":"outsourcer","structure":"outsource + -er (one who does)","meaning":"the firm that takes the work on","meaningCN":"承接这项工作的公司","example":"The outsourcer employs two thousand agents.","exampleCN":"承接方雇有两千名坐席。"},{"word":"sub-","structure":"sub- (Latin prefix, 'from below')","meaning":"from below; upward","meaningCN":"从下方；向上","example":"The prefix inside source gives the image of rising water.","exampleCN":"来源一词内部的前缀带来水向上涌的画面。"},{"word":"surgere","structure":"surgere, surrexi, surrectum (Latin verb)","meaning":"to rise, spring up","meaningCN":"升起；涌出","example":"The Latin verb is the base of source.","exampleCN":"这个拉丁动词是「来源」的底座。"}],"latinEntries":[{"word":"surgere","structure":"surgere, surrexi, surrectum (verb, third conjugation)","meaning":"to rise, spring up","meaningCN":"升起；涌出"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to lead straight, guide","meaningCN":"引直；引导"}],"derivatives":[{"word":"outsourcing","pos":"n.","zh":"外包；外包做法"},{"word":"outsourced","pos":"adj.","zh":"已外包的"},{"word":"outsourcer","pos":"n.","zh":"外包承接方"}]}},{"word":"marketing","ipa_uk":"/ˈmɑːkɪtɪŋ/","ipa_us":"/ˈmɑːrkɪtɪŋ/","definition_zh":"市场营销；营销；促销推广；营销部门","definition_en":"the activity of finding out what customers want and persuading them to buy, or the department that does it","core_image":"白板上画满箭头：产品、价格、渠道、推广四个方块被连成一张网","scene":"会议室的白板上画满箭头，产品、价格、渠道与推广被反复挪动，最后定下一套能打动顾客的组合。Good marketing starts before the product is finished.","sceneCN":"白板上的四个方块被箭头反复连接，最后形成一套面向顾客的组合；句中的 marketing 指「研究并满足顾客需求、促成购买的整体活动」（第 1 个义项：从了解需求到促成交易的整套经营职能）。图中可辨识物件：白板、方块图、箭头、记号笔。","pos":[{"tag":"n.","zh":"市场营销；营销"},{"tag":"n.","zh":"营销部门；营销职能"}],"collocations":[{"phrase":"marketing strategy","zh":"营销策略"},{"phrase":"marketing campaign","zh":"营销活动"},{"phrase":"digital marketing","zh":"数字营销"},{"phrase":"marketing mix","zh":"营销组合"},{"phrase":"direct marketing","zh":"直接营销"},{"phrase":"marketing department","zh":"营销部门"}],"forms":[{"label":"动词（营销）","form":"market"},{"label":"三单","form":"markets"},{"label":"过去式","form":"marketed"},{"label":"现在分词","form":"marketing"},{"label":"施动者名词","form":"marketer"},{"label":"形容词（有销路的）","form":"marketable"}],"derivatives":[{"word":"market","pos":"v./n.","zh":"营销；销售 / 市场"},{"word":"marketer","pos":"n.","zh":"营销人员"},{"word":"marketable","pos":"adj.","zh":"有销路的"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"}],"senses":[{"no":"01","title":"The whole activity of meeting demand","titleCN":"研究并满足顾客需求、促成购买的整体活动","definition":"the business activity of understanding what customers want and persuading them to buy","definitionCN":"理解顾客所需并说服其购买的整体经营活动","example":"Good marketing starts before the product is finished.","exampleCN":"好的营销在产品做完之前就已开始。","why":"the word began as a noun for trade and its place, then took the activity ending to name what is done in that place.","whyCN":"这个词最初指贸易及其场所，加上表活动的词尾后，就指在那个场所里所做的事。"},{"no":"02","title":"The department or function","titleCN":"承担营销工作的部门或职能","definition":"the team or function inside a firm responsible for promotion and customer research","definitionCN":"企业内负责推广与顾客研究的团队或职能","example":"Marketing approved the new packaging before the launch.","exampleCN":"上市前，营销部门批准了新包装。","why":"the activity's name transferred to the people who perform it, as with purchasing and procurement.","whyCN":"活动名被转给了执行它的人，这与采购一词的情况相同。"},{"no":"03","title":"The marketing mix","titleCN":"由产品、价格、渠道、推广构成的营销组合","definition":"the planned combination of product, price, place and promotion","definitionCN":"把产品、价格、渠道与推广编排成一体的组合","example":"The marketing mix was rebuilt around service speed.","exampleCN":"营销组合围绕服务速度被重新编排。","why":"once several levers are adjusted together, the trade gives the bundle a name of its own.","whyCN":"当几根杠杆被一起调整时，行业就给这一组合起了专门名称。"},{"no":"04","title":"Direct marketing","titleCN":"直接寄送给特定顾客的营销","definition":"promotion sent straight to named individuals through mail, phone or email","definitionCN":"通过邮件、电话或电子邮件直接寄给具名个人的推广","example":"Direct marketing to the list doubled the response rate.","exampleCN":"直接寄给名单上的顾客，使回应率翻倍。","why":"the channel is described by an adjective, because the general word covers every channel.","whyCN":"渠道用形容词来描述，因为一般词涵盖所有渠道。"},{"no":"05","title":"Digital marketing","titleCN":"通过网站、搜索与社交平台进行的营销","definition":"promotion carried out through websites, search engines and social platforms","definitionCN":"通过网站、搜索引擎与社交平台进行的推广","example":"Digital marketing let a small shop reach distant buyers.","exampleCN":"数字营销让一家小店接触到远方买家。","why":"a new medium needs a label, and the old activity simply takes a prefix.","whyCN":"新媒介需要一个标签，旧的活动只需添一个前缀。"},{"no":"06","title":"A written marketing plan","titleCN":"成文的营销策略或计划","definition":"a documented plan setting out targets, audiences and the means of reaching them","definitionCN":"写明目标、受众与触达方式的成文计划","example":"The marketing plan named three audiences and one budget.","exampleCN":"营销计划列明了三类受众与一份预算。","why":"planning turns the activity into a document, and the same word covers the document.","whyCN":"规划把活动变成文件，同一个词也指这份文件。"},{"no":"07","title":"Word-of-mouth spread","titleCN":"靠顾客口碑自发扩散的营销","definition":"promotion that spreads because customers pass it on rather than because it was bought","definitionCN":"因顾客主动转述而扩散、并非花钱买来的推广","example":"Word-of-mouth marketing filled the workshop without an ad.","exampleCN":"口碑营销没打广告就把工坊报满了。","why":"when the audience does the spreading, the trade still calls it marketing, because the effect is the same.","whyCN":"当受众自己替你做传播时，行业仍称之为营销，因为效果相同。"},{"no":"08","title":"Selling oneself","titleCN":"抽象义：把自己当作产品来经营","definition":"the effort to present one's own skills, image or ideas as attractive to others","definitionCN":"把自己的技能、形象或想法呈现得对他人有吸引力的努力","example":"Her personal marketing was better than her product.","exampleCN":"她的自我营销比她的产品更出色。","why":"the commercial frame generalizes: anyone can be the product and anyone can be the audience.","whyCN":"商业框架被一般化：任何人都可以成为产品，任何人也可以成为受众。"}],"etymology":{"intro":{"en":"Marketing is market plus the English activity ending -ing; market comes from Latin mercatus 'trade, marketplace'. Dates are approximate.","cn":"marketing 是 market 加英语表活动的词尾构成；market 来自拉丁语 mercatus「贸易、市场」。年代均为约数。"},"items":[{"era":"LATIN MERX","en":"Merx 'wares' is the noun behind the trading verb; its deeper origin is not established.","cn":"merx「货物」是那个交易动词背后的名词，其更早来源未有定论。"},{"era":"LATIN MERCARI","en":"Mercari meant 'to trade, deal', and its participle mercatus named trade and the place of trade.","cn":"mercari 意为「做买卖、经营」，其分词 mercatus 指贸易与交易之地。"},{"era":"ENGLISH MARKET","en":"English market first named a place where goods were sold, then the demand for goods itself.","cn":"英语 market 先指售卖货物的场所，后指对货物的需求本身。"},{"era":"MARKETING AS ACTIVITY","en":"From the sixteenth century marketing meant buying and selling in a market; the modern promotional sense grew in the early twentieth century.","cn":"从十六世纪起，marketing 指在市场里买卖；现代推广义在二十世纪初发展起来。"},{"era":"MODERN DISCIPLINE","en":"After the Second World War marketing became a taught discipline with its own mix, research and budgets.","cn":"第二次世界大战后，营销成为一门被教授的学科，拥有自己的组合、调研与预算。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the Latin noun merx has no agreed origin before Latin, so any earlier form proposed for it is a reconstruction.","cn":"来源不确定（更深词根）：拉丁语名词 merx 在拉丁语之前没有公认来源，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same trading and market stock; group two holds the neighbouring business activities.","cn":"第一组同出「交易、市场」这一词干；第二组是相邻的商业活动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"market","ipa":"/ˈmɑːkɪt/","tag":"the place or demand","definition":"The place where trade happens or the demand for a product; marketing is the activity directed at it.","definitionCN":"交易发生的场所或对某产品的需求；营销则是针对它展开的活动。"},{"word":"marketer","ipa":"/ˈmɑːkɪtə/","tag":"the person","definition":"A person who works in marketing; the shorter form names the activity, the longer one the practitioner.","definitionCN":"从事营销工作的人；较短的形式指活动，较长的指从业者。"},{"word":"marketable","ipa":"/ˈmɑːkɪtəbl/","tag":"the quality","definition":"Able to be sold or attractive to buyers, built with an adjective suffix on the same noun.","definitionCN":"能卖出或对买家有吸引力的，由同一名词加形容词后缀构成。"},{"word":"marketplace","ipa":"/ˈmɑːkɪtpleɪs/","tag":"the location","definition":"The physical or online space where buyers and sellers meet, a compound of market and place.","definitionCN":"买卖双方相遇的实体或线上空间，由「市场」与「场所」合成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advertising","ipa":"/ˈædvətaɪzɪŋ/","tag":"paid messages","definition":"Paid public messages that promote goods; it is one part of marketing, not the whole.","definitionCN":"为推广商品而付费的公开信息；是营销的一部分而非全部。"},{"word":"promotion","ipa":"/prəˈməʊʃn/","tag":"a push for sales","definition":"A specific campaign or offer meant to lift sales in the short term.","definitionCN":"为短期提升销量而做的具体活动或优惠。"},{"word":"sales","ipa":"/seɪlz/","tag":"the closing stage","definition":"The activity of actually closing deals with customers, the stage that follows marketing.","definitionCN":"真正与顾客成交的活动，是营销之后的阶段。"},{"word":"branding","ipa":"/ˈbrændɪŋ/","tag":"identity work","definition":"Building a name and identity for a product, a long-term part of marketing.","definitionCN":"为产品建立名称与身份，是营销中长期的一面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real market root, the real discipline phrases and the real department use.","cn":"正常联想使用真实的「市场」词根、真实的学科搭配与真实的部门用法。"},"normal":[{"en":"Market plus the activity ending: what people do in a market, raised to a discipline.","cn":"「市场」加表活动的词尾：人们在市场里做的事，被提升为一门学科。"},{"en":"Fixed phrases mark it: marketing strategy, marketing campaign, marketing mix.","cn":"固定搭配标出这个词：营销策略、营销活动、营销组合。"},{"en":"The family runs market, marketer, marketable and marketplace.","cn":"同族词包括市场、营销人员、有销路的与市场场所。"},{"en":"The same root gives commerce and merchant, all about trade.","cn":"同一词根还给出「商业」与「商人」，都与交易有关。"},{"en":"Advertising is one tool; marketing decides what the tool should say.","cn":"广告是一件工具；营销决定这件工具该说什么。"}],"abstract":[{"en":"Picture four blocks joined by arrows, each arrow a decision.","cn":"想象四个方块被箭头连接，每支箭头都是一项决定。"},{"en":"Picture a shop window built before the goods are finished.","cn":"想象橱窗在货物做完之前就已搭好。"},{"en":"Picture a person walking into a room carrying their own poster.","cn":"想象一个人走进房间，手里举着自己的海报。"}]},"examples":[{"en":"Marketing found that buyers cared more about delivery than price.","cn":"营销发现买家更在意送货而不是价格。"},{"en":"The marketing budget was moved from print to search.","cn":"营销预算从纸媒转到了搜索广告。"},{"en":"She studied marketing before joining the family firm.","cn":"她在加入家族企业之前学过营销。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「market（市场）+ ing」——在市场里做的事 → 营销","word":"marketing"},"root":"英语 market（市场，来自拉丁语 mercatus「贸易、市场」，再往上为 mercari「做买卖」与 merx「货物」）加表活动的词尾构成。merx 更早来源无定论。","sensesIntro":{"en":"Eight senses begin with the whole activity of meeting demand and then narrow into a department, a mix, a channel, a plan, a rumour and finally a person selling themselves.","cn":"八个义项从「满足需求」的整体活动开始，再收窄为部门、组合、渠道、计划、口碑，最后成为一个人在推销自己。"},"semanticMap":{"core":{"en":"CORE IMAGE: four blocks joined by arrows on a whiteboard.","cn":"核心意象：白板上四个方块被箭头连成一张网。"},"chain":["TRADE","A MARKET","UNDERSTAND DEMAND","PERSUADE TO BUY","COMBINE THE LEVERS","SELL ANYTHING"],"branches":[{"senses":"01 · 02","en":"THE ACTIVITY AND ITS OFFICE: what is done in a market becomes a function with a door.","cn":"活动与其部门：市场里所做的事变成一个有自己的门的职能。"},{"senses":"03 · 06","en":"PLANNED COMBINATION: levers and documents turn persuasion into a design.","cn":"有计划的组合：杠杆与文件把说服变成一项设计。"},{"senses":"04 · 05","en":"CHANNELS: direct mail and digital media are the same message on different wires.","cn":"渠道：直邮与数字媒体是同一条消息走在不同的线上。"},{"senses":"07","en":"THE AUDIENCE SPREADS IT: word of mouth keeps the effect without the purchase.","cn":"受众替它传播：口碑让效果出现而无需购买媒体。"},{"senses":"08","en":"THE PERSON AS PRODUCT: the last version has no goods at all.","cn":"人即产品：最后一个版本完全没有货物。"}]},"affixes":{"intro":{"en":"The word is a Latin-rooted noun plus the English activity ending; the root also builds merchant, commerce and marketable.","cn":"这个词是一个拉丁词根名词加英语表活动的词尾；该词根还构成「商人」「商业」与「有销路的」。"},"latinIntro":{"en":"Latin merx and mercari give market, merchant, commerce and mercantile; the ending is English.","cn":"拉丁语 merx 与 mercari 给出「市场」「商人」「商业」与「商业的」；词尾来自英语。"},"items":[{"word":"merx","structure":"merx, mercis (Latin noun, third declension)","meaning":"wares, goods","meaningCN":"货物；商品","example":"The root names what is traded.","exampleCN":"这个词根指被交易的东西。"},{"word":"mercari","structure":"mercari, mercatus sum (Latin verb)","meaning":"to trade","meaningCN":"做买卖","example":"The verb names the activity.","exampleCN":"这个动词指交易活动。"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, marketplace","meaningCN":"贸易；市场","example":"The participle gave the English noun market.","exampleCN":"这个分词给出了英语名词「市场」。"},{"word":"market","structure":"market (English noun and verb)","meaning":"a place or demand for trade","meaningCN":"交易场所或需求","example":"The market for the device was small.","exampleCN":"这种设备的市场很小。"},{"word":"-ing","structure":"-ing (English suffix, activity)","meaning":"the activity of doing","meaningCN":"进行某活动的过程","example":"The ending turns the place into a practice.","exampleCN":"这个词尾把场所变成一门实践。"},{"word":"marketing","structure":"market + -ing","meaning":"the activity of promoting and selling","meaningCN":"推广与销售的活动","example":"Marketing begins with research.","exampleCN":"营销从调研开始。"},{"word":"marketer","structure":"market + -er (one who does)","meaning":"a marketing worker","meaningCN":"营销从业者","example":"The marketer wrote the campaign brief.","exampleCN":"营销人员写了活动简报。"},{"word":"marketable","structure":"market + -able (can be)","meaning":"able to be sold","meaningCN":"有销路的；可销售的","example":"The design proved marketable.","exampleCN":"这个设计证明有销路。"},{"word":"marketplace","structure":"market + place","meaning":"the space of trade","meaningCN":"交易的空间","example":"The online marketplace never closes.","exampleCN":"网络市场从不关门。"}],"latinEntries":[{"word":"merx","structure":"merx, mercis (f., third declension)","meaning":"wares, goods","meaningCN":"货物；商品"},{"word":"mercari","structure":"mercari, mercatus sum (verb, first conjugation)","meaning":"to trade","meaningCN":"做买卖"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, marketplace","meaningCN":"贸易；市场"}],"derivatives":[{"word":"market","pos":"v./n.","zh":"营销；销售 / 市场"},{"word":"marketer","pos":"n.","zh":"营销人员"},{"word":"marketable","pos":"adj.","zh":"有销路的"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"}]}},{"word":"marketer","ipa_uk":"/ˈmɑːkɪtə/","ipa_us":"/ˈmɑːrkɪtər/","definition_zh":"营销人员；营销从业者；推销者","definition_en":"a person who works in marketing, or anyone who promotes a product, brand or idea","core_image":"一个人站在摊位前，把同一件货换着说法讲给不同的人听","scene":"摊位前的人先向学生讲价格，再向家长讲耐用，同一件货被讲成两种好处。A good marketer listens before speaking.","sceneCN":"摊主面对不同顾客换用不同的说法，同一件货被讲成两种好处；句中的 marketer 指「从事营销、负责推广的人」（第 1 个义项：以研究需求并说服购买为职业的人）。图中可辨识物件：摊位、商品、宣传牌、顾客。","pos":[{"tag":"n.","zh":"营销人员；营销从业者"},{"tag":"n.","zh":"推销者；推广者"}],"collocations":[{"phrase":"digital marketer","zh":"数字营销人员"},{"phrase":"brand marketer","zh":"品牌营销人员"},{"phrase":"direct marketer","zh":"直复营销者"},{"phrase":"online marketer","zh":"网络营销人员"},{"phrase":"marketer's toolkit","zh":"营销人员的工具箱"},{"phrase":"experienced marketer","zh":"资深营销人员"}],"forms":[{"label":"复数","form":"marketers"},{"label":"名词（营销）","form":"marketing"},{"label":"形容词（有销路的）","form":"marketable"},{"label":"动词（营销）","form":"market"},{"label":"过去式","form":"marketed"},{"label":"现在分词","form":"marketing"}],"derivatives":[{"word":"marketing","pos":"n.","zh":"营销；营销活动"},{"word":"marketable","pos":"adj.","zh":"有销路的"},{"word":"market","pos":"v./n.","zh":"营销；销售 / 市场"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"}],"senses":[{"no":"01","title":"A marketing professional","titleCN":"以营销为职业的人","definition":"a person whose job is to research customers and promote products","definitionCN":"以研究顾客并推广产品为职业的人","example":"A good marketer listens before speaking.","exampleCN":"好的营销人员先听后说。","why":"the activity ending on the trade noun names the person who carries the activity on.","whyCN":"行业名词加上表施动者的后缀，指从事这项活动的人。"},{"no":"02","title":"A digital marketer","titleCN":"专注网络渠道的营销人员","definition":"a marketer who works through search, social media and online advertising","definitionCN":"通过搜索、社交媒体与网络广告开展工作的营销人员","example":"The digital marketer tested five headlines in a week.","exampleCN":"这位数字营销人员一周内测了五条标题。","why":"the channel is named by an adjective, while the person's role stays the same.","whyCN":"渠道用形容词来标出，而人的角色并未改变。"},{"no":"03","title":"A brand marketer","titleCN":"负责单一品牌形象的营销人员","definition":"a marketer responsible for one brand's image and message","definitionCN":"负责某一品牌的形象与信息的营销人员","example":"The brand marketer refused to discount the name.","exampleCN":"品牌营销人员拒绝让这个名号打折。","why":"when the object of promotion is a brand rather than a product, the job title changes with it.","whyCN":"当推广对象是品牌而非产品时，职务名称也随之改变。"},{"no":"04","title":"A direct marketer","titleCN":"以直邮、电话等方式直接接触顾客的人","definition":"a marketer who reaches named individuals through mail, phone or email","definitionCN":"通过邮件、电话或电子邮件接触具名个人的营销人员","example":"The direct marketer measured replies per thousand letters.","exampleCN":"直复营销者按每千封信的回复数来计量。","why":"the adjective marks the channel, because the effect is still measured on the same person.","whyCN":"形容词标记渠道，因为效果仍落在同一个人身上。"},{"no":"05","title":"The promoter of one product","titleCN":"某个具体产品的推广负责人","definition":"the person responsible for taking one product to its audience","definitionCN":"负责把某一产品带到受众面前的人","example":"The marketer of the new phone had one quarter to build demand.","exampleCN":"新款手机的推广负责人只有一个季度来造需求。","why":"attaching the product narrows the role from a profession to a single campaign.","whyCN":"接上具体产品，就把这个角色从一种职业收窄为一场活动。"},{"no":"06","title":"A trader in an old market","titleCN":"旧义：在市场里买卖的人","definition":"a person who buys and sells in a market, in older usage","definitionCN":"较早用法中在市场里买卖的人","example":"The marketer weighed his grain at dawn.","exampleCN":"那个市场商人在天亮时称好了谷物。","why":"before marketing became a profession, the word simply meant one who traded in a market.","whyCN":"在营销成为职业之前，这个词只指在市场里交易的人。"},{"no":"07","title":"A job title","titleCN":"作为职务名称的「营销专员」","definition":"a formal job title in a company's marketing team","definitionCN":"公司营销团队中的正式职务名称","example":"She was hired as the sole marketer for the region.","exampleCN":"她受聘为该地区唯一的营销专员。","why":"organizations turn roles into titles, and the same noun serves as the label on a door.","whyCN":"组织把角色变成职称，同一个名词就成了门上的标签。"},{"no":"08","title":"Anyone promoting an idea","titleCN":"抽象义：任何推销某种主张的人","definition":"anyone who works to make an idea, cause or image attractive to others","definitionCN":"任何努力使某种主张、事业或形象对他人有吸引力的人","example":"Every reformer is a marketer of other people's hopes.","exampleCN":"每位改革者都在替别人的希望做营销。","why":"remove the goods and the role remains: someone must still make the thing wanted.","whyCN":"抽掉货物，角色仍在：总得有人让那件东西被人想要。"}],"etymology":{"intro":{"en":"Marketer is market plus the agent suffix; market comes from Latin mercatus 'trade, marketplace'. Dates are approximate.","cn":"marketer 是 market 加表施动者的后缀；market 来自拉丁语 mercatus「贸易、市场」。年代均为约数。"},"items":[{"era":"LATIN MERX","en":"Merx 'wares' is the noun behind the trading verb; its deeper origin is unsettled.","cn":"merx「货物」是那个交易动词背后的名词，其更早来源未有定论。"},{"era":"LATIN MERCARI","en":"Mercari 'to trade' produced the participle mercatus, which named both trade and its place.","cn":"mercari「做买卖」产生分词 mercatus，后者既指贸易也指其场所。"},{"era":"ENGLISH MARKET","en":"Market entered English as a place of trade and later also meant demand for goods.","cn":"market 进入英语时指交易场所，后来又指对货物的需求。"},{"era":"MARKETER","en":"Adding the agent suffix produced the name for a person who trades, and later for one who promotes.","cn":"加上表施动者的后缀，先指在市场交易的人，后指从事推广的人。"},{"era":"MODERN PROFESSION","en":"In the twentieth century the word settled on the marketing professional, with titles, teams and budgets.","cn":"到二十世纪，这个词固定指营销从业者，连同职称、团队与预算。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the Latin noun merx has no agreed pre-Latin origin, so any older form proposed for it is a reconstruction.","cn":"来源不确定（更深词根）：拉丁语名词 merx 没有公认的拉丁语之前来源，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same market stem, easily swapped; group two holds neighbouring roles in selling.","cn":"第一组同出「市场」词干，容易互换；第二组是销售中的相邻角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","tag":"the activity","definition":"The work of researching and promoting; the longer form names the person who does it.","definitionCN":"研究与推广的工作；较长的形式指做这项工作的人。"},{"word":"market","ipa":"/ˈmɑːkɪt/","tag":"the place or demand","definition":"The place of trade or the demand for a product, the noun from which the role is built.","definitionCN":"交易场所或对产品的需求，是构成这个角色名的名词。"},{"word":"marketable","ipa":"/ˈmɑːkɪtəbl/","tag":"the quality","definition":"Able to be sold; a marketer's task is to make a thing marketable.","definitionCN":"能卖出去的；营销人员的工作就是让东西变得有销路。"},{"word":"marketplace","ipa":"/ˈmɑːkɪtpleɪs/","tag":"the space","definition":"The place, physical or online, where the marketer's audience gathers.","definitionCN":"营销人员的受众聚集之处，可以是实体或线上的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advertiser","ipa":"/ˈædvətaɪzə/","tag":"buys media","definition":"The party that pays for public messages; a marketer may or may not be the advertiser.","definitionCN":"为公开信息付费的一方；营销人员不一定是广告主。"},{"word":"promoter","ipa":"/prəˈməʊtə/","tag":"runs events","definition":"A person who organizes publicity or events, often for music or sport.","definitionCN":"组织宣传或活动的人，常见于音乐与体育。"},{"word":"salesperson","ipa":"/ˈseɪlzpɜːsən/","tag":"closes deals","definition":"A person who sells directly to customers, the stage after the marketer's work.","definitionCN":"直接向顾客出售的人，处在营销工作之后的阶段。"},{"word":"merchandiser","ipa":"/məˈtʃændaɪzə/","tag":"arranges goods","definition":"A person who plans how goods are displayed and presented in shops.","definitionCN":"规划货物在店中如何陈列与呈现的人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real market stem, the real job titles and the real channel adjectives.","cn":"正常联想使用真实的「市场」词干、真实的职称与真实的渠道形容词。"},"normal":[{"en":"Market plus the person suffix: the one who works the market.","cn":"「市场」加表人的后缀：在市场里做事的人。"},{"en":"The pair marketer and marketing: one is the person, the other the work.","cn":"营销人员与营销：一个是人，一个是工作。"},{"en":"Fixed phrases mark it: digital marketer, brand marketer, direct marketer.","cn":"固定搭配标出这个词：数字营销人员、品牌营销人员、直复营销者。"},{"en":"The same stem gives market, marketable and marketplace.","cn":"同一词干还给出市场、有销路的与市场场所。"},{"en":"A marketer is judged by whether the thing becomes wanted.","cn":"营销人员的成败，看那件东西是否变得被人想要。"}],"abstract":[{"en":"Picture a stallholder changing the story for each passer-by.","cn":"想象摊主对每位路过的人换一套说法。"},{"en":"Picture a person holding two labels and choosing which to show.","cn":"想象一个人拿着两张标签，挑一张举出来。"},{"en":"Picture a reformer carrying a poster for someone else's dream.","cn":"想象一位改革者举着别人梦想的海报。"}]},"examples":[{"en":"The marketer rewrote the label after the first customer survey.","cn":"首次顾客调研之后，营销人员重写了标签。"},{"en":"A marketer who never buys the product rarely understands it.","cn":"从不买自己产品的营销人员很少真正懂它。"},{"en":"She hired a marketer to explain the tool in plain words.","cn":"她请了一位营销人员，用平实的话解释这个工具。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「market（市场）+ er（人）」——在市场里做事的人 → 营销人员","word":"marketer"},"root":"market（市场，来自拉丁语 mercatus「贸易、市场」，再往上为 mercari「做买卖」与 merx「货物」）加表施动者的后缀，指从事市场推广的人。merx 更早来源无定论。","sensesIntro":{"en":"Eight senses keep one person in view: the one who makes a thing wanted, whether a professional, a channel specialist, a product owner, an old trader or a promoter of ideas.","cn":"八个义项始终看着同一个人：让某件东西被人想要的那一位，可以是专业人士、渠道专才、产品负责人、旧时的市场商人，也可以是主张的推广者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stallholder telling each passer-by a different true story.","cn":"核心意象：摊主对每位路过的人讲一个不同的、却都真实的故事。"},"chain":["TRADE IN A MARKET","THE PERSON","RESEARCH THE AUDIENCE","PROMOTE A PRODUCT","OWN A BRAND","PROMOTE ANYTHING"],"branches":[{"senses":"01 · 07","en":"ROLE AND TITLE: the worker and the job title are the same figure seen from inside and from a door.","cn":"角色与职衔：从业者与职称是同一人物，一个从内部看，一个从门上标签看。"},{"senses":"02 · 04","en":"CHANNEL SPECIALISTS: digital and direct are the same person on different wires.","cn":"渠道专才：数字与直复是同一个人走在不同的线上。"},{"senses":"03 · 05","en":"ATTACHED TO A NAME: a brand or a product narrows the role to one thing.","cn":"依附于名号：品牌或产品把角色收窄到一件东西上。"},{"senses":"06","en":"OLDER TRADER: before the profession existed, the word meant anyone trading in a market.","cn":"旧时商人：在职业出现之前，这个词指任何在市场交易的人。"},{"senses":"08","en":"NO GOODS: the last version promotes hopes, causes and images.","cn":"没有货物：最后一个版本推广的是希望、事业与形象。"}]},"affixes":{"intro":{"en":"The word is a Latin-rooted noun plus the English agent suffix, and the root family covers trade and markets.","cn":"这个词是一个拉丁词根名词加英语施动后缀，其词根家族涵盖交易与市场。"},"latinIntro":{"en":"Latin merx and mercari supply market, merchant and commerce; the person suffix is English.","cn":"拉丁语 merx 与 mercari 提供「市场」「商人」与「商业」的词干；表人的后缀来自英语。"},"items":[{"word":"merx","structure":"merx, mercis (Latin noun)","meaning":"wares, goods","meaningCN":"货物；商品","example":"The root names what is traded.","exampleCN":"这个词根指被交易的东西。"},{"word":"mercari","structure":"mercari, mercatus sum (Latin verb)","meaning":"to trade","meaningCN":"做买卖","example":"The verb names the activity behind the role.","exampleCN":"这个动词指这一角色背后的活动。"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, marketplace","meaningCN":"贸易；市场","example":"The participle gave the English market.","exampleCN":"这个分词给出了英语的「市场」。"},{"word":"market","structure":"market (English noun and verb)","meaning":"a place or demand for trade","meaningCN":"交易场所或需求","example":"The market was crowded at dawn.","exampleCN":"天亮时市场很拥挤。"},{"word":"-er","structure":"-er (English suffix, 'one who does')","meaning":"the person who acts","meaningCN":"执行动作的人","example":"The suffix turns the market into a person.","exampleCN":"这个后缀把「市场」变成一个人。"},{"word":"marketer","structure":"market + -er","meaning":"a person who promotes goods","meaningCN":"从事推广的人","example":"The marketer wrote the slogans.","exampleCN":"营销人员写了那些口号。"},{"word":"marketing","structure":"market + -ing (activity)","meaning":"the work of promoting","meaningCN":"推广的工作","example":"Marketing reports to the founder.","exampleCN":"营销部门向创始人汇报。"},{"word":"marketable","structure":"market + -able (can be)","meaning":"able to be sold","meaningCN":"有销路的","example":"The idea was marketable at once.","exampleCN":"这个想法立刻就有了销路。"},{"word":"marketplace","structure":"market + place","meaning":"the space of trade","meaningCN":"交易的空间","example":"The marketplace moved online.","exampleCN":"市场空间搬到了线上。"}],"latinEntries":[{"word":"merx","structure":"merx, mercis (f., third declension)","meaning":"wares, goods","meaningCN":"货物；商品"},{"word":"mercari","structure":"mercari, mercatus sum (verb, first conjugation)","meaning":"to trade","meaningCN":"做买卖"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, marketplace","meaningCN":"贸易；市场"}],"derivatives":[{"word":"marketing","pos":"n.","zh":"营销；营销活动"},{"word":"marketable","pos":"adj.","zh":"有销路的"},{"word":"market","pos":"v./n.","zh":"营销；销售 / 市场"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"}]}},{"word":"marketable","ipa_uk":"/ˈmɑːkɪtəbl/","ipa_us":"/ˈmɑːrkətəbl/","definition_zh":"可销售的；有销路的；有市场价值的；（证券）可上市交易的；可转让的","definition_en":"able to be sold, attractive to buyers, or tradable on a market","core_image":"一件东西贴上价签后，很快有人愿意掏钱，价签本身就证明它卖得掉","scene":"摊主把两件东西摆上桌，一件很快被拿走，另一件整晚没人看，前者显然更卖得动。Her skills are marketable in three different industries.","sceneCN":"两张桌子上的东西表现完全不同，一件迅速成交，另一件无人问津；句中的 marketable 指「有销路、卖得出去的」（第 1 个义项：能在市场上找到买主的）。图中可辨识物件：摊位、两件商品、价签、顾客。","pos":[{"tag":"adj.","zh":"可销售的；有销路的"},{"tag":"adj.","zh":"有市场价值的；可交易的"}],"collocations":[{"phrase":"marketable skills","zh":"有市场价值的技能"},{"phrase":"marketable securities","zh":"可交易证券"},{"phrase":"marketable product","zh":"有销路的产品"},{"phrase":"marketable title","zh":"可转让的产权"},{"phrase":"marketable value","zh":"市场价值"},{"phrase":"commercially marketable","zh":"具备商业销路的"}],"forms":[{"label":"比较级","form":"more marketable"},{"label":"名词（可销售性）","form":"marketability"},{"label":"反义词","form":"unmarketable"},{"label":"动词（推销）","form":"market"},{"label":"过去式","form":"marketed"},{"label":"现在分词","form":"marketing"}],"derivatives":[{"word":"marketability","pos":"n.","zh":"可销售性；市场吸引力"},{"word":"unmarketable","pos":"adj.","zh":"无销路的；卖不掉的"},{"word":"market","pos":"v./n.","zh":"推销 / 市场"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"},{"word":"marketing","pos":"n.","zh":"营销"}],"senses":[{"no":"01","title":"Able to find buyers","titleCN":"能在市场上找到买主、卖得出去","definition":"able to be sold because buyers exist and want it","definitionCN":"因有买家存在且想要它而能够售出","example":"Her skills are marketable in three different industries.","exampleCN":"她的技能在三个不同行业里都有销路。","why":"market plus the suffix 'able to be': what can be put into a market and sold.","whyCN":"「市场」加「能够被……」的后缀：能够被放进市场并卖出去。"},{"no":"02","title":"Attractive to buyers","titleCN":"对买家有吸引力、讨人喜欢","definition":"presented in a way that makes buyers want it, whether or not it is the best option","definitionCN":"以让买家想要的方式呈现，无论它是否最佳选择","example":"The design was marketable long before it was reliable.","exampleCN":"这个设计在可靠之前很久就已很讨买家喜欢。","why":"the suffix covers not only what can be sold but what sells well, so appeal enters the meaning.","whyCN":"这个后缀不只指「能卖」，也指「卖得好」，因此吸引力进入了词义。"},{"no":"03","title":"Tradable on a market","titleCN":"在有活跃市场的交易所可买卖的（证券）","definition":"of securities, able to be bought and sold readily on an exchange","definitionCN":"指证券能在交易所随时买卖","example":"Marketable securities can be turned into cash within days.","exampleCN":"可交易证券能在几天内变现。","why":"finance uses the word for what has a ready market, so liquidity is part of the meaning.","whyCN":"金融领域用它指有现成市场的资产，因此流动性成为词义的一部分。"},{"no":"04","title":"Able to be priced","titleCN":"具有可定价的市场价值","definition":"having a value that a market can be asked to put a price on","definitionCN":"具有可以让市场为其定价的价值","example":"The land was marketable at a figure nobody had expected.","exampleCN":"这块地能卖到一个谁也没料到的价钱。","why":"once something has a market, it can be valued, and the adjective covers that step.","whyCN":"一旦某物有了市场，就可以被估值，这个形容词涵盖这一步。"},{"no":"05","title":"Employable skills","titleCN":"雇主愿意出价购买的技能","definition":"of skills, wanted by employers so that they can be exchanged for work","definitionCN":"指技能为雇主所需，可以用来换取工作","example":"Coding is marketable even without a degree.","exampleCN":"即使没有学位，编程技能也很有市场。","why":"the labour market applies the same frame: a skill is sold as labour, so it can be marketable.","whyCN":"劳动力市场使用同一框架：技能作为劳动力被出售，因此也可以「有销路」。"},{"no":"06","title":"A title that can be transferred","titleCN":"产权清晰、可以顺利过户的","definition":"of a property title, free of defects so that a buyer can take it over","definitionCN":"指产权没有瑕疵，买家可以顺利接手","example":"The lawyer confirmed that the title was marketable.","exampleCN":"律师确认该产权可以顺利转让。","why":"property law asks whether a title can actually be sold, and uses the ordinary adjective for it.","whyCN":"物权法要问产权是否真的能卖出，于是用了这个普通形容词。"},{"no":"07","title":"Suitable for a wide audience","titleCN":"符合大众口味、易于推广的","definition":"presented so that a large general audience will accept and want it","definitionCN":"以能让大量普通受众接受并想要的方式呈现","example":"The film was marketable but forgottable.","exampleCN":"这部影片很适合大众市场，却容易被忘记。","why":"appeal to many is a kind of sellability, so the word also judges tone and style.","whyCN":"能被许多人接受也是一种可销售性，因此这个词也用来评判基调与风格。"},{"no":"08","title":"Anything presentable as valuable","titleCN":"抽象义：可被包装呈现为有价值","definition":"able to be presented as worth having, even without a price","definitionCN":"能被呈现为值得拥有，即使没有标价","example":"Hope is marketable even when nothing is for sale.","exampleCN":"即使没有东西在卖，希望也依然有市场。","why":"the commercial frame generalizes: whatever can be made desirable is marketable.","whyCN":"商业框架被一般化：任何能变得令人想要的东西都有市场。"}],"etymology":{"intro":{"en":"Marketable is market plus the English suffix -able, which reached English through French from Latin -abilis. Dates are approximate.","cn":"marketable 是 market 加英语后缀 -able 构成，该后缀经法语来自拉丁语 -abilis。年代均为约数。"},"items":[{"era":"LATIN MERX","en":"Merx 'wares' is the noun behind the trading verb; its deeper origin is not settled.","cn":"merx「货物」是那个交易动词背后的名词，其更早来源未有定论。"},{"era":"LATIN MERCARI","en":"Mercari 'to trade' gave the participle mercatus, which named trade and the place of trade.","cn":"mercari「做买卖」给出分词 mercatus，后者指贸易及其场所。"},{"era":"ENGLISH MARKET","en":"Market named a place of sale and later the demand for goods.","cn":"market 指销售场所，后来也指对货物的需求。"},{"era":"SUFFIX -ABLE","en":"The suffix means 'able to be', so marketable says that a thing can be put on a market and sold.","cn":"这个后缀意为「能够被……」，因此 marketable 表示某物能够进入市场并售出。"},{"era":"FINANCE AND LAW","en":"The nineteenth century extended the word to securities with a ready market and to titles that can be transferred.","cn":"十九世纪把这个词扩展到有现成市场的证券，以及可以转让的产权。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the Latin noun merx has no agreed pre-Latin origin, so any older form proposed for it is a reconstruction.","cn":"来源不确定（更深词根）：拉丁语名词 merx 没有公认的拉丁语之前来源，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words from the same market stem; group two holds near adjectives of sellability.","cn":"第一组同出「市场」词干；第二组是表示可售性的近义形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"market","ipa":"/ˈmɑːkɪt/","tag":"the noun and verb","definition":"The place or demand for trade, and the verb to promote; marketable adds the idea of being fit for it.","definitionCN":"指交易场所或需求，也指推广的动词；marketable 加上「适合进入其中」的意思。"},{"word":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","tag":"the activity","definition":"The work of promoting; something becomes marketable as a result of it.","definitionCN":"推广的工作；某物正是经由这项工作而变得有销路。"},{"word":"marketer","ipa":"/ˈmɑːkɪtə/","tag":"the person","definition":"The person who promotes; marketable describes the object of that work.","definitionCN":"从事推广的人；marketable 描述的则是这项工作的对象。"},{"word":"marketplace","ipa":"/ˈmɑːkɪtpleɪs/","tag":"the space","definition":"The physical or online place of trade where marketable things are offered.","definitionCN":"实体或线上的交易空间，有销路的东西在此出售。"}]},{"heading":"NEAR MEANING","entries":[{"word":"saleable","ipa":"/ˈseɪləbl/","tag":"close synonym","definition":"Able to be sold, usually of goods in good condition; it says nothing about appeal.","definitionCN":"能卖出去的，通常指货物状况良好；不涉及吸引力。"},{"word":"sellable","ipa":"/ˈseləbl/","tag":"plain twin","definition":"A plainer synonym for able to be sold, with no financial or legal overtones.","definitionCN":"更朴素的「能卖掉」，不带金融或法律色彩。"},{"word":"tradable","ipa":"/ˈtreɪdəbl/","tag":"market focus","definition":"Able to be traded, especially on an exchange; it stresses the market rather than the buyer.","definitionCN":"可交易的，尤指在交易所；强调市场而非买家。"},{"word":"commercial","ipa":"/kəˈmɜːʃl/","tag":"profit focus","definition":"Likely to make money; marketable says it can find buyers, commercial says it can earn.","definitionCN":"有望赚钱；marketable 指能找到买家，commercial 指能带来收益。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real market stem, the real suffix meaning and the real finance and legal phrases.","cn":"正常联想使用真实的「市场」词干、真实的后缀含义与真实的金融、法律搭配。"},"normal":[{"en":"Market plus 'able to be': able to be put on a market and sold.","cn":"「市场」加「能够被……」：能够进入市场并卖出去。"},{"en":"Fixed phrases mark it: marketable skills, marketable securities, marketable title.","cn":"固定搭配标出这个词：有市场价值的技能、可交易证券、可转让产权。"},{"en":"The family runs market, marketing, marketer and marketability.","cn":"同族词包括市场、营销、营销人员与可销售性。"},{"en":"Marketable judges the thing; marketing is the work that makes it so.","cn":"marketable 评判的是东西本身，marketing 是让它变成这样的工作。"},{"en":"A marketable title is one a buyer can actually take over.","cn":"可转让的产权，就是买家真能接手的那一种。"}],"abstract":[{"en":"Picture a price tag that someone reaches for without asking why.","cn":"想象一张价签，有人不问缘由就伸手去拿。"},{"en":"Picture a skill carried like a tool that employers queue to borrow.","cn":"想象一项技能像工具一样被带着，雇主排队来借。"},{"en":"Picture hope on a shelf with a tag but no goods behind it.","cn":"想象希望摆在货架上，有价签，身后却没有货。"}]},"examples":[{"en":"The prototype is clever but not yet marketable.","cn":"这个原型很巧妙，但还不能上市销售。"},{"en":"Marketable securities are counted as near-cash.","cn":"可交易证券被算作准现金。"},{"en":"He took a course to make his skills more marketable.","cn":"他上了一门课，让自己的技能更有市场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「market（市场）+ able（能）」——能拿到市场上卖 → 有销路的","word":"marketable"},"root":"英语 market（市场，来自拉丁语 mercatus「贸易、市场」，再往上为 mercari「做买卖」与 merx「货物」）加意为「能够被……」的形容词后缀 -able（经法语来自拉丁语 -abilis）。","sensesIntro":{"en":"Eight senses follow one question: can this thing find a buyer? Goods, skills, securities, titles and even hope each answer it in turn.","cn":"八个义项围绕同一个问题：这件东西能不能找到买家？货物、技能、证券、产权，甚至希望，依次给出回答。"},"semanticMap":{"core":{"en":"CORE IMAGE: a price tag that attracts a hand without any explanation.","cn":"核心意象：一张价签，不必解释就引来一只手。"},"chain":["A MARKET","CAN BE OFFERED","FINDS A BUYER","LOOKS DESIRABLE","HAS A PRICE","CAN BE TRANSFERRED"],"branches":[{"senses":"01 · 02","en":"CAN SELL AND SELLS WELL: finding buyers and being wanted are two degrees of the same fitness.","cn":"能卖与卖得好：找到买家与被想要，是同一种适合度的两个程度。"},{"senses":"03 · 04","en":"READY MARKET: securities and land show that a price needs an active market behind it.","cn":"现成市场：证券与土地说明，价格背后需要一个活跃的市场。"},{"senses":"05","en":"LABOUR AS GOODS: a skill is sold as work, so it too can be marketable.","cn":"劳动即货物：技能作为劳动被出售，因此也能有销路。"},{"senses":"06","en":"CLEAN TITLE: law asks whether the thing can actually change hands.","cn":"干净的产权：法律问的是这东西是否真能易手。"},{"senses":"07 · 08","en":"APPEAL WITHOUT GOODS: tone, style and hope can all be made desirable.","cn":"无需货物的吸引力：基调、风格与希望都能变得令人想要。"}]},"affixes":{"intro":{"en":"The word is a Latin-rooted noun plus a suffix of ability that English borrowed through French.","cn":"这个词是一个拉丁词根名词加一个表「能够」的后缀，后者经法语借入英语。"},"latinIntro":{"en":"Latin merx and mercari give the market stem; Latin -abilis, through French -able, gives the suffix.","cn":"拉丁语 merx 与 mercari 提供「市场」词干；拉丁语 -abilis 经法语 -able 提供后缀。"},"items":[{"word":"merx","structure":"merx, mercis (Latin noun)","meaning":"wares, goods","meaningCN":"货物；商品","example":"The root names what is offered.","exampleCN":"这个词根指被提供出售的东西。"},{"word":"mercari","structure":"mercari, mercatus sum (Latin verb)","meaning":"to trade","meaningCN":"做买卖","example":"The verb names the trade behind the market.","exampleCN":"这个动词指市场背后的交易。"},{"word":"market","structure":"market (English noun and verb)","meaning":"a place or demand for trade","meaningCN":"交易场所或需求","example":"The market decides what sells.","exampleCN":"市场决定什么卖得掉。"},{"word":"-able","structure":"-able (English suffix from Latin -abilis)","meaning":"able to be","meaningCN":"能够被……的","example":"The suffix turns a place into a capacity.","exampleCN":"这个后缀把场所变成一种能力。"},{"word":"marketable","structure":"market + -able","meaning":"able to be sold","meaningCN":"可销售的；有销路的","example":"The crop was marketable by June.","exampleCN":"这批作物到六月就能上市。"},{"word":"marketability","structure":"marketable + -ity (quality)","meaning":"the quality of being sellable","meaningCN":"可销售性","example":"Marketability depends on the buyer, not the maker.","exampleCN":"可销售性取决于买家，而非制造者。"},{"word":"unmarketable","structure":"un- + marketable","meaning":"not able to be sold","meaningCN":"无销路的","example":"The damaged stock was unmarketable.","exampleCN":"受损的存货卖不出去。"},{"word":"marketed","structure":"market + -ed (past participle)","meaning":"promoted for sale","meaningCN":"已推向市场的","example":"The device was marketed as a toy.","exampleCN":"这种设备被当作玩具推向市场。"},{"word":"marketing","structure":"market + -ing (activity)","meaning":"the work of promoting","meaningCN":"推广工作","example":"Marketing made the plain tool desirable.","exampleCN":"营销让这件普通工具变得令人想要。"}],"latinEntries":[{"word":"merx","structure":"merx, mercis (f., third declension)","meaning":"wares, goods","meaningCN":"货物；商品"},{"word":"mercari","structure":"mercari, mercatus sum (verb, first conjugation)","meaning":"to trade","meaningCN":"做买卖"},{"word":"mercatus","structure":"mercatus, mercatus (m., fourth declension)","meaning":"trade, marketplace","meaningCN":"贸易；市场"}],"derivatives":[{"word":"marketability","pos":"n.","zh":"可销售性；市场吸引力"},{"word":"unmarketable","pos":"adj.","zh":"无销路的；卖不掉的"},{"word":"market","pos":"v./n.","zh":"推销 / 市场"},{"word":"marketed","pos":"adj.","zh":"已推向市场的"},{"word":"marketing","pos":"n.","zh":"营销"}]}}]);
